project_files = {
    "cmd/etalon-server/main.go": "package main\n\nimport (\n\t\"etalon-server/internal/app\"\n\t\"flag\"\n\t\"log\"\n)\n\nfunc main() {\n\t// Обработка флагов командной строки\n\tseedFlag := flag.Bool(\"seed\", false, \"Наполнить базу данных тестовыми данными из файлов и выйти.\")\n\tflag.Parse()\n\n\t// Инициализация всего приложения\n\tapplication, err := app.New()\n\tif err != nil {\n\t\tlog.Fatalf(\"Не удалось инициализировать приложение: %v\", err)\n\t}\n\n\t// Если передан флаг --seed, запускаем наполнение и выходим\n\tif *seedFlag {\n\t\tapplication.SeedDBAndExit()\n\t}\n\n\t// Запуск сервера и фоновых сервисов в обычном режиме\n\tapplication.Run()\n}\n",
    "internal/api/dtos.go": "package api\n\nimport (\n\t\"encoding/json\"\n\t\"time\"\n)\n\n// --- DTO для CRUD, Задач и других операций ---\n\n// CompanyCreateDTO - DTO для создания/обновления компании.\ntype CompanyCreateDTO struct {\n\tTitle                 *string `json:\"title\"`\n\tAddress               *string `json:\"address\"`\n\tAdditionalName        *string `json:\"additional_name\"`\n\tParentServiceDeskUUID *string `json:\"parent_uuid\"`\n}\n\n// ResolveTaskRequestDTO - тело запроса для решения задачи.\ntype ResolveTaskRequestDTO struct {\n\tStatus            string                 `json:\"status\"` // 'resolved', 'rejected', 'pending_sd_action' и т.д.\n\tComment           string                 `json:\"comment,omitempty\"`\n\tResolutionPayload map[string]interface{} `json:\"resolution_payload,omitempty\"` // Данные для выполнения действия\n}\n\n// DuplicateGroupDTO представляет группу дубликатов для ответа API.\ntype DuplicateGroupDTO struct {\n\tField      string        `json:\"field\"`\n\tValue      string        `json:\"value\"`\n\tEntityType string        `json:\"entity_type\"`\n\tMainRecord interface{}   `json:\"main_record\"`\n\tDuplicates []interface{} `json:\"duplicates\"`\n}\n\n// ErrorResponseDTO стандартизированный ответ с ошибкой.\ntype ErrorResponseDTO struct {\n\tError string `json:\"error\"`\n}\n\n// --- DTO для взаимодействия с Агентами ---\n\n// LicenseInfo описывает одну лицензию из данных агента.\ntype LicenseInfo struct {\n\tName      string `json:\"name\"`\n\tDateFrom  string `json:\"dateFrom\"`\n\tDateUntil string `json:\"dateUntil\"`\n}\n\n// LicensesField - это специальный тип для поля 'licenses',\n// который может быть либо строкой (старый формат), либо картой (новый формат).\ntype LicensesField struct {\n\tStructured map[string]LicenseInfo\n\tLegacy     string\n}\n\n// UnmarshalJSON для кастомной обработки поля 'licenses'.\nfunc (lf *LicensesField) UnmarshalJSON(data []byte) error {\n\t// Сначала пытаемся распарсить как структурированный объект (карту).\n\tvar structured map[string]LicenseInfo\n\tif err := json.Unmarshal(data, &structured); err == nil {\n\t\tlf.Structured = structured\n\t\treturn nil\n\t}\n\n\t// Если не получилось, пытаемся распарсить как простую строку.\n\tvar legacy string\n\tif err := json.Unmarshal(data, &legacy); err == nil {\n\t\tlf.Legacy = legacy\n\t\treturn nil\n\t}\n\n\t// Если не удалось распарсить ни как карту, ни как строку, возвращаем ошибку.\n\t// Это может произойти, если в JSON, например, число или null.\n\treturn json.Unmarshal(data, &struct{}{}) // Возвращаем оригинальную ошибку парсинга\n}\n\n// MarshalJSON для кастомной сериализации поля 'licenses' обратно в простой JSON.\nfunc (lf LicensesField) MarshalJSON() ([]byte, error) {\n\tif lf.Structured != nil {\n\t\treturn json.Marshal(lf.Structured)\n\t}\n\t// Если Structured - nil, сериализуем Legacy (даже если это пустая строка).\n\treturn json.Marshal(lf.Legacy)\n}\n\n// AgentDataDTO определяет структуру данных, получаемых от агента.\ntype AgentDataDTO struct {\n\tModelName        string        `json:\"modelName\"`\n\tSerialNumber     string        `json:\"serialNumber\"`\n\tRNM              string        `json:\"RNM\"`\n\tINN              string        `json:\"INN\"`\n\tFNSerial         string        `json:\"fn_serial\"`\n\tDateTimeEnd      string        `json:\"dateTime_end\"`\n\tFFDVersion       string        `json:\"ffdVersion\"`\n\tFNExecution      string        `json:\"fnExecution\"`\n\tOrganizationName string        `json:\"organizationName\"`\n\tDateTimeReg      string        `json:\"datetime_reg\"`\n\tHostname         string        `json:\"hostname\"`\n\tURLRms           string        `json:\"url_rms\"`\n\tCRMID            string        `json:\"crmId\"`\n\tTeamviewerID     string        `json:\"teamviewer_id\"`\n\tAnydeskID        string        `json:\"anydesk_id\"`\n\tLitemanagerID    string        `json:\"litemanager_id\"`\n\tCurrentTime      string        `json:\"current_time\"`\n\tAgentVersion     string        `json:\"agent_version\"`\n\tInstalledDriver  string        `json:\"installed_driver,omitempty\"`\n\tBootVersion      string        `json:\"bootVersion,omitempty\"` // Версия прошивки (для FRFirmware)\n\tLicenses         LicensesField `json:\"licenses,omitempty\"`    // Используем кастомный тип\n\n\tAdditionalProperties map[string]interface{} `json:\"-\"`\n}\n\n// UnmarshalJSON для кастомной обработки JSON, чтобы собирать все неописанные поля.\nfunc (a *AgentDataDTO) UnmarshalJSON(data []byte) error {\n\ttype Alias AgentDataDTO\n\talias := &struct{ *Alias }{Alias: (*Alias)(a)}\n\tif err := json.Unmarshal(data, alias); err != nil {\n\t\treturn err\n\t}\n\n\tvar raw map[string]interface{}\n\tif err := json.Unmarshal(data, &raw); err != nil {\n\t\treturn err\n\t}\n\n\t// Удаляем из мапы те поля, которые уже были распарсены в основные поля структуры.\n\tdelete(raw, \"modelName\")\n\tdelete(raw, \"serialNumber\")\n\tdelete(raw, \"RNM\")\n\tdelete(raw, \"INN\")\n\tdelete(raw, \"fn_serial\")\n\tdelete(raw, \"dateTime_end\")\n\tdelete(raw, \"ffdVersion\")\n\tdelete(raw, \"fnExecution\")\n\tdelete(raw, \"organizationName\")\n\tdelete(raw, \"datetime_reg\")\n\tdelete(raw, \"hostname\")\n\tdelete(raw, \"url_rms\")\n\tdelete(raw, \"crmId\")\n\tdelete(raw, \"teamviewer_id\")\n\tdelete(raw, \"anydesk_id\")\n\tdelete(raw, \"litemanager_id\")\n\tdelete(raw, \"current_time\")\n\tdelete(raw, \"agent_version\")\n\tdelete(raw, \"installed_driver\")\n\tdelete(raw, \"bootVersion\")\n\tdelete(raw, \"licenses\")\n\n\ta.AdditionalProperties = raw\n\treturn nil\n}\n\n// RegistrationRequestDTO - тело запроса для регистрации нового агента.\ntype RegistrationRequestDTO struct {\n\tAgentUUID    string       `json:\"agent_uuid\"`\n\tHostname     string       `json:\"hostname\"`\n\tAgentVersion string       `json:\"agent_version\"`\n\tInitialData  AgentDataDTO `json:\"initial_data\"`\n}\n\n// AgentConfigDTO - структура конфигурации, отправляемая агенту.\ntype AgentConfigDTO struct {\n\tEtalonServerURL string            `json:\"etalon_server_url\"`\n\tMode            string            `json:\"mode\"`\n\tIntervals       IntervalsDTO      `json:\"intervals\"`\n\tZabbix          ZabbixConfigDTO   `json:\"zabbix\"`\n\tWorkstation     WorkstationCfgDTO `json:\"workstation,omitempty\"`\n}\n\ntype IntervalsDTO struct {\n\tHeartbeat        int `json:\"heartbeat_seconds\"`\n\tConfigCheck      int `json:\"config_check_seconds\"`\n\tWorkstationCheck int `json:\"workstation_check_seconds\"`\n\tUpdateCheck      int `json:\"update_check_seconds\"`\n}\n\ntype ZabbixConfigDTO struct {\n\tServerHost string `json:\"server_host\"`\n\tServerPort int    `json:\"server_port\"`\n\tHostname   string `json:\"hostname\"`\n}\n\ntype WorkstationCfgDTO struct {\n\tPrimaryJSONPath   string `json:\"primary_json_path\"`\n\tCashServerLogPath string `json:\"cash_server_log_path\"`\n}\n\n// --- DTO для аутентификации и пользователей ---\n\n// LoginRequestDTO - тело запроса для входа в систему.\ntype LoginRequestDTO struct {\n\tUsername string `json:\"username\" validate:\"required\"`\n\tPassword string `json:\"password\" validate:\"required\"`\n}\n\n// UserDTO - DTO для отображения информации о пользователе.\ntype UserDTO struct {\n\tID       uint     `json:\"id\"`\n\tUsername string   `json:\"username\"`\n\tFullName string   `json:\"fullName\"`\n\tRoles    []string `json:\"roles\"`\n}\n\n// LoginResponseDTO - тело ответа при успешном входе.\ntype LoginResponseDTO struct {\n\tAccessToken string  `json:\"access_token\"`\n\tUser        UserDTO `json:\"user\"`\n}\n\n// UserCreateDTO - DTO для создания нового пользователя.\ntype UserCreateDTO struct {\n\tUsername string   `json:\"username\" validate:\"required\"`\n\tPassword string   `json:\"password\" validate:\"required,min=6\"`\n\tFullName string   `json:\"fullName\" validate:\"required\"`\n\tRoles    []string `json:\"roles\" validate:\"required\"`\n}\n\n// UserUpdateDTO - DTO для обновления пользователя.\ntype UserUpdateDTO struct {\n\tPassword *string  `json:\"password,omitempty\" validate:\"omitempty,min=6\"`\n\tFullName *string  `json:\"fullName,omitempty\"`\n\tRoles    []string `json:\"roles,omitempty\"`\n}\n\n// --- DTO для UI-ориентированного поиска ---\n\n// FinalSearchResponseDTO - корневой объект для нового ответа поиска.\ntype FinalSearchResponseDTO struct {\n\tSearchResults []SearchGroupDTO `json:\"search_results\"`\n}\n\n// SearchGroupDTO представляет одну группу в результатах поиска (сущности, сгруппированные по владельцу).\ntype SearchGroupDTO struct {\n\tOwner         OwnerFullDTO     `json:\"owner\"`\n\tFoundEntities []FoundEntityDTO `json:\"found_entities\"`\n}\n\n// OwnerFullDTO содержит расширенную информацию о компании-владельце.\ntype OwnerFullDTO struct {\n\tUUID           string  `json:\"uuid\"`\n\tExternalUUID   *string `json:\"externalUUID,omitempty\"`\n\tName           string  `json:\"name\"`\n\tAddress        *string `json:\"address,omitempty\"`\n\tActiveContract *bool   `json:\"active_contract,omitempty\"`\n\tAdditionalInfo *string `json:\"additional_info,omitempty\"`\n}\n\n// FoundEntityDTO представляет одну найденную сущность внутри группы.\ntype FoundEntityDTO struct {\n\tEntityType string      `json:\"entity_type\"`\n\tData       interface{} `json:\"data\"`\n}\n\n// --- DTO для данных внутри FoundEntityDTO ---\n\n// ServerRichDTO содержит полный набор полей Сервера для UI.\ntype ServerRichDTO struct {\n\tUUID         string  `json:\"uuid\"`                   // Внутренний ID\n\tExternalUUID *string `json:\"externalUUID,omitempty\"` // Внешний ID (для ссылок)\n\tDeviceName   *string `json:\"device_name,omitempty\"`\n\tIP           *string `json:\"ip,omitempty\"`\n\tStatus       string  `json:\"status,omitempty\"`\n\tAnydesk      *string `json:\"anydesk,omitempty\"`\n\tTeamviewer   *string `json:\"teamviewer,omitempty\"`\n\tRDP          *string `json:\"rdp,omitempty\"`\n\tLitemanager  *string `json:\"litemanager,omitempty\"`\n\tUniqueID     *string `json:\"unique_id,omitempty\"`\n\tPartnersLink *string `json:\"partners_link,omitempty\"`\n}\n\n// WorkstationRichDTO содержит полный набор полей Рабочей станции для UI.\n// WorkstationRichDTO содержит полный набор полей Рабочей станции для UI.\ntype WorkstationRichDTO struct {\n\tUUID         string  `json:\"uuid\"`\n\tExternalUUID *string `json:\"externalUUID,omitempty\"`\n\tDeviceName   *string `json:\"device_name,omitempty\"`\n\tStatus       *string `json:\"status,omitempty\"`\n\tAnydesk      *string `json:\"anydesk,omitempty\"`\n\tTeamviewer   *string `json:\"teamviewer,omitempty\"`\n\tLitemanager  *string `json:\"litemanager,omitempty\"`\n}\n\n// FiscalRegisterRichDTO содержит полный набор полей Фискального регистратора для UI.\ntype FiscalRegisterRichDTO struct {\n\tUUID               string     `json:\"uuid\"`\n\tExternalUUID       *string    `json:\"externalUUID,omitempty\"`\n\tStatus             *string    `json:\"status,omitempty\"`\n\tRNKKT              *string    `json:\"rn_kkt,omitempty\"`\n\tModelKKT           *string    `json:\"model_kkt,omitempty\"`\n\tFNRegistrationDate *time.Time `json:\"fn_registration_date,omitempty\"`\n\tFNExpireDate       *time.Time `json:\"fn_expire_date,omitempty\"`\n\tDriverVersion      *string    `json:\"driver_version,omitempty\"`\n\tFRFirmware         *string    `json:\"fr_firmware,omitempty\"`\n\tFRDownloader       *string    `json:\"fr_downloader,omitempty\"`\n\tOrganizationName   *string    `json:\"organization_name,omitempty\"`\n\tINN                *string    `json:\"inn,omitempty\"`\n\tSerialNumber       *string    `json:\"serial_number,omitempty\"`\n\tIsMarkingActive    bool       `json:\"is_marking_active\"`\n\tIsExciseActive     bool       `json:\"is_excise_active\"`\n}\n\n// TaskDTO - DTO для отображения задачи в UI.\ntype TaskDTO struct {\n\tID         uint        `json:\"id\"`\n\tTaskType   string      `json:\"task_type\"`\n\tEntityType string      `json:\"entity_type\"`\n\tEntityUUID string      `json:\"entity_uuid\"` // Может быть внутренним ID или другим идентификатором (СН)\n\tDetails    interface{} `json:\"details\"`\n\tStatus     string      `json:\"status\"`\n\tComment    string      `json:\"comment\"`\n\tCreatedAt  time.Time   `json:\"created_at\"`\n\tUpdatedAt  time.Time   `json:\"updated_at\"`\n}\n\n// CreateEntityInSDRequestDTO - тело запроса для создания сущности в ServiceDesk по задаче.\ntype CreateEntityInSDRequestDTO struct {\n\tEntityType string `json:\"entity_type\" validate:\"required\"` // 'FiscalRegister', 'Workstation', 'Server'\n}\n\n// AcceptedResponseDTO - стандартный ответ для асинхронных операций.\ntype AcceptedResponseDTO struct {\n\tMessage string `json:\"message\"`\n\tTaskID  uint   `json:\"task_id\"`\n}\n",
    "internal/app/app.go": "// internal/app/app.go\npackage app\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/db\"\n\t\"etalon-server/internal/gateways\"\n\t\"etalon-server/internal/handlers\"\n\t\"etalon-server/internal/logger\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/plugins/naumen\"\n\t\"etalon-server/internal/processing\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/seeder\"\n\t\"etalon-server/internal/services\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/internal/workers\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"os/signal\"\n\t\"sync\"\n\t\"syscall\"\n\t\"time\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"github.com/go-chi/chi/v5/middleware\"\n\t\"github.com/go-chi/cors\"\n\t\"go.uber.org/zap\"\n\t\"gorm.io/datatypes\"\n\t\"gorm.io/gorm\"\n)\n\n// Application хранит все зависимости приложения (DI-контейнер).\ntype Application struct {\n\tConfig               *config.Config\n\tLogger               *zap.Logger\n\tDB                   *gorm.DB\n\tProcessingEngine     processing.ProcessingEngine\n\tEventBus             eventbus.EventBus\n\tOrchestrator         *processing.Orchestrator\n\tSDeskGateway         gateways.ServiceDeskGateway\n\tDuplicatesGateway    gateways.DuplicatesGateway\n\tPollingGateway       gateways.ServerPollingGateway\n\tAgentFTPGateway      gateways.AgentFTPGateway\n\tSeeder               *seeder.Seeder\n\tCrudHandler          *handlers.CrudHandler\n\tSearchHandler        *handlers.SearchHandler\n\tSyncHandler          *handlers.SyncHandler\n\tTaskHandler          *handlers.TaskHandler\n\tAgentHandler         *handlers.AgentHandler\n\tServerActionsHandler *handlers.ServerActionsHandler\n\tAuthHandler          *handlers.AuthHandler\n\tServerActionsSvc     services.ServerActionsService\n\tAuthSvc              services.AuthService\n\tAgentSvc             services.AgentService\n\tSDEditorSvc          services.SDEditorService\n\tFRUpdateFounder      workers.FRUpdateFounder\n\tDebugHandler         *handlers.DebugHandler\n}\n\n// New создает и инициализирует новый экземпляр Application.\nfunc New() (*Application, error) {\n\tcfg := config.New()\n\n\tappLogger := logger.New(cfg.LogDir, \"app\", cfg.LogLevel, cfg.DisableFileLogging)\n\tappLogger.Info(\"Инициализация приложения etalon-server...\")\n\n\tif err := os.MkdirAll(cfg.FTPCachePath, 0755); err != nil {\n\t\tappLogger.Fatal(\"Не удалось создать директорию для кэша FTP\", zap.Error(err))\n\t}\n\n\tdatabase, err := db.NewConnection(cfg)\n\tif err != nil {\n\t\tappLogger.Fatal(\"Не удалось подключиться к базе данных\", zap.Error(err))\n\t\treturn nil, err\n\t}\n\tappLogger.Info(\"Подключение к базе данных установлено\")\n\n\tappLogger.Info(\"Запуск миграций базы данных...\")\n\terr = database.AutoMigrate(\n\t\t&models.Company{}, &models.Server{}, &models.Workstation{},\n\t\t&models.FiscalRegister{}, &models.AgentFile{}, &models.ReconciliationTask{},\n\t\t&models.Agent{}, &models.Contract{}, &models.CompanyContract{},\n\t\t&models.User{}, &models.ExternalSystemLink{},\n\t)\n\tif err != nil {\n\t\tappLogger.Fatal(\"Не удалось выполнить миграцию схемы БД\", zap.Error(err))\n\t\treturn nil, err\n\t}\n\tappLogger.Info(\"Миграции базы данных успешно завершены.\")\n\n\tif err := seedAdminUser(cfg, database, appLogger); err != nil {\n\t\tappLogger.Fatal(\"Не удалось создать пользователя-администратора\", zap.Error(err))\n\t\treturn nil, err\n\t}\n\n\tbus := eventbus.NewInMemoryEventBus(1000)\n\n\t// Репозитории\n\tcompanyRepo := repositories.NewCompanyRepo(database)\n\tserverRepo := repositories.NewServerRepo(database)\n\tworkstationRepo := repositories.NewWorkstationRepo(database)\n\tfrRepo := repositories.NewFiscalRegisterRepo(database)\n\tagentRepo := repositories.NewAgentRepo(database)\n\tcontractRepo := repositories.NewContractRepo(database)\n\ttaskRepo := repositories.NewTaskRepo(database)\n\tuserRepo := repositories.NewUserRepo(database)\n\tlinkRepo := repositories.NewLinkRepo(database)\n\n\t// Логгеры\n\tsdeskGatewayLogger := logger.New(cfg.LogDir, \"sdesk_gateway\", cfg.LogLevel, cfg.DisableFileLogging)\n\torchestratorLogger := logger.New(cfg.LogDir, \"orchestrator\", cfg.LogLevel, cfg.DisableFileLogging)\n\tserverPollingLogger := logger.New(cfg.LogDir, \"server_polling\", cfg.LogLevel, cfg.DisableFileLogging)\n\treconcilerLogger := logger.New(cfg.LogDir, \"reconciler\", cfg.LogLevel, cfg.DisableFileLogging)\n\tduplicatesLogger := logger.New(cfg.LogDir, \"duplicates_gateway\", cfg.LogLevel, cfg.DisableFileLogging)\n\tsdEditorLogger := logger.New(cfg.LogDir, \"sdesk_editor\", cfg.LogLevel, cfg.DisableFileLogging)\n\tfrUpdateFounderLogger := logger.New(cfg.LogDir, \"fr_update_founder\", cfg.LogLevel, cfg.DisableFileLogging)\n\n\t// Сервисы, шлюзы и оркестратор\n\tsdClient := naumen.NewNaumenClient(cfg, appLogger, database, linkRepo)\n\tftpClient := services.NewFTPClient(cfg, appLogger)\n\trmsClient := utils.NewRMSClient(cfg.RequestTimeout, appLogger)\n\tagentService := services.NewAgentService(appLogger, agentRepo, companyRepo, database, bus)\n\tauthService := services.NewAuthService(cfg, userRepo)\n\ttaskResolutionService := services.NewTaskResolutionService(appLogger, database, bus, taskRepo, serverRepo, workstationRepo, frRepo)\n\tdbSeeder := seeder.NewSeeder(appLogger, database, companyRepo, serverRepo, workstationRepo, frRepo, contractRepo)\n\tsdEditorService := services.NewSDEditorService(sdEditorLogger, database, bus, sdClient, taskRepo, linkRepo, companyRepo, serverRepo, workstationRepo, frRepo)\n\tprocessingEngine := processing.NewProcessingEngine(appLogger, serverRepo, workstationRepo, frRepo, companyRepo, taskRepo, services.NewEntityMatcherService(appLogger, serverRepo, workstationRepo, frRepo))\n\n\tsdeskGateway := gateways.NewServiceDeskGateway(cfg, sdClient, bus, sdeskGatewayLogger, database, companyRepo, serverRepo, workstationRepo, frRepo)\n\tduplicatesGateway := gateways.NewDuplicatesGateway(cfg, database, bus, duplicatesLogger)\n\tpollingGateway := gateways.NewServerPollingGateway(cfg, serverPollingLogger, serverRepo, rmsClient, bus)\n\tagentFTPGateway := gateways.NewAgentFTPGateway(cfg, reconcilerLogger, database, ftpClient, bus)\n\n\t// ВАЖНО: Конструктор Оркестратора пока остается старым! Мы отрефакторим его на следующем шаге.\n\torchestrator := processing.NewOrchestrator(orchestratorLogger, database, bus, sdClient, companyRepo, serverRepo, workstationRepo, frRepo, taskRepo, linkRepo, processingEngine)\n\n\tserverActionsSvc := services.NewServerActionsService(appLogger, bus, serverRepo, companyRepo, database)\n\tfrUpdateFounder := workers.NewFRUpdateFounder(cfg, frUpdateFounderLogger, bus, frRepo, linkRepo, sdClient)\n\n\t// Обработчики\n\tcrudHandler := handlers.NewCrudHandler(appLogger, database, companyRepo, serverRepo, workstationRepo, frRepo)\n\tsearchHandler := handlers.NewSearchHandler(appLogger, companyRepo, serverRepo, workstationRepo, frRepo, linkRepo)\n\tsyncHandler := handlers.NewSyncHandler(appLogger, dbSeeder, cfg.SeederKey)\n\ttaskHandler := handlers.NewTaskHandler(appLogger, database, taskResolutionService, sdEditorService, serverRepo, workstationRepo, frRepo, linkRepo)\n\tagentHandler := handlers.NewAgentHandler(appLogger, agentService)\n\tserverActionsHandler := handlers.NewServerActionsHandler(appLogger, serverActionsSvc)\n\tauthHandler := handlers.NewAuthHandler(appLogger, authService)\n\tdebugHandler := handlers.NewDebugHandler(appLogger, bus)\n\n\treturn &Application{\n\t\tConfig:               cfg,\n\t\tLogger:               appLogger,\n\t\tDB:                   database,\n\t\tProcessingEngine:     processingEngine,\n\t\tEventBus:             bus,\n\t\tOrchestrator:         orchestrator,\n\t\tSDeskGateway:         sdeskGateway,\n\t\tDuplicatesGateway:    duplicatesGateway,\n\t\tPollingGateway:       pollingGateway,\n\t\tAgentFTPGateway:      agentFTPGateway,\n\t\tSeeder:               dbSeeder,\n\t\tCrudHandler:          crudHandler,\n\t\tSearchHandler:        searchHandler,\n\t\tSyncHandler:          syncHandler,\n\t\tTaskHandler:          taskHandler,\n\t\tAgentHandler:         agentHandler,\n\t\tServerActionsHandler: serverActionsHandler,\n\t\tAuthHandler:          authHandler,\n\t\tAuthSvc:              authService,\n\t\tServerActionsSvc:     serverActionsSvc,\n\t\tAgentSvc:             agentService,\n\t\tSDEditorSvc:          sdEditorService,\n\t\tFRUpdateFounder:      frUpdateFounder,\n\t\tDebugHandler:         debugHandler,\n\t}, nil\n}\n\n// Run запускает приложение (HTTP-сервер и фоновые службы).\nfunc (a *Application) Run() {\n\tdefer a.Logger.Sync()\n\n\tr := chi.NewRouter()\n\n\tcorsMiddleware := cors.New(cors.Options{\n\t\tAllowedOrigins:   a.Config.AllowedOrigins,\n\t\tAllowedMethods:   []string{\"GET\", \"POST\", \"PUT\", \"DELETE\", \"OPTIONS\"},\n\t\tAllowedHeaders:   []string{\"Accept\", \"Authorization\", \"Content-Type\", \"X-CSRF-Token\"},\n\t\tAllowCredentials: true,\n\t\tMaxAge:           300,\n\t})\n\tr.Use(corsMiddleware.Handler)\n\n\tr.Use(middleware.RequestID, middleware.RealIP, middleware.Logger, middleware.Recoverer)\n\tr.Use(middleware.Timeout(60 * time.Second))\n\t// Публичные роуты для аутентификации\n\tr.Route(\"/api/auth\", func(r chi.Router) {\n\t\ta.AuthHandler.RegisterRoutes(r)\n\t})\n\n\t// Роуты для агентов со своей аутентификацией\n\tr.Route(\"/api/agents\", func(r chi.Router) {\n\t\tr.Use(handlers.AgentAuthMiddleware(a.Config.AgentAPIKey))\n\t\ta.AgentHandler.RegisterRoutes(r)\n\t})\n\n\t// Защищенная группа роутов для UI\n\tr.Route(\"/api\", func(r chi.Router) {\n\t\t// Применяем middleware для проверки JWT\n\t\tr.Use(handlers.JwtAuthMiddleware(a.Config))\n\n\t\t// Регистрируем все защищенные хендлеры\n\t\ta.CrudHandler.RegisterRoutes(r)\n\t\ta.SearchHandler.RegisterRoutes(r)\n\t\ta.TaskHandler.RegisterRoutes(r)\n\t\ta.ServerActionsHandler.RegisterRoutes(r)\n\n\t\t// Пример группы роутов только для админов\n\t\tr.Route(\"/users\", func(r chi.Router) {\n\t\t\tr.Use(handlers.AdminRequiredMiddleware)\n\t\t\t// Здесь будут регистрироваться роуты для UserHandler\n\t\t\t// a.UserHandler.RegisterRoutes(r)\n\t\t})\n\t})\n\tr.Route(\"/sync\", func(r chi.Router) {\n\t\ta.SyncHandler.RegisterRoutes(r)\n\t})\n\tr.Route(\"/debug\", func(r chi.Router) {\n\t\ta.DebugHandler.RegisterRoutes(r)\n\t})\n\tr.Get(\"/\", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Write([]byte(\"Welcome to Etalon Server\"))\n\t})\n\n\tserver := &http.Server{\n\t\tAddr:    \":\" + a.Config.ServerPort,\n\t\tHandler: r,\n\t}\n\n\tmainCtx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)\n\tdefer stop()\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// --- Запуск компонентов новой архитектуры ---\n\t// Шина событий\n\tgo func() { defer wg.Done(); a.EventBus.Start(mainCtx, a.Logger) }()\n\n\t// Оркестратор (он только подписывается, активной работы не ведет)\n\ta.Orchestrator.Start(mainCtx)\n\ta.SDEditorSvc.Start(mainCtx)\n\n\t// Шлюз поиска дубликатов\n\tif a.Config.EnableDuplicatesGateway {\n\t\twg.Add(1)\n\t\tgo func() { defer wg.Done(); a.DuplicatesGateway.Start(mainCtx) }()\n\t} else {\n\t\ta.Logger.Info(\"Шлюз поиска дубликатов отключен в конфигурации.\")\n\t}\n\n\t// Воркер поиска обновлений для ФР\n\tif a.Config.EnableFRDiscrepancyFinder {\n\t\twg.Add(1)\n\t\tgo func() { defer wg.Done(); a.FRUpdateFounder.Start(mainCtx) }()\n\t} else {\n\t\ta.Logger.Info(\"Воркер поиска обновлений для ФР (FRUpdateFounder) отключен в конфигурации.\")\n\t}\n\n\t// Шлюз для данных от агентов (FTP)\n\tif a.Config.EnableAgentFTPGateway {\n\t\twg.Add(1)\n\t\tgo func() { defer wg.Done(); a.AgentFTPGateway.Start(mainCtx) }()\n\t} else {\n\t\ta.Logger.Info(\"Шлюз агентов (FTP) отключен в конфигурации.\")\n\t}\n\n\t// Шлюз опроса статусов серверов\n\tif a.Config.EnablePollingGateway {\n\t\twg.Add(1)\n\t\tgo func() { defer wg.Done(); a.PollingGateway.Start(mainCtx) }()\n\t} else {\n\t\ta.Logger.Info(\"Шлюз опроса статусов серверов отключен в конфигурации.\")\n\t}\n\n\t// Шлюз синхронизации сущностей с ServiceDesk\n\tif a.Config.EnableSDeskGateway {\n\t\twg.Add(1)\n\t\tgo func() { defer wg.Done(); a.SDeskGateway.Start(mainCtx) }()\n\t} else {\n\t\ta.Logger.Info(\"Шлюз синхронизации сущностей с ServiceDesk отключен в конфигурации.\")\n\t}\n\n\t// HTTP-сервер\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ta.Logger.Info(fmt.Sprintf(\"Сервер запущен и слушает порт %s\", a.Config.ServerPort))\n\t\tif err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {\n\t\t\ta.Logger.Error(\"Не удалось запустить сервер\", zap.String(\"port\", a.Config.ServerPort), zap.Error(err))\n\t\t\tstop()\n\t\t}\n\t}()\n\n\t<-mainCtx.Done()\n\n\ta.Logger.Info(\"Получен сигнал завершения. Начинаю остановку...\")\n\n\tshutdownCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)\n\tdefer cancel()\n\n\tif err := server.Shutdown(shutdownCtx); err != nil {\n\t\ta.Logger.Fatal(\"Принудительная остановка сервера:\", zap.Error(err))\n\t}\n\n\twg.Wait()\n\ta.Logger.Info(\"Приложение успешно завершило работу.\")\n}\n\n// SeedDBAndExit выполняет наполнение БД и завершает работу.\nfunc (a *Application) SeedDBAndExit() {\n\ta.Logger.Info(\"Запуск в режиме наполнения базы данных (seeding)...\")\n\tmockClient := seeder.NewMockServiceDeskClient(a.Logger, \"./tools/seeder/mock_data\")\n\tif err := a.Seeder.SeedDatabase(mockClient); err != nil {\n\t\ta.Logger.Fatal(\"Ошибка при наполнении базы данных\", zap.Error(err))\n\t}\n\ta.Logger.Info(\"Наполнение базы данных успешно завершено. Программа завершает работу.\")\n\tos.Exit(0)\n}\n\n// Новая функция для сидинга админа\nfunc seedAdminUser(cfg *config.Config, db *gorm.DB, logger *zap.Logger) error {\n\tvar count int64\n\tdb.Model(&models.User{}).Where(\"username = ?\", cfg.AdminUsername).Count(&count)\n\n\tif count > 0 {\n\t\tlogger.Info(\"Пользователь-администратор уже существует, пропуск создания.\")\n\t\treturn nil\n\t}\n\n\tlogger.Info(\"Создание пользователя-администратора по умолчанию...\")\n\trolesJSON, _ := json.Marshal([]string{\"admin\"})\n\tadmin := &models.User{\n\t\tUsername: cfg.AdminUsername,\n\t\tFullName: cfg.AdminFullName,\n\t\tRoles:    datatypes.JSON(rolesJSON),\n\t}\n\tif err := admin.HashPassword(cfg.AdminPassword); err != nil {\n\t\treturn err\n\t}\n\n\tif err := db.Create(admin).Error; err != nil {\n\t\treturn err\n\t}\n\n\tlogger.Info(\"Пользователь-администратор успешно создан.\", zap.String(\"username\", cfg.AdminUsername))\n\treturn nil\n}\n",
    "internal/config/config.go": "// internal/config/config.go\npackage config\n\nimport (\n\t\"log\"\n\t\"os\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n\n\t\"github.com/joho/godotenv\"\n)\n\n// Config хранит всю конфигурацию приложения.\n// Значения считываются из переменных окружения или из файла .env.\ntype Config struct {\n\t// --- Общие настройки ---\n\tServerPort         string\n\tDatabaseURL        string\n\tLogDir             string\n\tLogLevel           string\n\tDisableFileLogging bool\n\tRequestTimeout     time.Duration\n\tAllowedOrigins     []string\n\n\t// --- Настройки API ---\n\tAgentAPIKey      string\n\tSeederKey        string\n\tJWTSecret        string\n\tJWTExpirationMin int\n\tAdminUsername    string\n\tAdminPassword    string\n\tAdminFullName    string\n\n\t// --- Настройки ServiceDesk Client ---\n\tServiceDeskBaseURL string\n\tServiceDeskKey     string\n\tRateLimit          int\n\tMaxRetries         int\n\tConcurrentRequests int\n\tServiceDeskDryRun  bool\n\n\t// --- Настройки фоновых шлюзов (Gateways) ---\n\n\t// Шлюз синхронизации с ServiceDesk (сущности)\n\tEnableSDeskGateway bool\n\tSDeskSyncInterval  time.Duration\n\n\t// Шлюз синхронизации контрактов\n\tEnableContractGateway bool\n\tContractSyncInterval  time.Duration\n\n\t// Шлюз опроса статусов серверов (RMS Polling)\n\tEnablePollingGateway   bool\n\tServerPollingInterval  time.Duration\n\tServerPollingBatchSize int\n\tRMSLogin               string\n\tRMSPassword1           string\n\tRMSPassword2           string\n\n\t// Шлюз для данных от агентов (FTP)\n\tEnableAgentFTPGateway bool\n\tAgentFTPInterval      time.Duration // Бывший ReconcileInterval\n\tFTPHost               string\n\tFTPUser               string\n\tFTPPassword           string\n\tFTPPort               string\n\tFTPPath               string\n\tFTPCachePath          string\n\n\t// Шлюз поиска дубликатов\n\tEnableDuplicatesGateway  bool\n\tDuplicatesSearchInterval time.Duration\n\n\t// --- Настройки фоновых воркеров ---\n\n\t// Воркер поиска расхождений для ФР\n\tEnableFRDiscrepancyFinder  bool\n\tFRDiscrepancyCheckInterval time.Duration\n}\n\n// New загружает конфигурацию из файла .env и переменных окружения.\nfunc New() *Config {\n\tif err := godotenv.Load(); err != nil {\n\t\tlog.Println(\"No .env file found, using environment variables\")\n\t}\n\n\tallowedOriginsStr := getEnv(\"ALLOWED_ORIGINS\", \"http://localhost:5173\")\n\n\treturn &Config{\n\t\t// Общие\n\t\tServerPort:         getEnv(\"PORT\", \"8080\"),\n\t\tDatabaseURL:        getEnv(\"DATABASE_URL\", \"postgres://user:password@localhost:5432/etalon_db?sslmode=disable\"),\n\t\tLogDir:             getEnv(\"LOG_DIR\", \"./logs\"),\n\t\tLogLevel:           getEnv(\"LOG_LEVEL\", \"info\"),\n\t\tDisableFileLogging: getEnvAsBool(\"DISABLE_FILE_LOGGING\", false),\n\t\tRequestTimeout:     time.Duration(getEnvAsInt(\"REQUEST_TIMEOUT_SEC\", 15)) * time.Second,\n\t\tAllowedOrigins:     strings.Split(allowedOriginsStr, \",\"),\n\n\t\t// API\n\t\tAgentAPIKey:      getEnv(\"AGENT_API_KEY\", \"\"),\n\t\tSeederKey:        getEnv(\"SEEDER_KEY\", \"super-secret-key-for-seeding\"),\n\t\tJWTSecret:        getEnv(\"JWT_SECRET\", \"mhrcadmin994525\"),\n\t\tJWTExpirationMin: getEnvAsInt(\"JWT_EXPIRATION_MIN\", 1440), // 24 часа\n\t\tAdminUsername:    getEnv(\"ADMIN_USERNAME\", \"admin\"),\n\t\tAdminPassword:    getEnv(\"ADMIN_PASSWORD\", \"mhrcadmin994525\"),\n\t\tAdminFullName:    getEnv(\"ADMIN_FULLNAME\", \"Главный\"),\n\n\t\t// ServiceDesk Client\n\t\tServiceDeskBaseURL: getEnv(\"BASE_URL\", \"https://servicedesk.example.com\"),\n\t\tServiceDeskKey:     getEnv(\"SDKEY\", \"\"),\n\t\tRateLimit:          getEnvAsInt(\"RATE_LIMIT\", 45),\n\t\tMaxRetries:         getEnvAsInt(\"MAX_RETRIES\", 3),\n\t\tConcurrentRequests: getEnvAsInt(\"CONCURRENT_REQUESTS\", 10),\n\t\tServiceDeskDryRun:  getEnvAsBool(\"SD_DRY_RUN\", false),\n\n\t\t// --- Шлюзы ---\n\n\t\t// ServiceDesk Gateway\n\t\tEnableSDeskGateway: getEnvAsBool(\"ENABLE_SDESK_GATEWAY\", true),\n\t\tSDeskSyncInterval:  time.Duration(getEnvAsInt(\"SDESK_SYNC_INTERVAL_MIN\", 10)) * time.Minute,\n\n\t\t// Contract Gateway\n\t\tEnableContractGateway: getEnvAsBool(\"ENABLE_CONTRACT_GATEWAY\", true),\n\t\tContractSyncInterval:  time.Duration(getEnvAsInt(\"CONTRACT_SYNC_INTERVAL_MIN\", 30)) * time.Minute,\n\n\t\t// Server Polling Gateway\n\t\tEnablePollingGateway:   getEnvAsBool(\"ENABLE_POLLING_GATEWAY\", true),\n\t\tServerPollingInterval:  time.Duration(getEnvAsInt(\"SERVER_POLLING_INTERVAL_HOURS\", 12)) * time.Hour,\n\t\tServerPollingBatchSize: getEnvAsInt(\"SERVER_POLLING_BATCH_SIZE\", 50),\n\t\tRMSLogin:               getEnv(\"RMS_LOGIN\", \"\"),\n\t\tRMSPassword1:           getEnv(\"RMS_PASSWORD_1\", \"\"),\n\t\tRMSPassword2:           getEnv(\"RMS_PASSWORD_2\", \"\"),\n\n\t\t// Agent FTP Gateway\n\t\tEnableAgentFTPGateway: getEnvAsBool(\"ENABLE_AGENT_FTP_GATEWAY\", true),\n\t\tAgentFTPInterval:      time.Duration(getEnvAsInt(\"AGENT_FTP_INTERVAL_MIN\", 60)) * time.Minute,\n\t\tFTPHost:               getEnv(\"FTP_HOST\", \"localhost\"),\n\t\tFTPUser:               getEnv(\"FTP_USER\", \"user\"),\n\t\tFTPPassword:           getEnv(\"FTP_PASSWORD\", \"password\"),\n\t\tFTPPort:               getEnv(\"FTP_PORT\", \"21\"),\n\t\tFTPPath:               getEnv(\"FTP_PATH\", \"/\"),\n\t\tFTPCachePath:          getEnv(\"FTP_CACHE_PATH\", \"./ftp_cache\"),\n\n\t\t// Duplicates Gateway\n\t\tEnableDuplicatesGateway:  getEnvAsBool(\"ENABLE_DUPLICATES_GATEWAY\", true),\n\t\tDuplicatesSearchInterval: time.Duration(getEnvAsInt(\"DUPLICATES_SEARCH_INTERVAL_HOURS\", 24)) * time.Hour, // Раз в сутки по умолчанию\n\n\t\t// --- Воркеры ---\n\t\t// FR Discrepancy Finder\n\t\tEnableFRDiscrepancyFinder:  getEnvAsBool(\"ENABLE_FR_DISCREPANCY_FINDER\", true),\n\t\tFRDiscrepancyCheckInterval: time.Duration(getEnvAsInt(\"FR_DISCREPANCY_CHECK_INTERVAL_HOURS\", 6)) * time.Hour, // Раз в 6 часов\n\n\t}\n}\n\n// Вспомогательная функция для получения переменной окружения с значением по умолчанию.\nfunc getEnv(key, fallback string) string {\n\tif value, ok := os.LookupEnv(key); ok {\n\t\treturn value\n\t}\n\treturn fallback\n}\n\n// Вспомогательная функция для получения int из переменной окружения.\nfunc getEnvAsInt(key string, fallback int) int {\n\tif valueStr := getEnv(key, \"\"); valueStr != \"\" {\n\t\tif value, err := strconv.Atoi(valueStr); err == nil {\n\t\t\treturn value\n\t\t}\n\t}\n\treturn fallback\n}\n\n// Вспомогательная функция для получения bool из переменной окружения.\nfunc getEnvAsBool(key string, fallback bool) bool {\n\tif valueStr := getEnv(key, \"\"); valueStr != \"\" {\n\t\tif value, err := strconv.ParseBool(valueStr); err == nil {\n\t\t\treturn value\n\t\t}\n\t}\n\treturn fallback\n}\n",
    "internal/contextkeys/keys.go": "package contextkeys\n\n// ContextKey - тип для ключей контекста, чтобы избежать коллизий.\ntype ContextKey string\n\n// Константы для ключей, используемых в context.Context для передачи данных между middleware и сервисами.\nconst (\n\tUserRolesContextKey ContextKey = \"userRoles\"\n\tUserIDContextKey    ContextKey = \"userID\"\n)\n",
    "internal/core/events/events.go": "package events\n\nimport (\n\t\"etalon-server/internal/api\"\n\t\"time\"\n)\n\n// Константы для типов событий.\nconst (\n\t// ContractsStatusRecalculated событие возникает, когда шлюз контрактов завершил синхронизацию и пересчет статусов.\n\tContractsStatusRecalculated = \"contracts.status.recalculated\"\n\n\t// ServiceDeskEntityUpdated событие возникает, когда из ServiceDesk получены обновленные данные о сущности.\n\tServiceDeskEntityUpdated = \"servicedesk.entity.updated\"\n\n\t// ServiceDeskEntityDeleted событие возникает, когда сущность была удалена в ServiceDesk.\n\tServiceDeskEntityDeleted = \"servicedesk.entity.deleted\"\n\n\t// AgentDataReceived событие возникает, когда от агента (по API или через FTP) получены данные.\n\tAgentDataReceived = \"agent.data.received\"\n\n\t// DuplicatesFound событие возникает, когда воркер поиска обнаружил дубликаты.\n\tDuplicatesFound = \"duplicates.found\"\n\n\t// ServerPollingSucceeded событие возникает при успешном опросе статуса сервера.\n\tServerPollingSucceeded = \"server.polling.succeeded\"\n\t// ServerPollingFailed событие возникает при неудачном опросе статуса сервера.\n\tServerPollingFailed = \"server.polling.failed\"\n\t// ServerPollingRequested событие для ручного запуска опроса одного сервера.\n\tServerPollingRequested = \"server.polling.requested\"\n\n\t// ServiceDeskCreateRequested событие для асинхронного создания сущности в ServiceDesk.\n\tServiceDeskCreateRequested = \"servicedesk.entity.create.requested\"\n\t// ServiceDeskUpdateRequested событие для асинхронного обновления сущности в ServiceDesk.\n\tServiceDeskUpdateRequested = \"servicedesk.entity.update.requested\"\n\t// FiscalRegisterDiscrepancyFound событие возникает, когда воркер обнаружил расхождение данных ФР.\n\tFiscalRegisterDiscrepancyFound = \"discrepancy.fiscal_register.found\"\n)\n\n// ServiceDeskEntityPayload - полезная нагрузка для события ServiceDeskEntityUpdated.\n// Содержит сырые данные из внешней системы.\ntype ServiceDeskEntityPayload struct {\n\tEntityType   string                 // Внутренний тип сущности: \"Company\", \"Server\"\n\tExternalUUID string                 // UUID сущности во внешней системе\n\tData         map[string]interface{} // Полные данные сущности, полученные от внешней системы\n}\n\n// ServiceDeskEntityDeletePayload - полезная нагрузка для события ServiceDeskEntityDeleted.\ntype ServiceDeskEntityDeletePayload struct {\n\tEntityType   string // Внутренний тип сущности\n\tExternalUUID string // UUID удаленной сущности во внешней системе\n}\n\n// ContractsStatusPayload - полезная нагрузка для события ContractsStatusRecalculated.\ntype ContractsStatusPayload struct {\n\t// Карта, где ключ - ВНУТРЕННИЙ ID компании, а значение - флаг, активен ли у нее контракт.\n\tCompanyActiveContract map[string]bool\n}\n\n// DuplicatesFoundPayload - полезная нагрузка для события DuplicatesFound.\ntype DuplicatesFoundPayload struct {\n\tEntityType  string   // 'Server', 'Workstation', 'FiscalRegister'\n\tField       string   // Поле, по которому найдены дубликаты ('ip', 'anydesk', и т.д.)\n\tValue       string   // Значение поля, которое дублируется\n\tInternalIDs []string // Список ВНУТРЕННИХ UUID всех сущностей в группе дубликатов\n}\n\n// ServerPollingSucceededPayload - полезная нагрузка для успешного опроса.\ntype ServerPollingSucceededPayload struct {\n\tServerUUID    string\n\tServerName    string\n\tServerEdition string\n\tServerVersion string\n\tNewStatus     string\n\tLastPolledAt  time.Time\n}\n\n// ServerPollingFailedPayload - полезная нагрузка для неудачного опроса.\ntype ServerPollingFailedPayload struct {\n\tServerUUID   string\n\tNewStatus    string // 'offline' или 'archived'\n\tErrorMessage string\n\tLastPolledAt time.Time\n}\n\n// ServerPollingRequestedPayload - полезная нагрузка для ручного запуска.\ntype ServerPollingRequestedPayload struct {\n\tServerUUID string\n}\n\n// ServiceDeskModificationPayload - общая полезная нагрузка для событий создания/обновления в ServiceDesk.\ntype ServiceDeskModificationPayload struct {\n\tTaskID            uint                   `json:\"task_id\"`\n\tEntityType        string                 `json:\"entity_type\"`\n\tEntityUUID        string                 `json:\"entity_uuid,omitempty\"` // Пусто для создания\n\tTriggeredByUserID string                 `json:\"triggered_by_user_id\"`\n\tPayloadForSD      map[string]interface{} `json:\"payload_for_sd\"` // Данные для отправки в SD\n}\n\n// DiscrepancyDetail описывает расхождение по одному полю.\ntype DiscrepancyDetail struct {\n\tEtalonValue      interface{} `json:\"etalon_value\"`\n\tServiceDeskValue interface{} `json:\"service_desk_value\"`\n}\n\n// FiscalRegisterDiscrepancyPayload - полезная нагрузка для события FiscalRegisterDiscrepancyFound.\ntype FiscalRegisterDiscrepancyPayload struct {\n\tFRServiceDeskUUID string                       `json:\"fr_service_desk_uuid\"`\n\tDiscrepancies     map[string]DiscrepancyDetail `json:\"discrepancies\"` // Карта: имя поля -> детали расхождения\n}\n\n// AgentDataPayload - полезная нагрузка для события AgentDataReceived.\ntype AgentDataPayload struct {\n\tSource string           // Источник данных: имя файла для FTP или UUID агента для API\n\tData   api.AgentDataDTO // Сами данные, полученные от агента\n}\n",
    "internal/db/db.go": "package db\n\nimport (\n\t\"etalon-server/internal/config\"\n\t\"log\"\n\n\t\"gorm.io/driver/postgres\"\n\t\"gorm.io/gorm\"\n\t\"gorm.io/gorm/logger\"\n)\n\n// NewConnection создает и возвращает новое подключение к базе данных.\nfunc NewConnection(cfg *config.Config) (*gorm.DB, error) {\n\tdb, err := gorm.Open(postgres.Open(cfg.DatabaseURL), &gorm.Config{\n\t\tLogger: logger.Default.LogMode(logger.Silent),\n\t})\n\tif err != nil {\n\t\tlog.Fatalf(\"Failed to connect to database: %v\", err)\n\t}\n\n\treturn db, nil\n}\n",
    "internal/external/client.go": "package external\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// ContractState представляет собой простой статус контракта для компании.\ntype ContractState struct {\n\tIsActive bool\n\t// В будущем можно добавить сюда уровень сервиса, дату окончания и т.д.\n\t// ServiceLevel int\n\t// ExpiresAt    *time.Time\n}\n\n// MapperContext содержит зависимости, необходимые для маппинга.\ntype MapperContext struct {\n\tDB       *gorm.DB\n\tLinkRepo repositories.LinkRepo\n\tLogger   *zap.Logger\n}\n\n// Mapper определяет интерфейс для преобразования данных из формата внешней системы в наши внутренние модели.\n// Вся логика, специфичная для конкретной внешней системы, должна быть инкапсулирована здесь.\ntype Mapper interface {\n\t// DataToCompany преобразует сырые данные в модель Company.\n\tDataToCompany(ctx context.Context, mc *MapperContext, data map[string]interface{}) (*models.Company, error)\n\n\t// DataToServer преобразует сырые данные в модель Server.\n\tDataToServer(ctx context.Context, mc *MapperContext, data map[string]interface{}) (*models.Server, error)\n\n\t// DataToWorkstation преобразует сырые данные в модель Workstation.\n\tDataToWorkstation(ctx context.Context, mc *MapperContext, data map[string]interface{}) (*models.Workstation, error)\n\n\t// DataToFiscalRegister преобразует сырые данные в модель FiscalRegister.\n\tDataToFiscalRegister(ctx context.Context, mc *MapperContext, data map[string]interface{}) (*models.FiscalRegister, error)\n\n\t// DataToContract преобразует сырые данные в модель Contract.\n\tDataToContract(ctx context.Context, mc *MapperContext, data map[string]interface{}) (*models.Contract, error)\n\n\t// GetCompanyUUIDsFromContract извлекает UUID компаний из данных контракта.\n\tGetCompanyUUIDsFromContract(data map[string]interface{}) []string\n}\n\n// ExternalSystemClient определяет абстрактный интерфейс для взаимодействия с внешней системой (например, ServiceDesk).\n// Интерфейс полностью очищен от деталей реализации конкретной системы.\ntype ExternalSystemClient interface {\n\n\t// Mapper возвращает реализацию маппера, специфичную для данной внешней системы.\n\tMapper() Mapper\n\n\t// FetchEntityList получает список всех сущностей определенного типа из внешней системы.\n\tFetchEntityList(ctx context.Context, entityType string) ([]map[string]interface{}, error)\n\n\t// FetchEntitySummaries получает КРАТКИЙ список сущностей с минимальным набором атрибутов\n\t// (обычно UUID, lastModifiedDate, owner) для быстрой сверки изменений.\n\tFetchEntitySummaries(ctx context.Context, entityType string) ([]map[string]interface{}, error)\n\n\t// FetchEntityDetails получает полную информацию о конкретной сущности по ее внешнему ID.\n\tFetchEntityDetails(ctx context.Context, externalID string, entityType string) (map[string]interface{}, error)\n\n\t// FetchCompanyContractStates получает статусы контрактов для всех компаний.\n\t// Возвращает map[externalCompanyID]ContractState.\n\tFetchCompanyContractStates(ctx context.Context) (map[string]ContractState, error)\n\n\t// UpdateEntity обновляет сущность во внешней системе.\n\tUpdateEntity(ctx context.Context, externalID string, entityType string, data map[string]interface{}) error\n\n\t// CreateEntity создает сущность во внешней системе.\n\tCreateEntity(ctx context.Context, entityType string, data map[string]interface{}) (map[string]interface{}, error)\n\n\t// FindReferenceID ищет ID в справочнике внешней системы.\n\tFindReferenceID(ctx context.Context, referenceType, title string, useSubstringSearch bool) (string, error)\n}\n",
    "internal/gateways/agent_ftp_gateway.go": "package gateways\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/services\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"os\"\n\t\"path\"\n\t\"path/filepath\"\n\t\"strings\"\n\t\"time\"\n\n\t\"github.com/jlaffaye/ftp\"\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n\t\"gorm.io/gorm/clause\"\n)\n\n// AgentFTPGateway отвечает за чтение данных от агентов с FTP и публикацию событий.\ntype AgentFTPGateway interface {\n\tStart(ctx context.Context)\n}\n\ntype agentFTPGatewayImpl struct {\n\tcfg       *config.Config\n\tlogger    *zap.Logger\n\tdb        *gorm.DB\n\tftpClient services.FTPClient\n\tbus       eventbus.EventBus\n}\n\nfunc NewAgentFTPGateway(cfg *config.Config, logger *zap.Logger, db *gorm.DB, ftpClient services.FTPClient, bus eventbus.EventBus) AgentFTPGateway {\n\treturn &agentFTPGatewayImpl{cfg, logger, db, ftpClient, bus}\n}\n\nfunc (g *agentFTPGatewayImpl) Start(ctx context.Context) {\n\tg.logger.Info(\"Запуск шлюза агентов (FTP)\", zap.Duration(\"interval\", g.cfg.AgentFTPInterval))\n\tticker := time.NewTicker(g.cfg.AgentFTPInterval)\n\tdefer ticker.Stop()\n\tg.runReconciliationCycle(ctx)\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tg.runReconciliationCycle(ctx)\n\t\tcase <-ctx.Done():\n\t\t\tg.logger.Info(\"Остановка шлюза агентов (FTP).\")\n\t\t\treturn\n\t\t}\n\t}\n}\n\nfunc (g *agentFTPGatewayImpl) runReconciliationCycle(ctx context.Context) {\n\tg.logger.Info(\"Начало нового цикла сверки данных с FTP...\")\n\tif err := g.syncLocalCacheWithFTP(ctx); err != nil {\n\t\tg.logger.Error(\"Ошибка синхронизации кэша с FTP, цикл прерван\", zap.Error(err))\n\t\treturn\n\t}\n\tlocalFiles, err := os.ReadDir(g.cfg.FTPCachePath)\n\tif err != nil {\n\t\tg.logger.Error(\"Не удалось прочитать директорию с кэшем, цикл прерван\", zap.Error(err))\n\t\treturn\n\t}\n\tpublishedEvents := 0\n\tfor _, file := range localFiles {\n\t\tif file.IsDir() || !strings.HasSuffix(strings.ToLower(file.Name()), \".json\") {\n\t\t\tcontinue\n\t\t}\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\treturn\n\t\tdefault:\n\t\t\tif g.processFile(ctx, file.Name()) {\n\t\t\t\tpublishedEvents++\n\t\t\t}\n\t\t}\n\t}\n\tg.logger.Info(\"Цикл сверки данных с FTP завершен.\", zap.Int(\"published_events\", publishedEvents))\n}\n\n// processFile обрабатывает один файл из кэша.\nfunc (g *agentFTPGatewayImpl) processFile(ctx context.Context, fileName string) bool {\n\tlog := g.logger.With(zap.String(\"file\", fileName))\n\tlocalFilePath := filepath.Join(g.cfg.FTPCachePath, fileName)\n\n\tfileInfo, err := os.Stat(localFilePath)\n\tif err != nil {\n\t\tlog.Error(\"Не удалось получить информацию о файле в кэше\", zap.Error(err))\n\t\treturn false\n\t}\n\n\tvar previousState models.AgentFile\n\terr = g.db.WithContext(ctx).First(&previousState, \"file_name = ?\", fileName).Error\n\tisNewRecordInDB := errors.Is(err, gorm.ErrRecordNotFound)\n\tif err != nil && !isNewRecordInDB {\n\t\tlog.Error(\"Ошибка получения состояния файла из БД\", zap.Error(err))\n\t\treturn false\n\t}\n\n\tif !isNewRecordInDB && previousState.LastProcessedModTime.Equal(fileInfo.ModTime()) && previousState.LastProcessedFileSize == fileInfo.Size() {\n\t\treturn false\n\t}\n\n\tfileData, err := os.ReadFile(localFilePath)\n\tif err != nil {\n\t\tlog.Error(\"Не удалось прочитать файл из кэша\", zap.Error(err))\n\t\treturn false\n\t}\n\n\tvar data api.AgentDataDTO\n\tif err := json.Unmarshal(fileData, &data); err != nil {\n\t\tlog.Error(\"Не удалось распарсить JSON, файл будет пропущен до следующего изменения\", zap.Error(err))\n\t\treturn false\n\t}\n\n\tcurrentFRSerial := data.SerialNumber\n\tcurrentRMSUrl := data.URLRms\n\thierarchyHasChanged := isNewRecordInDB ||\n\t\t(utils.SafeStringDereference(previousState.LastSeenFRSerial) != currentFRSerial) ||\n\t\t(utils.SafeStringDereference(previousState.LastSeenRMSUrl) != currentRMSUrl)\n\n\tnewState := models.AgentFile{\n\t\tFileName:              fileName,\n\t\tLastProcessedModTime:  fileInfo.ModTime(),\n\t\tLastProcessedFileSize: fileInfo.Size(),\n\t}\n\tif currentFRSerial != \"\" {\n\t\tnewState.LastSeenFRSerial = &currentFRSerial\n\t}\n\tif currentRMSUrl != \"\" {\n\t\tnewState.LastSeenRMSUrl = &currentRMSUrl\n\t}\n\terr = g.db.WithContext(ctx).Clauses(clause.OnConflict{\n\t\tColumns:   []clause.Column{{Name: \"file_name\"}},\n\t\tDoUpdates: clause.AssignmentColumns([]string{\"last_processed_mod_time\", \"last_processed_file_size\", \"last_seen_fr_serial\", \"last_seen_rms_url\", \"updated_at\"}),\n\t}).Create(&newState).Error\n\n\tif err != nil {\n\t\tlog.Error(\"Не удалось обновить статус файла в БД\", zap.Error(err))\n\t\treturn false\n\t}\n\n\tif hierarchyHasChanged {\n\t\tlog.Info(\"Обнаружен новый файл или изменение в иерархии объектов. Публикация события...\")\n\n\t\t// ИЗМЕНЕНИЕ: Формируем новую полезную нагрузку\n\t\tpayload := events.AgentDataPayload{\n\t\t\tSource: fileName,\n\t\t\tData:   data,\n\t\t}\n\n\t\tg.bus.Publish(eventbus.Event{\n\t\t\tType:    events.AgentDataReceived,\n\t\t\tPayload: payload,\n\t\t})\n\t\treturn true\n\t}\n\n\tlog.Debug(\"Файл обновлен, но иерархия объектов не изменилась. Событие не публикуется.\")\n\treturn false\n}\n\n// syncLocalCacheWithFTP скачивает новые или обновленные файлы с FTP-сервера в локальный кэш.\nfunc (s *agentFTPGatewayImpl) syncLocalCacheWithFTP(_ context.Context) error {\n\ts.logger.Info(\"Синхронизация локального кэша с FTP...\")\n\tftpFiles, err := s.ftpClient.ListFiles(s.cfg.FTPPath)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"не удалось получить список файлов с FTP: %w\", err)\n\t}\n\n\tlocalFileInfos := make(map[string]os.FileInfo)\n\tcachedFiles, err := os.ReadDir(s.cfg.FTPCachePath)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"не удалось прочитать кэш-директорию: %w\", err)\n\t}\n\n\tfor _, f := range cachedFiles {\n\t\tif info, err := f.Info(); err == nil {\n\t\t\tlocalFileInfos[f.Name()] = info\n\t\t}\n\t}\n\tfor _, ftpFile := range ftpFiles {\n\t\tif ftpFile.Type != ftp.EntryTypeFile || !strings.HasSuffix(strings.ToLower(ftpFile.Name), \".json\") || ftpFile.Size == 0 {\n\t\t\tcontinue\n\t\t}\n\t\tlocalInfo, found := localFileInfos[ftpFile.Name]\n\t\tif !found || ftpFile.Time.After(localInfo.ModTime()) {\n\t\t\ts.logger.Info(\"Обнаружен новый/обновленный файл, скачивание...\", zap.String(\"file\", ftpFile.Name))\n\t\t\tftpFilePath := path.Join(s.cfg.FTPPath, ftpFile.Name)\n\t\t\tfileData, err := s.ftpClient.DownloadFile(ftpFilePath)\n\t\t\tif err != nil {\n\t\t\t\ts.logger.Error(\"Не удалось скачать файл\", zap.String(\"file\", ftpFile.Name), zap.Error(err))\n\t\t\t\tcontinue\n\t\t\t}\n\n\t\t\tlocalFilePath := filepath.Join(s.cfg.FTPCachePath, ftpFile.Name)\n\t\t\tif err := os.WriteFile(localFilePath, fileData, 0644); err != nil {\n\t\t\t\ts.logger.Error(\"Не удалось сохранить файл в кэш\", zap.String(\"file\", localFilePath), zap.Error(err))\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tos.Chtimes(localFilePath, ftpFile.Time, ftpFile.Time)\n\t\t}\n\t}\n\ts.logger.Info(\"Синхронизация локального кэша завершена.\")\n\treturn nil\n}\n",
    "internal/gateways/duplicates_gateway.go": "// internal/gateways/duplicates_gateway.go\npackage gateways\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"sync\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// DuplicatesGateway периодически ищет дубликаты в базе данных и публикует события.\ntype DuplicatesGateway interface {\n\tStart(ctx context.Context)\n}\n\ntype duplicatesGatewayImpl struct {\n\tcfg    *config.Config\n\tdb     *gorm.DB\n\tbus    eventbus.EventBus\n\tlogger *zap.Logger\n}\n\n// NewDuplicatesGateway создает новый экземпляр шлюза.\nfunc NewDuplicatesGateway(cfg *config.Config, db *gorm.DB, bus eventbus.EventBus, logger *zap.Logger) DuplicatesGateway {\n\treturn &duplicatesGatewayImpl{\n\t\tcfg:    cfg,\n\t\tdb:     db,\n\t\tbus:    bus,\n\t\tlogger: logger,\n\t}\n}\n\n// Start запускает периодический поиск дубликатов.\nfunc (g *duplicatesGatewayImpl) Start(ctx context.Context) {\n\tinterval := g.cfg.DuplicatesSearchInterval\n\tg.logger.Info(\"Запуск шлюза поиска дубликатов\", zap.Duration(\"interval\", interval))\n\tticker := time.NewTicker(interval)\n\tdefer ticker.Stop()\n\n\tg.runSearchCycle(ctx)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tg.runSearchCycle(ctx)\n\t\tcase <-ctx.Done():\n\t\t\tg.logger.Info(\"Остановка шлюза поиска дубликатов.\")\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// runSearchCycle выполняет один полный цикл поиска по всем типам сущностей и полям.\nfunc (g *duplicatesGatewayImpl) runSearchCycle(ctx context.Context) {\n\tg.logger.Info(\"Начало нового цикла поиска дубликатов.\")\n\n\tentityConfigs := []struct {\n\t\tmodel      interface{}\n\t\tentityType string\n\t\tfields     []string\n\t}{\n\t\t{&models.Server{}, \"Server\", []string{\"ip\"}},\n\t\t{&models.Workstation{}, \"Workstation\", []string{\"anydesk\", \"teamviewer\", \"litemanager\"}},\n\t\t{&models.FiscalRegister{}, \"FiscalRegister\", []string{\"fr_serial_number\", \"rn_kkt\"}},\n\t}\n\n\tvar wg sync.WaitGroup\n\tfor _, config := range entityConfigs {\n\t\tfor _, field := range config.fields {\n\t\t\twg.Add(1)\n\t\t\tgo func(m interface{}, et, f string) {\n\t\t\t\tdefer wg.Done()\n\t\t\t\tg.findAndPublish(ctx, m, et, f)\n\t\t\t}(config.model, config.entityType, field)\n\t\t}\n\t}\n\twg.Wait()\n\tg.logger.Info(\"Цикл поиска дубликатов завершен.\")\n}\n\n// findAndPublish находит дубликаты для конкретной модели/поля и публикует события.\nfunc (g *duplicatesGatewayImpl) findAndPublish(ctx context.Context, model interface{}, entityType, field string) {\n\tlog := g.logger.With(zap.String(\"entityType\", entityType), zap.String(\"field\", field))\n\n\tvar duplicateValues []struct{ Value string }\n\terr := g.db.WithContext(ctx).Model(model).\n\t\tSelect(fmt.Sprintf(\"%s as value\", field)).\n\t\tWhere(fmt.Sprintf(\"%s IS NOT NULL AND %s != ''\", field, field)).\n\t\tWhere(\"status != ?\", \"locked\").\n\t\tGroup(field).\n\t\tHaving(\"count(*) > 1\").\n\t\tFind(&duplicateValues).Error\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при поиске групп дубликатов\", zap.Error(err))\n\t\treturn\n\t}\n\n\tif len(duplicateValues) == 0 {\n\t\treturn\n\t}\n\n\tlog.Info(\"Найдено групп дубликатов\", zap.Int(\"count\", len(duplicateValues)))\n\n\tfor _, item := range duplicateValues {\n\t\tvar internalIDs []string\n\t\terr := g.db.WithContext(ctx).Model(model).\n\t\t\tWhere(fmt.Sprintf(\"%s = ?\", field), item.Value).\n\t\t\tPluck(\"id\", &internalIDs).Error\n\n\t\tif err != nil {\n\t\t\tlog.Error(\"Не удалось получить внутренние ID для группы дубликатов\", zap.String(\"value\", item.Value), zap.Error(err))\n\t\t\tcontinue\n\t\t}\n\n\t\tif len(internalIDs) > 1 {\n\t\t\tg.bus.Publish(eventbus.Event{\n\t\t\t\tType: events.DuplicatesFound,\n\t\t\t\tPayload: events.DuplicatesFoundPayload{\n\t\t\t\t\tEntityType:  entityType,\n\t\t\t\t\tField:       field,\n\t\t\t\t\tValue:       item.Value,\n\t\t\t\t\tInternalIDs: internalIDs,\n\t\t\t\t},\n\t\t\t})\n\t\t}\n\t}\n}\n",
    "internal/gateways/sdesk_gateway.go": "// internal/gateways/sdesk_gateway.go\npackage gateways\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"sync\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// ServiceDeskGateway отвечает за получение данных из ServiceDesk и публикацию событий.\ntype ServiceDeskGateway interface {\n\tStart(ctx context.Context)\n}\n\n// localEntityInfo - внутренняя структура для хранения минимально необходимых данных из локальной БД для сравнения.\ntype localEntityInfo struct {\n\tInternalID       string\n\tLastModifiedDate *time.Time\n\tDeletedAt        gorm.DeletedAt\n}\n\ntype serviceDeskGatewayImpl struct {\n\tcfg             *config.Config\n\tsdClient        external.ExternalSystemClient\n\tbus             eventbus.EventBus\n\tlogger          *zap.Logger\n\tdb              *gorm.DB // Добавляем прямое подключение для работы со связями\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\tmu              sync.Mutex\n\tisSyncing       bool\n}\n\n// NewServiceDeskGateway создает новый экземпляр шлюза ServiceDesk.\nfunc NewServiceDeskGateway(cfg *config.Config, sdClient external.ExternalSystemClient, bus eventbus.EventBus, logger *zap.Logger, db *gorm.DB, companyRepo repositories.CompanyRepo, serverRepo repositories.ServerRepo, workstationRepo repositories.WorkstationRepo, frRepo repositories.FiscalRegisterRepo) ServiceDeskGateway {\n\treturn &serviceDeskGatewayImpl{\n\t\tcfg:             cfg,\n\t\tsdClient:        sdClient,\n\t\tbus:             bus,\n\t\tlogger:          logger,\n\t\tdb:              db, // Инициализируем\n\t\tcompanyRepo:     companyRepo,\n\t\tserverRepo:      serverRepo,\n\t\tworkstationRepo: workstationRepo,\n\t\tfrRepo:          frRepo,\n\t}\n}\n\n// Start запускает воркер в фоновом режиме.\nfunc (g *serviceDeskGatewayImpl) Start(ctx context.Context) {\n\tg.logger.Info(\"Запуск шлюза ServiceDesk\", zap.Duration(\"interval\", g.cfg.SDeskSyncInterval))\n\tticker := time.NewTicker(g.cfg.SDeskSyncInterval)\n\tdefer ticker.Stop()\n\n\tg.runSyncCycle(ctx)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tg.runSyncCycle(ctx)\n\t\tcase <-ctx.Done():\n\t\t\tg.logger.Info(\"Остановка шлюза ServiceDesk...\")\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// runSyncCycle выполняет один полный цикл синхронизации.\nfunc (g *serviceDeskGatewayImpl) runSyncCycle(ctx context.Context) {\n\tg.mu.Lock()\n\tif g.isSyncing {\n\t\tg.logger.Warn(\"Цикл синхронизации шлюза ServiceDesk уже запущен. Пропуск.\")\n\t\tg.mu.Unlock()\n\t\treturn\n\t}\n\tg.isSyncing = true\n\tg.mu.Unlock()\n\n\tdefer func() {\n\t\tg.mu.Lock()\n\t\tg.isSyncing = false\n\t\tg.mu.Unlock()\n\t}()\n\n\tg.logger.Info(\"Начало нового цикла получения данных из ServiceDesk.\")\n\n\tentityTypes := []string{\"Company\", \"Server\", \"Workstation\", \"FiscalRegister\"}\n\tfor _, entityType := range entityTypes {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\treturn\n\t\tdefault:\n\t\t\tg.processEntityType(ctx, entityType)\n\t\t}\n\t}\n\tg.logger.Info(\"Цикл получения данных из ServiceDesk завершен.\")\n}\n\n// processEntityType выполняет инкрементальную синхронизацию для одного типа сущности.\nfunc (g *serviceDeskGatewayImpl) processEntityType(ctx context.Context, entityType string) {\n\tlog := g.logger.With(zap.String(\"entityType\", entityType))\n\tlog.Info(\"Начало синхронизации типа сущности\")\n\n\t// 1. Получаем КРАТКИЙ список сущностей из внешней системы.\n\tremoteList, err := g.sdClient.FetchEntitySummaries(ctx, entityType)\n\tif err != nil {\n\t\tlog.Error(\"Не удалось получить список сущностей из ServiceDesk\", zap.Error(err))\n\t\treturn\n\t}\n\n\t// 2. Получаем все существующие связи для этого типа сущности.\n\tlocalMap, err := g.getLocalEntityLinks(ctx, entityType)\n\tif err != nil {\n\t\tlog.Error(\"Не удалось получить локальные связи для сущностей\", zap.Error(err))\n\t\treturn\n\t}\n\n\t// 3. Сравниваем списки и формируем задачи на создание, обновление и удаление.\n\tremoteExternalIDs := make(map[string]struct{}, len(remoteList))\n\tvar toCreate, toUpdate, toDelete []string\n\n\tfor _, remoteItem := range remoteList {\n\t\tremoteUUID, _ := remoteItem[\"UUID\"].(string)\n\t\tif remoteUUID == \"\" {\n\t\t\tcontinue\n\t\t}\n\t\tremoteExternalIDs[remoteUUID] = struct{}{}\n\t\tremoteLMD := utils.ParseServiceDeskTime(remoteItem[\"lastModifiedDate\"].(string))\n\t\tif remoteLMD == nil {\n\t\t\tcontinue // Пропускаем сущности без даты модификации (можно добавить creationDate?)\n\t\t}\n\n\t\tlocalLink, exists := localMap[remoteUUID]\n\t\tif !exists {\n\t\t\ttoCreate = append(toCreate, remoteUUID)\n\t\t} else if localLink.DeletedAt.Valid || (localLink.LastModifiedDate != nil && remoteLMD.After(*localLink.LastModifiedDate)) {\n\t\t\ttoUpdate = append(toUpdate, remoteUUID)\n\t\t}\n\t}\n\n\tfor externalUUID, localLink := range localMap {\n\t\tif _, exists := remoteExternalIDs[externalUUID]; !exists && !localLink.DeletedAt.Valid {\n\t\t\ttoDelete = append(toDelete, externalUUID)\n\t\t}\n\t}\n\n\tlog.Info(\"Сравнение завершено\",\n\t\tzap.Int(\"remote_count\", len(remoteList)),\n\t\tzap.Int(\"local_count\", len(localMap)),\n\t\tzap.Int(\"to_create\", len(toCreate)),\n\t\tzap.Int(\"to_update\", len(toUpdate)),\n\t\tzap.Int(\"to_delete\", len(toDelete)),\n\t)\n\n\t// 4. Обрабатываем задачи и публикуем события.\n\tif len(toDelete) > 0 {\n\t\tg.publishDeleteEvents(entityType, toDelete, log)\n\t}\n\n\tif len(toCreate) > 0 || len(toUpdate) > 0 {\n\t\tuuidsToFetch := append(toCreate, toUpdate...)\n\t\tg.fetchAndPublishUpdateEvents(ctx, entityType, uuidsToFetch, log)\n\t}\n}\n\n// publishDeleteEvents публикует события об удалении сущностей.\nfunc (g *serviceDeskGatewayImpl) publishDeleteEvents(entityType string, externalUUIDs []string, log *zap.Logger) {\n\tlog.Info(\"Публикация событий об удалении...\", zap.Int(\"count\", len(externalUUIDs)))\n\tfor _, uuid := range externalUUIDs {\n\t\tg.bus.Publish(eventbus.Event{\n\t\t\tType: events.ServiceDeskEntityDeleted,\n\t\t\tPayload: events.ServiceDeskEntityDeletePayload{\n\t\t\t\tEntityType:   entityType,\n\t\t\t\tExternalUUID: uuid,\n\t\t\t},\n\t\t})\n\t}\n}\n\n// fetchAndPublishUpdateEvents получает полные данные для сущностей и публикует события.\nfunc (g *serviceDeskGatewayImpl) fetchAndPublishUpdateEvents(ctx context.Context, entityType string, externalUUIDs []string, log *zap.Logger) {\n\tlog.Info(\"Получение полных данных для новых/обновленных сущностей...\", zap.Int(\"count\", len(externalUUIDs)))\n\tvar wg sync.WaitGroup\n\ttasks := make(chan string, len(externalUUIDs))\n\n\tfor i := 0; i < g.cfg.ConcurrentRequests; i++ {\n\t\twg.Add(1)\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor uuid := range tasks {\n\t\t\t\tselect {\n\t\t\t\tcase <-ctx.Done():\n\t\t\t\t\treturn\n\t\t\t\tdefault:\n\t\t\t\t\tdetails, err := g.sdClient.FetchEntityDetails(ctx, uuid, entityType)\n\t\t\t\t\tif err != nil {\n\t\t\t\t\t\tlog.Error(\"Не удалось получить детали для сущности\", zap.String(\"external_uuid\", uuid), zap.Error(err))\n\t\t\t\t\t\tcontinue\n\t\t\t\t\t}\n\t\t\t\t\tg.bus.Publish(eventbus.Event{\n\t\t\t\t\t\tType: events.ServiceDeskEntityUpdated,\n\t\t\t\t\t\tPayload: events.ServiceDeskEntityPayload{\n\t\t\t\t\t\t\tEntityType:   entityType,\n\t\t\t\t\t\t\tExternalUUID: uuid,\n\t\t\t\t\t\t\tData:         details,\n\t\t\t\t\t\t},\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\n\tfor _, uuid := range externalUUIDs {\n\t\ttasks <- uuid\n\t}\n\tclose(tasks)\n\twg.Wait()\n}\n\n// getLocalEntityLinks извлекает из БД мапу с информацией о связях для данного типа сущности.\nfunc (g *serviceDeskGatewayImpl) getLocalEntityLinks(ctx context.Context, entityType string) (map[string]localEntityInfo, error) {\n\n\ttype result struct {\n\t\tExternalID       string\n\t\tInternalID       string\n\t\tLastModifiedDate *time.Time\n\t\tDeletedAt        gorm.DeletedAt\n\t}\n\n\tvar results []result\n\tvar err error\n\n\t// Выбираем таблицу для JOIN в зависимости от entityType\n\tvar tableName string\n\tswitch entityType {\n\tcase \"Company\":\n\t\ttableName = \"companies\"\n\tcase \"Server\":\n\t\ttableName = \"servers\"\n\tcase \"Workstation\":\n\t\ttableName = \"workstations\"\n\tcase \"FiscalRegister\":\n\t\ttableName = \"fiscal_registers\"\n\tdefault:\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности для получения связей: %s\", entityType)\n\t}\n\n\t// Выполняем запрос с JOIN\n\terr = g.db.WithContext(ctx).Table(\"external_system_links as l\").\n\t\tSelect(\"l.external_id, l.internal_id, t.last_modified_date, t.deleted_at\").\n\t\tJoins(fmt.Sprintf(\"JOIN %s as t ON l.internal_id = t.id\", tableName)).\n\t\tWhere(\"l.system_name = ? AND l.entity_type = ?\", \"naumen\", entityType).\n\t\tScan(&results).Error\n\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\tinfoMap := make(map[string]localEntityInfo, len(results))\n\tfor _, res := range results {\n\t\tinfoMap[res.ExternalID] = localEntityInfo{\n\t\t\tInternalID:       res.InternalID,\n\t\t\tLastModifiedDate: res.LastModifiedDate,\n\t\t\tDeletedAt:        res.DeletedAt,\n\t\t}\n\t}\n\n\treturn infoMap, nil\n}\n",
    "internal/gateways/server_polling_gateway.go": "// internal/gateways/server_polling_gateway.go\npackage gateways\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"regexp\"\n\t\"strings\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n)\n\n// ServerPollingGateway отвечает за фоновый опрос статусов серверов и публикацию результатов.\ntype ServerPollingGateway interface {\n\tStart(ctx context.Context)\n}\n\ntype serverPollingGatewayImpl struct {\n\tcfg        *config.Config\n\tlogger     *zap.Logger\n\tserverRepo repositories.ServerRepo\n\trmsClient  utils.RMSClient\n\tbus        eventbus.EventBus\n}\n\nfunc NewServerPollingGateway(cfg *config.Config, logger *zap.Logger, serverRepo repositories.ServerRepo, rmsClient utils.RMSClient, bus eventbus.EventBus) ServerPollingGateway {\n\treturn &serverPollingGatewayImpl{cfg, logger, serverRepo, rmsClient, bus}\n}\n\n// Start запускает сервис в фоновом режиме.\nfunc (g *serverPollingGatewayImpl) Start(ctx context.Context) {\n\tg.bus.Subscribe(events.ServerPollingRequested, g.handlePollingRequest) // Подписываемся на ручной запуск\n\tg.logger.Info(\"Запуск шлюза опроса статусов серверов\", zap.Duration(\"interval\", 1*time.Minute))\n\tticker := time.NewTicker(1 * time.Minute)\n\tdefer ticker.Stop()\n\tg.runCycle(ctx)\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tg.runCycle(ctx)\n\t\tcase <-ctx.Done():\n\t\t\tg.logger.Info(\"Остановка шлюза для опроса статусов серверов...\")\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// handlePollingRequest обрабатывает событие ручного запуска опроса.\nfunc (g *serverPollingGatewayImpl) handlePollingRequest(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServerPollingRequestedPayload)\n\tif !ok {\n\t\treturn\n\t}\n\t// Payload.ServerUUID здесь уже является внутренним ID\n\tlog := g.logger.With(zap.String(\"trigger\", \"manual\"), zap.String(\"uuid\", payload.ServerUUID))\n\tlog.Info(\"Обработка ручного запроса на опрос сервера\")\n\n\t// Используем новый метод GetByID\n\tserver, err := g.serverRepo.GetByID(ctx, payload.ServerUUID)\n\tif err != nil || server == nil {\n\t\tlog.Error(\"Не удалось найти сервер для ручного опроса\", zap.Error(err))\n\t\treturn\n\t}\n\tgo g.processServer(context.Background(), *server)\n}\n\n// runCycle выполняет один цикл фоновой работы воркера.\nfunc (g *serverPollingGatewayImpl) runCycle(ctx context.Context) {\n\tg.logger.Info(\"Начало нового цикла опроса статусов серверов...\")\n\tservers, err := g.serverRepo.FindForPolling(ctx, g.cfg.ServerPollingBatchSize, g.cfg.ServerPollingInterval)\n\tif err != nil || len(servers) == 0 {\n\t\tif err != nil {\n\t\t\tg.logger.Error(\"Не удалось получить список серверов для опроса\", zap.Error(err))\n\t\t} else {\n\t\t\tg.logger.Info(\"Не найдено серверов, подлежащих опросу.\")\n\t\t}\n\t\treturn\n\t}\n\tg.logger.Info(\"Найдено серверов для обработки\", zap.Int(\"count\", len(servers)))\n\tfor _, server := range servers {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\treturn\n\t\tdefault:\n\t\t\tg.processServer(ctx, server)\n\t\t\ttime.Sleep(2 * time.Second)\n\t\t}\n\t}\n}\n\n// processServer обрабатывает один сервер и публикует событие.\nfunc (g *serverPollingGatewayImpl) processServer(ctx context.Context, server models.Server) {\n\tlog := g.logger.With(zap.String(\"server_id\", server.ID), zap.String(\"server_ip\", utils.SafeStringDereference(server.IP)))\n\tif server.IP == nil || *server.IP == \"\" {\n\t\treturn\n\t}\n\n\tvar url string\n\tparts := strings.SplitN(*server.IP, \":\", 2)\n\thost := parts[0]\n\tif len(parts) == 2 && (parts[1] == \"443\" || strings.Contains(*server.IP, \"iiko.it\") || strings.Contains(*server.IP, \"syrve.online\")) {\n\t\turl = \"https://\" + host\n\t} else {\n\t\turl = \"http://\" + *server.IP\n\t}\n\n\tinfo, err := g.rmsClient.GetServerMonitoringInfo(ctx, url)\n\tif err != nil {\n\t\tlog.Warn(\"Не удалось получить информацию о сервере\", zap.String(\"url\", url), zap.Error(err))\n\t\tstatus := \"offline\"\n\t\tif strings.Contains(err.Error(), \"no such host\") {\n\t\t\tstatus = \"archived\"\n\t\t}\n\t\tg.bus.Publish(eventbus.Event{\n\t\t\tType: events.ServerPollingFailed,\n\t\t\tPayload: events.ServerPollingFailedPayload{\n\t\t\t\tServerUUID:   server.ID, // ИЗМЕНЕНИЕ: Используем внутренний ID\n\t\t\t\tNewStatus:    status,\n\t\t\t\tErrorMessage: err.Error(),\n\t\t\t\tLastPolledAt: time.Now(),\n\t\t\t},\n\t\t})\n\t} else {\n\t\tlog.Info(\"Информация о сервере успешно получена\", zap.String(\"state\", info.ServerState))\n\t\tg.bus.Publish(eventbus.Event{\n\t\t\tType: events.ServerPollingSucceeded,\n\t\t\tPayload: events.ServerPollingSucceededPayload{\n\t\t\t\tServerUUID:    server.ID, // ИЗМЕНЕНИЕ: Используем внутренний ID\n\t\t\t\tServerName:    info.ServerName,\n\t\t\t\tServerEdition: info.Edition,\n\t\t\t\tServerVersion: shortenVersion(info.Version),\n\t\t\t\tNewStatus:     mapServerStateToStatus(info.ServerState),\n\t\t\t\tLastPolledAt:  time.Now(),\n\t\t\t},\n\t\t})\n\t}\n}\n\n// mapServerStateToStatus преобразует статус из ответа сервера в наш внутренний статус.\nfunc mapServerStateToStatus(state string) string {\n\tswitch state {\n\tcase \"STARTED_SUCCESSFULLY\":\n\t\treturn \"active\"\n\tcase \"WAITING_LICENSE\":\n\t\treturn \"license\"\n\tcase \"STARTING\":\n\t\treturn \"starting\"\n\tdefault:\n\t\treturn \"unknown\"\n\t}\n}\n\n// shortenVersion обрезает версию до формата X.Y.Z\nfunc shortenVersion(fullVersion string) string {\n\tif fullVersion == \"\" {\n\t\treturn \"\"\n\t}\n\tre := regexp.MustCompile(`^(\\d+\\.\\d+\\.\\d+)`)\n\tmatches := re.FindStringSubmatch(fullVersion)\n\tif len(matches) > 1 {\n\t\treturn matches[1]\n\t}\n\treturn fullVersion\n}\n",
    "internal/handlers/agent_handler.go": "package handlers\n\nimport (\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/services\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n)\n\n// AgentHandler обрабатывает HTTP-запросы от агентов.\ntype AgentHandler struct {\n\tlogger       *zap.Logger\n\tagentService services.AgentService\n}\n\n// NewAgentHandler создает новый экземпляр обработчика.\nfunc NewAgentHandler(logger *zap.Logger, agentService services.AgentService) *AgentHandler {\n\treturn &AgentHandler{\n\t\tlogger:       logger,\n\t\tagentService: agentService,\n\t}\n}\n\n// RegisterRoutes регистрирует все роуты для агентов.\nfunc (h *AgentHandler) RegisterRoutes(r chi.Router) {\n\tr.Post(\"/register\", h.registerAgent)\n\tr.Get(\"/{uuid}/config\", h.getAgentConfig)\n\tr.Post(\"/{uuid}/data\", h.postAgentData)\n}\n\n// registerAgent обрабатывает запрос на первичную регистрацию агента.\nfunc (h *AgentHandler) registerAgent(w http.ResponseWriter, r *http.Request) {\n\tvar dto api.RegistrationRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат тела запроса\")\n\t\treturn\n\t}\n\n\t// TODO: Добавить валидацию DTO\n\n\t_, err := h.agentService.RegisterAgent(r.Context(), &dto)\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrAgentAlreadyExists):\n\t\t\tRespondWithError(w, http.StatusConflict, \"Агент с таким UUID уже зарегистрирован\")\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка регистрации агента\", zap.String(\"uuid\", dto.AgentUUID), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера при регистрации агента\")\n\t\t}\n\t\treturn\n\t}\n\n\t// В соответствии с протоколом, отвечаем 202 Accepted.\n\t// Агент поймет, что его запрос принят в обработку.\n\tw.WriteHeader(http.StatusAccepted)\n\tRespondWithJSON(w, http.StatusAccepted, map[string]string{\"status\": \"регистрация принята в обработку\"})\n}\n\n// getAgentConfig возвращает конфигурацию для агента.\nfunc (h *AgentHandler) getAgentConfig(w http.ResponseWriter, r *http.Request) {\n\tuuid := chi.URLParam(r, \"uuid\")\n\tif uuid == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"UUID агента не указан\")\n\t\treturn\n\t}\n\n\tconfig, err := h.agentService.GetAgentConfig(r.Context(), uuid)\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrAgentNotFound):\n\t\t\t// Это штатная ситуация для агента, который еще не прошел регистрацию до конца.\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Агент не найден или его регистрация еще не завершена\")\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка получения конфигурации агента\", zap.String(\"uuid\", uuid), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\n\tRespondWithJSON(w, http.StatusOK, config)\n}\n\n// postAgentData принимает и обрабатывает оперативные данные от агента.\nfunc (h *AgentHandler) postAgentData(w http.ResponseWriter, r *http.Request) {\n\tuuid := chi.URLParam(r, \"uuid\")\n\tif uuid == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"UUID агента не указан\")\n\t\treturn\n\t}\n\n\tvar dto api.AgentDataDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат тела запроса\")\n\t\treturn\n\t}\n\n\terr := h.agentService.ProcessData(r.Context(), uuid, &dto)\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrAgentNotFound):\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Агент не найден\")\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка обработки данных от агента\", zap.String(\"uuid\", uuid), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка при обработке данных\")\n\t\t}\n\t\treturn\n\t}\n\n\tRespondWithJSON(w, http.StatusOK, map[string]string{\"status\": \"данные приняты\"})\n}\n",
    "internal/handlers/auth_handler.go": "// <-- НОВЫЙ ФАЙЛ -->\npackage handlers\n\nimport (\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/services\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n)\n\ntype AuthHandler struct {\n\tlogger      *zap.Logger\n\tauthService services.AuthService\n}\n\nfunc NewAuthHandler(logger *zap.Logger, authService services.AuthService) *AuthHandler {\n\treturn &AuthHandler{logger, authService}\n}\n\nfunc (h *AuthHandler) RegisterRoutes(r chi.Router) {\n\tr.Post(\"/login\", h.login)\n}\n\nfunc (h *AuthHandler) login(w http.ResponseWriter, r *http.Request) {\n\tvar dto api.LoginRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат запроса\")\n\t\treturn\n\t}\n\n\tresponse, err := h.authService.Login(r.Context(), dto.Username, dto.Password)\n\tif err != nil {\n\t\tif errors.Is(err, services.ErrInvalidCredentials) {\n\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Неверное имя пользователя или пароль\")\n\t\t} else {\n\t\t\th.logger.Error(\"Ошибка входа в систему\", zap.String(\"username\", dto.Username), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\n\tRespondWithJSON(w, http.StatusOK, response)\n}\n",
    "internal/handlers/crud_handlers.go": "package handlers\n\nimport (\n\t\"encoding/json\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// CrudHandler обрабатывает CRUD-запросы.\ntype CrudHandler struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n}\n\n// NewCrudHandler создает новый экземпляр обработчика.\nfunc NewCrudHandler(logger *zap.Logger, db *gorm.DB, companyRepo repositories.CompanyRepo, serverRepo repositories.ServerRepo, workstationRepo repositories.WorkstationRepo, frRepo repositories.FiscalRegisterRepo) *CrudHandler {\n\treturn &CrudHandler{logger, db, companyRepo, serverRepo, workstationRepo, frRepo}\n}\n\n// RegisterRoutes регистрирует CRUD роуты.\nfunc (h *CrudHandler) RegisterRoutes(r chi.Router) {\n\tr.Route(\"/companies\", func(r chi.Router) {\n\t\tr.Get(\"/{id}\", h.GetCompany)\n\t\tr.Post(\"/\", h.CreateCompany)\n\t\tr.Put(\"/{id}\", h.UpdateCompany)\n\t\tr.Delete(\"/{id}\", h.DeleteCompany)\n\t})\n}\n\nfunc (h *CrudHandler) GetCompany(w http.ResponseWriter, r *http.Request) {\n\tid := chi.URLParam(r, \"id\")\n\tcompany, err := h.companyRepo.GetByID(r.Context(), id)\n\tif err != nil {\n\t\th.logger.Error(\"Failed to get company\", zap.String(\"id\", id), zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Failed to retrieve company\")\n\t\treturn\n\t}\n\tif company == nil {\n\t\tRespondWithError(w, http.StatusNotFound, \"Company not found\")\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusOK, company)\n}\n\nfunc (h *CrudHandler) CreateCompany(w http.ResponseWriter, r *http.Request) {\n\tvar dto api.CompanyCreateDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Invalid request body\")\n\t\treturn\n\t}\n\n\tcompany := &models.Company{\n\t\tTitle:          dto.Title,\n\t\tAddress:        dto.Address,\n\t\tAdditionalName: dto.AdditionalName,\n\t\t// ParentID: dto.ParentID // Предполагаем, что DTO тоже будет обновлен для передачи ParentID\n\t}\n\tcompany.MetaClass = \"ou$company\"\n\n\terr := h.db.Transaction(func(tx *gorm.DB) error {\n\t\treturn h.companyRepo.Create(r.Context(), tx, company)\n\t})\n\tif err != nil {\n\t\th.logger.Error(\"Failed to create company\", zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Failed to create company\")\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusCreated, company)\n}\n\nfunc (h *CrudHandler) UpdateCompany(w http.ResponseWriter, r *http.Request) {\n\tid := chi.URLParam(r, \"id\")\n\tvar updateData map[string]interface{}\n\tif err := json.NewDecoder(r.Body).Decode(&updateData); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Invalid request body\")\n\t\treturn\n\t}\n\t// Удаляем поля, которые не должны обновляться вручную через API\n\tdelete(updateData, \"id\")\n\tdelete(updateData, \"meta_class\")\n\tdelete(updateData, \"created_at\")\n\tdelete(updateData, \"updated_at\")\n\tdelete(updateData, \"deleted_at\")\n\n\tvar updated bool\n\terr := h.db.Transaction(func(tx *gorm.DB) error {\n\t\tvar txErr error\n\t\tupdated, txErr = h.companyRepo.Update(r.Context(), tx, id, updateData)\n\t\treturn txErr\n\t})\n\tif err != nil {\n\t\th.logger.Error(\"Failed to update company\", zap.String(\"id\", id), zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Failed to update company\")\n\t\treturn\n\t}\n\tif !updated {\n\t\tRespondWithError(w, http.StatusNotFound, \"Company not found or no changes applied\")\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusOK, map[string]string{\"message\": \"company updated successfully\"})\n}\n\nfunc (h *CrudHandler) DeleteCompany(w http.ResponseWriter, r *http.Request) {\n\tid := chi.URLParam(r, \"id\")\n\tvar deleted bool\n\terr := h.db.Transaction(func(tx *gorm.DB) error {\n\t\tvar txErr error\n\t\tdeleted, txErr = h.companyRepo.Delete(r.Context(), tx, id)\n\t\treturn txErr\n\t})\n\n\tif err != nil {\n\t\th.logger.Error(\"Failed to delete company\", zap.String(\"id\", id), zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Failed to delete company\")\n\t\treturn\n\t}\n\tif !deleted {\n\t\tRespondWithError(w, http.StatusNotFound, \"Company not found\")\n\t\treturn\n\t}\n\tw.WriteHeader(http.StatusNoContent)\n}\n\n// ИЗМЕНЕНИЕ: Вспомогательные функции respondWithError и respondWithJSON полностью удалены из этого файла.\n",
    "internal/handlers/debug_handler.go": "package handlers\n\nimport (\n\t\"etalon-server/pkg/eventbus\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n)\n\n// DebugHandler обрабатывает запросы к отладочным эндпоинтам.\ntype DebugHandler struct {\n\tlogger *zap.Logger\n\tbus    eventbus.EventBus\n}\n\n// NewDebugHandler создает новый экземпляр обработчика.\nfunc NewDebugHandler(logger *zap.Logger, bus eventbus.EventBus) *DebugHandler {\n\treturn &DebugHandler{\n\t\tlogger: logger,\n\t\tbus:    bus,\n\t}\n}\n\n// RegisterRoutes регистрирует роуты для отладки.\nfunc (h *DebugHandler) RegisterRoutes(r chi.Router) {\n\tr.Get(\"/bus\", h.getBusStatus)\n}\n\n// getBusStatus возвращает текущее состояние шины событий.\nfunc (h *DebugHandler) getBusStatus(w http.ResponseWriter, r *http.Request) {\n\tdebugInfo := h.bus.GetDebugInfo()\n\tRespondWithJSON(w, http.StatusOK, debugInfo)\n}",
    "internal/handlers/middleware.go": "package handlers\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/contextkeys\" // ИЗМЕНЕНИЕ: Новый импорт\n\t\"fmt\"\n\t\"net/http\"\n\t\"strings\"\n\n\t\"github.com/golang-jwt/jwt/v5\"\n)\n\n// JwtAuthMiddleware проверяет JWT токен и добавляет информацию о пользователе в контекст.\nfunc JwtAuthMiddleware(cfg *config.Config) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tauthHeader := r.Header.Get(\"Authorization\")\n\t\t\tif authHeader == \"\" {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Отсутствует заголовок Authorization\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\ttokenString := strings.TrimPrefix(authHeader, \"Bearer \")\n\t\t\tif tokenString == authHeader {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Неверный формат токена\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\ttoken, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {\n\t\t\t\tif _, ok := token.Method.(*jwt.SigningMethodHMAC); !ok {\n\t\t\t\t\treturn nil, fmt.Errorf(\"неожиданный метод подписи: %v\", token.Header[\"alg\"])\n\t\t\t\t}\n\t\t\t\treturn []byte(cfg.JWTSecret), nil\n\t\t\t})\n\n\t\t\tif err != nil || !token.Valid {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Невалидный токен\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tif claims, ok := token.Claims.(jwt.MapClaims); ok {\n\t\t\t\tctx := r.Context()\n\t\t\t\t// Извлекаем ID\n\t\t\t\tif sub, ok := claims[\"sub\"].(string); ok {\n\t\t\t\t\t// ИЗМЕНЕНИЕ: Используем константу из contextkeys\n\t\t\t\t\tctx = context.WithValue(ctx, contextkeys.UserIDContextKey, sub)\n\t\t\t\t} else {\n\t\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Невалидный sub в токене\")\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\t// Извлекаем роли\n\t\t\t\tif roles, ok := claims[\"roles\"].([]interface{}); ok {\n\t\t\t\t\tvar rolesStr []string\n\t\t\t\t\tfor _, r := range roles {\n\t\t\t\t\t\tif role, ok := r.(string); ok {\n\t\t\t\t\t\t\trolesStr = append(rolesStr, role)\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\t// ИЗМЕНЕНИЕ: Используем константу из contextkeys\n\t\t\t\t\tctx = context.WithValue(ctx, contextkeys.UserRolesContextKey, rolesStr)\n\t\t\t\t} else {\n\t\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Невалидные roles в токене\")\n\t\t\t\t\treturn\n\t\t\t\t}\n\n\t\t\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t\t\t} else {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Невалидные claims в токене\")\n\t\t\t}\n\t\t})\n\t}\n}\n\n// AdminRequiredMiddleware проверяет, есть ли у пользователя роль \"admin\".\nfunc AdminRequiredMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t// ИЗМЕНЕНИЕ: Используем константу из contextkeys\n\t\troles, ok := r.Context().Value(contextkeys.UserRolesContextKey).([]string)\n\t\tif !ok {\n\t\t\tRespondWithError(w, http.StatusForbidden, \"Не удалось определить роли пользователя\")\n\t\t\treturn\n\t\t}\n\n\t\tisAdmin := false\n\t\tfor _, role := range roles {\n\t\t\tif role == \"admin\" {\n\t\t\t\tisAdmin = true\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\n\t\tif !isAdmin {\n\t\t\tRespondWithError(w, http.StatusForbidden, \"Доступ запрещен: требуется роль администратора\")\n\t\t\treturn\n\t\t}\n\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\n// AgentAuthMiddleware проверяет наличие и правильность Bearer токена для агентов.\nfunc AgentAuthMiddleware(apiKey string) func(http.Handler) http.Handler {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tif apiKey == \"\" {\n\t\t\t\t// Если ключ не задан на сервере, считаем это ошибкой конфигурации.\n\t\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Сервер не настроен для аутентификации агентов\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tauthHeader := r.Header.Get(\"Authorization\")\n\t\t\tif authHeader == \"\" {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Отсутствует заголовок Authorization\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\theaderParts := strings.Split(authHeader, \" \")\n\t\t\tif len(headerParts) != 2 || strings.ToLower(headerParts[0]) != \"bearer\" {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Неверный формат заголовка Authorization\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\ttoken := headerParts[1]\n\t\t\tif token != apiKey {\n\t\t\t\tRespondWithError(w, http.StatusUnauthorized, \"Неверный ключ API агента\")\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n",
    "internal/handlers/response.go": "package handlers\n\nimport (\n\t\"encoding/json\"\n\t\"etalon-server/internal/api\"\n\t\"net/http\"\n)\n\n// RespondWithError отправляет стандартизированный JSON с ошибкой.\nfunc RespondWithError(w http.ResponseWriter, code int, message string) {\n\tRespondWithJSON(w, code, api.ErrorResponseDTO{Error: message})\n}\n\n// RespondWithJSON отправляет JSON-ответ с указанным кодом и данными.\nfunc RespondWithJSON(w http.ResponseWriter, code int, payload interface{}) {\n\tresponse, err := json.Marshal(payload)\n\tif err != nil {\n\t\t// В случае ошибки маршалинга, отправляем внутреннюю ошибку сервера\n\t\tw.WriteHeader(http.StatusInternalServerError)\n\t\tw.Write([]byte(\"Internal Server Error\"))\n\t\treturn\n\t}\n\tw.Header().Set(\"Content-Type\", \"application/json\")\n\tw.WriteHeader(code)\n\tw.Write(response)\n}\n",
    "internal/handlers/search_handler.go": "// internal/handlers/search_handler.go\npackage handlers\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"strconv\"\n\t\"strings\"\n\t\"sync\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n)\n\n// SearchHandler обрабатывает поисковые запросы.\ntype SearchHandler struct {\n\tlogger          *zap.Logger\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\tlinkRepo        repositories.LinkRepo\n}\n\n// NewSearchHandler создает новый экземпляр обработчика.\nfunc NewSearchHandler(\n\tlogger *zap.Logger,\n\tcompanyRepo repositories.CompanyRepo,\n\tserverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo,\n\tlinkRepo repositories.LinkRepo,\n) *SearchHandler {\n\treturn &SearchHandler{logger, companyRepo, serverRepo, workstationRepo, frRepo, linkRepo}\n}\n\n// RegisterRoutes регистрирует роут для поиска.\nfunc (h *SearchHandler) RegisterRoutes(r chi.Router) {\n\tr.Get(\"/search\", h.Search)\n}\n\n// Search выполняет финальный, UI-ориентированный, owner-centric поиск.\nfunc (h *SearchHandler) Search(w http.ResponseWriter, r *http.Request) {\n\tterm := r.URL.Query().Get(\"term\")\n\tif term == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Поисковый запрос не может быть пустым\")\n\t\treturn\n\t}\n\tlimit, _ := strconv.Atoi(r.URL.Query().Get(\"limit\"))\n\tif limit <= 0 || limit > 100 {\n\t\tlimit = 50\n\t}\n\n\tctx := r.Context()\n\tlog := h.logger.With(zap.String(\"search_term\", term))\n\n\t// ИЗМЕНЕНИЕ: Добавляем логирование\n\tlog.Debug(\"Поступил поисковый запрос\")\n\n\tvar wg sync.WaitGroup\n\tvar initialCompanies []models.Company\n\tvar initialServers []models.Server\n\tvar initialWorkstations []models.Workstation\n\tvar initialFRs []models.FiscalRegister\n\twg.Add(4)\n\tgo func() { defer wg.Done(); initialCompanies, _ = h.companyRepo.Search(ctx, term, true, limit, 0) }()\n\tgo func() { defer wg.Done(); initialServers, _ = h.serverRepo.Search(ctx, term, limit, 0) }()\n\tgo func() { defer wg.Done(); initialWorkstations, _ = h.workstationRepo.Search(ctx, term, limit, 0) }()\n\tgo func() { defer wg.Done(); initialFRs, _ = h.frRepo.Search(ctx, term, limit, 0) }()\n\twg.Wait()\n\n\townerIDs := make(map[string]bool)\n\tfor _, company := range initialCompanies {\n\t\townerIDs[company.ID] = true\n\t}\n\tfor _, server := range initialServers {\n\t\tif server.OwnerID != nil {\n\t\t\townerIDs[*server.OwnerID] = true\n\t\t}\n\t}\n\tfor _, ws := range initialWorkstations {\n\t\tif ws.OwnerID != nil {\n\t\t\townerIDs[*ws.OwnerID] = true\n\t\t}\n\t}\n\tfor _, fr := range initialFRs {\n\t\tif fr.OwnerID != nil {\n\t\t\townerIDs[*fr.OwnerID] = true\n\t\t}\n\t}\n\n\tif len(ownerIDs) == 0 {\n\t\tlog.Debug(\"По запросу ничего не найдено\")\n\t\tRespondWithJSON(w, http.StatusOK, api.FinalSearchResponseDTO{SearchResults: []api.SearchGroupDTO{}})\n\t\treturn\n\t}\n\n\tidsToEnrich := make([]string, 0, len(ownerIDs))\n\tfor id := range ownerIDs {\n\t\tidsToEnrich = append(idsToEnrich, id)\n\t}\n\tfor _, id := range idsToEnrich {\n\t\tparents, _ := h.companyRepo.GetAllParentIDs(ctx, id)\n\t\tfor _, parentID := range parents {\n\t\t\townerIDs[parentID] = true\n\t\t}\n\t}\n\n\tallOwnerIDs := make([]string, 0, len(ownerIDs))\n\tfor id := range ownerIDs {\n\t\tallOwnerIDs = append(allOwnerIDs, id)\n\t}\n\n\tvar allOwnerCompanies []models.Company\n\tvar allOwnerServers []models.Server\n\tvar allOwnerWorkstations []models.Workstation\n\tvar allOwnerFRs []models.FiscalRegister\n\twg.Add(4)\n\tgo func() { defer wg.Done(); allOwnerCompanies, _ = h.companyRepo.GetByIDs(ctx, allOwnerIDs) }()\n\tgo func() { defer wg.Done(); allOwnerServers, _ = h.serverRepo.FindByOwnerIDs(ctx, allOwnerIDs) }()\n\tgo func() { defer wg.Done(); allOwnerWorkstations, _ = h.workstationRepo.FindByOwnerIDs(ctx, allOwnerIDs) }()\n\tgo func() { defer wg.Done(); allOwnerFRs, _ = h.frRepo.FindByOwnerIDs(ctx, allOwnerIDs) }()\n\twg.Wait()\n\n\tserversByOwner := h.groupServersByOwner(ctx, allOwnerServers)\n\tworkstationsByOwner := h.groupWorkstationsByOwner(ctx, allOwnerWorkstations)\n\tfrsByOwner := h.groupFRsByOwner(ctx, allOwnerFRs)\n\n\tfinalResponse := api.FinalSearchResponseDTO{}\n\tinitialOwnerIDs := make(map[string]struct{})\n\tfor _, id := range idsToEnrich {\n\t\tinitialOwnerIDs[id] = struct{}{}\n\t}\n\n\tfor _, owner := range allOwnerCompanies {\n\t\townerID := owner.ID\n\t\tif _, ok := initialOwnerIDs[ownerID]; !ok {\n\t\t\tcontinue\n\t\t}\n\n\t\tlink, _ := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", owner.ID)\n\t\tvar externalUUID *string\n\t\tif link != nil {\n\t\t\texternalUUID = &link.ExternalID\n\t\t}\n\n\t\tgroup := api.SearchGroupDTO{\n\t\t\tOwner: api.OwnerFullDTO{\n\t\t\t\tUUID:           ownerID,\n\t\t\t\tExternalUUID:   externalUUID, // ИСПРАВЛЕНИЕ: Теперь это поле существует\n\t\t\t\tName:           utils.SafeStringDereference(owner.Title),\n\t\t\t\tAddress:        owner.Address,\n\t\t\t\tActiveContract: owner.ActiveContract,\n\t\t\t\tAdditionalInfo: owner.AdditionalName,\n\t\t\t},\n\t\t\tFoundEntities: []api.FoundEntityDTO{},\n\t\t}\n\n\t\tcurrentAndParentIDs := map[string]struct{}{ownerID: {}}\n\t\tparents, _ := h.companyRepo.GetAllParentIDs(ctx, ownerID)\n\t\tfor _, pID := range parents {\n\t\t\tcurrentAndParentIDs[pID] = struct{}{}\n\t\t}\n\n\t\tfor id := range currentAndParentIDs {\n\t\t\tif servers, ok := serversByOwner[id]; ok {\n\t\t\t\tgroup.FoundEntities = append(group.FoundEntities, servers...)\n\t\t\t}\n\t\t\tif id == ownerID {\n\t\t\t\tif workstations, ok := workstationsByOwner[id]; ok {\n\t\t\t\t\tgroup.FoundEntities = append(group.FoundEntities, workstations...)\n\t\t\t\t}\n\t\t\t\tif frs, ok := frsByOwner[id]; ok {\n\t\t\t\t\tgroup.FoundEntities = append(group.FoundEntities, frs...)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tfinalResponse.SearchResults = append(finalResponse.SearchResults, group)\n\t}\n\tlog.Debug(\"Поиск завершен, найдено групп\", zap.Int(\"groups_count\", len(finalResponse.SearchResults)))\n\tRespondWithJSON(w, http.StatusOK, finalResponse)\n}\n\n// --- Вспомогательные функции-группировщики ---\n\nfunc (h *SearchHandler) groupServersByOwner(ctx context.Context, servers []models.Server) map[string][]api.FoundEntityDTO {\n\tresult := make(map[string][]api.FoundEntityDTO)\n\tfor _, s := range servers {\n\t\tif s.OwnerID != nil {\n\t\t\townerID := *s.OwnerID\n\n\t\t\t// Обогащаем внешним ID\n\t\t\tlink, _ := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", s.ID)\n\t\t\tvar externalUUID *string\n\t\t\tif link != nil {\n\t\t\t\texternalUUID = &link.ExternalID\n\t\t\t}\n\n\t\t\t// Формируем ссылку на партнерский кабинет\n\t\t\tvar partnersLink *string\n\t\t\tclientIdStr := utils.SafeStringDereference(s.CabinetLink)\n\t\t\tif clientIdStr != \"\" && clientIdStr != \"N/A\" {\n\t\t\t\tvar link string\n\t\t\t\tipStr := utils.SafeStringDereference(s.IP)\n\t\t\t\tif strings.Contains(strings.ToLower(ipStr), \"syrve\") {\n\t\t\t\t\tlink = fmt.Sprintf(\"https://pp.syrve.com/en/cabinet/client-area/index.html?clientId=%s\", clientIdStr)\n\t\t\t\t} else {\n\t\t\t\t\tlink = fmt.Sprintf(\"https://pp.iiko.ru/ru/cabinet/client-area/index.html?clientId=%s\", clientIdStr)\n\t\t\t\t}\n\t\t\t\tpartnersLink = &link\n\t\t\t}\n\n\t\t\tresult[ownerID] = append(result[ownerID], api.FoundEntityDTO{\n\t\t\t\tEntityType: \"Server\",\n\t\t\t\tData: api.ServerRichDTO{\n\t\t\t\t\tUUID:         s.ID,\n\t\t\t\t\tExternalUUID: externalUUID,\n\t\t\t\t\tDeviceName:   s.DeviceName,\n\t\t\t\t\tIP:           s.IP,\n\t\t\t\t\tStatus:       s.Status,\n\t\t\t\t\tAnydesk:      s.Anydesk,\n\t\t\t\t\tTeamviewer:   s.Teamviewer,\n\t\t\t\t\tRDP:          s.RDP,\n\t\t\t\t\tLitemanager:  s.Litemanager,\n\t\t\t\t\tUniqueID:     s.UniqueID,\n\t\t\t\t\tPartnersLink: partnersLink,\n\t\t\t\t},\n\t\t\t})\n\t\t}\n\t}\n\treturn result\n}\n\nfunc (h *SearchHandler) groupWorkstationsByOwner(ctx context.Context, workstations []models.Workstation) map[string][]api.FoundEntityDTO {\n\tresult := make(map[string][]api.FoundEntityDTO)\n\tfor _, ws := range workstations {\n\t\tif ws.OwnerID != nil {\n\t\t\townerID := *ws.OwnerID\n\n\t\t\t// Обогащаем внешним ID\n\t\t\tlink, _ := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", ws.ID)\n\t\t\tvar externalUUID *string\n\t\t\tif link != nil {\n\t\t\t\texternalUUID = &link.ExternalID\n\t\t\t}\n\n\t\t\tresult[ownerID] = append(result[ownerID], api.FoundEntityDTO{\n\t\t\t\tEntityType: \"Workstation\",\n\t\t\t\tData: api.WorkstationRichDTO{\n\t\t\t\t\tUUID:         ws.ID,\n\t\t\t\t\tExternalUUID: externalUUID,\n\t\t\t\t\tDeviceName:   ws.DeviceName,\n\t\t\t\t\tStatus:       ws.Status,\n\t\t\t\t\tAnydesk:      ws.Anydesk,\n\t\t\t\t\tTeamviewer:   ws.Teamviewer,\n\t\t\t\t\tLitemanager:  ws.Litemanager,\n\t\t\t\t},\n\t\t\t})\n\t\t}\n\t}\n\treturn result\n}\n\nfunc (h *SearchHandler) groupFRsByOwner(ctx context.Context, frs []models.FiscalRegister) map[string][]api.FoundEntityDTO {\n\tresult := make(map[string][]api.FoundEntityDTO)\n\tfor _, fr := range frs {\n\t\tif fr.OwnerID != nil {\n\t\t\townerID := *fr.OwnerID\n\n\t\t\t// Обогащаем внешним ID\n\t\t\tlink, _ := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", fr.ID)\n\t\t\tvar externalUUID *string\n\t\t\tif link != nil {\n\t\t\t\texternalUUID = &link.ExternalID\n\t\t\t}\n\n\t\t\tresult[ownerID] = append(result[ownerID], api.FoundEntityDTO{\n\t\t\t\tEntityType: \"FiscalRegister\",\n\t\t\t\tData: api.FiscalRegisterRichDTO{\n\t\t\t\t\tUUID:               fr.ID,\n\t\t\t\t\tExternalUUID:       externalUUID,\n\t\t\t\t\tStatus:             fr.Status,\n\t\t\t\t\tRNKKT:              fr.RNKKT,\n\t\t\t\t\tModelKKT:           fr.ModelKKT,\n\t\t\t\t\tFNRegistrationDate: fr.KKTRegDate,\n\t\t\t\t\tFNExpireDate:       fr.FNExpireDate,\n\t\t\t\t\tDriverVersion:      fr.DriverVersion,\n\t\t\t\t\tFRFirmware:         fr.FRFirmware,\n\t\t\t\t\tFRDownloader:       fr.FRDownloader,\n\t\t\t\t\tOrganizationName:   fr.LegalName,\n\t\t\t\t\tINN:                fr.INN,\n\t\t\t\t\tSerialNumber:       fr.FRSerialNumber,\n\t\t\t\t\tIsMarkingActive:    true,\n\t\t\t\t\tIsExciseActive:     false,\n\t\t\t\t},\n\t\t\t})\n\t\t}\n\t}\n\treturn result\n}\n",
    "internal/handlers/server_actions_handler.go": "// internal/handlers/server_actions_handler.go\npackage handlers\n\nimport (\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/services\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// ServerActionsHandler обрабатывает специфичные действия над серверами.\ntype ServerActionsHandler struct {\n\tlogger     *zap.Logger\n\tactionsSvc services.ServerActionsService\n}\n\n// NewServerActionsHandler создает новый экземпляр обработчика.\nfunc NewServerActionsHandler(logger *zap.Logger, actionsSvc services.ServerActionsService) *ServerActionsHandler {\n\treturn &ServerActionsHandler{\n\t\tlogger:     logger,\n\t\tactionsSvc: actionsSvc,\n\t}\n}\n\n// RegisterRoutes регистрирует роуты для действий с серверами.\n// ИЗМЕНЕНИЕ: В URL теперь ожидается внутренний ID, а не UUID.\nfunc (h *ServerActionsHandler) RegisterRoutes(r chi.Router) {\n\tr.Post(\"/servers/{id}/install_license\", h.installLicense)\n\tr.Post(\"/servers/{id}/poll\", h.pollServerStatus)\n\tr.Post(\"/servers/{serverID}/additional_owners\", h.addAdditionalOwner)\n\tr.Delete(\"/servers/{serverID}/additional_owners/{companyID}\", h.removeAdditionalOwner)\n}\n\ntype installLicenseRequestDTO struct {\n\tUniqueID string `json:\"uniqueId\"`\n}\n\n// installLicense обрабатывает запрос на запуск установки лицензии.\nfunc (h *ServerActionsHandler) installLicense(w http.ResponseWriter, r *http.Request) {\n\tserverID := chi.URLParam(r, \"id\")\n\tif serverID == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"ID сервера не указан\")\n\t\treturn\n\t}\n\n\tvar dto installLicenseRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат тела запроса\")\n\t\treturn\n\t}\n\tif dto.UniqueID == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Поле 'uniqueId' обязательно для заполнения\")\n\t\treturn\n\t}\n\n\terr := h.actionsSvc.InstallLicense(r.Context(), serverID, dto.UniqueID)\n\tif err != nil {\n\t\tif errors.Is(err, gorm.ErrRecordNotFound) {\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Сервер с указанным ID не найден\")\n\t\t} else {\n\t\t\th.logger.Error(\"Ошибка при вызове заглушки установки лицензии\", zap.String(\"serverID\", serverID), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusOK, map[string]string{\"message\": \"Команда на установку лицензии отправлена успешно\"})\n}\n\n// pollServerStatus обрабатывает запрос на принудительный асинхронный опрос статуса сервера.\nfunc (h *ServerActionsHandler) pollServerStatus(w http.ResponseWriter, r *http.Request) {\n\tserverID := chi.URLParam(r, \"id\")\n\tif serverID == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"ID сервера не указан\")\n\t\treturn\n\t}\n\n\terr := h.actionsSvc.PollSingleServer(r.Context(), serverID)\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrRateLimitExceeded):\n\t\t\tRespondWithError(w, http.StatusTooManyRequests, \"Превышен лимит запросов на опрос статуса для этого сервера (не более 3 раз в 2 минуты)\")\n\t\tcase errors.Is(err, gorm.ErrRecordNotFound):\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Сервер с указанным ID не найден\")\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка при запуске принудительного опроса\", zap.String(\"serverID\", serverID), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusAccepted, map[string]string{\"message\": \"Задача на опрос статуса сервера принята в обработку\"})\n}\n\ntype additionalOwnerRequestDTO struct {\n\tCompanyID string `json:\"company_id\"` // ИЗМЕНЕНИЕ: Поле переименовано\n}\n\n// addAdditionalOwner обрабатывает запрос на добавление дополнительного владельца.\nfunc (h *ServerActionsHandler) addAdditionalOwner(w http.ResponseWriter, r *http.Request) {\n\tserverID := chi.URLParam(r, \"serverID\")\n\tvar dto additionalOwnerRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат тела запроса\")\n\t\treturn\n\t}\n\tif serverID == \"\" || dto.CompanyID == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"ID сервера и компании обязательны\")\n\t\treturn\n\t}\n\n\terr := h.actionsSvc.AddAdditionalOwner(r.Context(), serverID, dto.CompanyID)\n\tif err != nil {\n\t\tif errors.Is(err, gorm.ErrRecordNotFound) {\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Сервер или компания не найдены\")\n\t\t} else {\n\t\t\th.logger.Error(\"Ошибка при добавлении дополнительного владельца\", zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\tRespondWithJSON(w, http.StatusOK, map[string]string{\"message\": \"Дополнительный владелец успешно добавлен\"})\n}\n\n// removeAdditionalOwner обрабатывает запрос на удаление дополнительного владельца.\nfunc (h *ServerActionsHandler) removeAdditionalOwner(w http.ResponseWriter, r *http.Request) {\n\tserverID := chi.URLParam(r, \"serverID\")\n\tcompanyID := chi.URLParam(r, \"companyID\")\n\n\tif serverID == \"\" || companyID == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"ID сервера и компании обязательны\")\n\t\treturn\n\t}\n\n\terr := h.actionsSvc.RemoveAdditionalOwner(r.Context(), serverID, companyID)\n\tif err != nil {\n\t\tif errors.Is(err, gorm.ErrRecordNotFound) {\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Сервер или компания не найдены\")\n\t\t} else {\n\t\t\th.logger.Error(\"Ошибка при удалении дополнительного владельца\", zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера\")\n\t\t}\n\t\treturn\n\t}\n\tw.WriteHeader(http.StatusNoContent)\n}\n",
    "internal/handlers/sync_handlers.go": "// internal/handlers/sync_handlers.go\npackage handlers\n\nimport (\n\t\"etalon-server/internal/seeder\"\n\t\"net/http\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n)\n\n// SyncHandler обрабатывает запросы, связанные с наполнением базы.\ntype SyncHandler struct {\n\tlogger    *zap.Logger\n\tseeder    *seeder.Seeder\n\tseederKey string\n}\n\n// NewSyncHandler создает новый обработчик синхронизации.\nfunc NewSyncHandler(logger *zap.Logger, seeder *seeder.Seeder, seederKey string) *SyncHandler {\n\treturn &SyncHandler{\n\t\tlogger:    logger,\n\t\tseeder:    seeder,\n\t\tseederKey: seederKey,\n\t}\n}\n\n// RegisterRoutes регистрирует роуты для этого обработчика.\nfunc (h *SyncHandler) RegisterRoutes(router chi.Router) {\n\trouter.Post(\"/seed\", h.TriggerSeed)\n\t// router.Post(\"/contracts\", h.TriggerContractSync) // ИЗМЕНЕНИЕ: Удаляем ручку\n}\n\n// TriggerSeed запускает фоновое наполнение базы данных из мок-файлов.\nfunc (h *SyncHandler) TriggerSeed(w http.ResponseWriter, r *http.Request) {\n\tkey := r.URL.Query().Get(\"key\")\n\tif key == \"\" || key != h.seederKey {\n\t\tRespondWithError(w, http.StatusUnauthorized, \"Неверный или отсутствует ключ доступа\")\n\t\treturn\n\t}\n\n\tgo func() {\n\t\th.logger.Info(\"Запуск наполнения БД через API...\")\n\t\tmockClient := seeder.NewMockServiceDeskClient(h.logger, \"./tools/seeder/mock_data\")\n\t\tif err := h.seeder.SeedDatabase(mockClient); err != nil {\n\t\t\th.logger.Error(\"Процесс наполнения БД завершился с ошибкой\", zap.Error(err))\n\t\t} else {\n\t\t\th.logger.Info(\"Процесс наполнения БД, запущенный через API, успешно завершен.\")\n\t\t}\n\t}()\n\n\tRespondWithJSON(w, http.StatusAccepted, map[string]string{\n\t\t\"message\": \"Наполнение базы данных запущено в фоновом режиме\",\n\t})\n}\n",
    "internal/handlers/task_handler.go": "package handlers\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/services\"\n\t\"etalon-server/internal/utils\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"sort\"\n\t\"strconv\"\n\t\"time\"\n\n\t\"github.com/go-chi/chi/v5\"\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// TaskHandler обрабатывает запросы, связанные с задачами сверки и поиском дубликатов.\ntype TaskHandler struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tresolutionSvc   services.TaskResolutionService\n\tsdEditorSvc     services.SDEditorService\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\tlinkRepo        repositories.LinkRepo\n}\n\n// NewTaskHandler создает новый экземпляр обработчика.\nfunc NewTaskHandler(\n\tlogger *zap.Logger,\n\tdb *gorm.DB,\n\tresolutionSvc services.TaskResolutionService,\n\tsdEditorSvc services.SDEditorService,\n\tserverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo,\n\tlinkRepo repositories.LinkRepo,\n) *TaskHandler {\n\treturn &TaskHandler{\n\t\tlogger:          logger,\n\t\tdb:              db,\n\t\tresolutionSvc:   resolutionSvc,\n\t\tsdEditorSvc:     sdEditorSvc,\n\t\tserverRepo:      serverRepo,\n\t\tworkstationRepo: workstationRepo,\n\t\tfrRepo:          frRepo,\n\t\tlinkRepo:        linkRepo,\n\t}\n}\n\n// RegisterRoutes регистрирует роуты для задач и дубликатов.\nfunc (h *TaskHandler) RegisterRoutes(r chi.Router) {\n\tr.Get(\"/tasks\", h.GetTasks)\n\tr.Post(\"/tasks/{id}/resolve\", h.ResolveTask)\n\tr.Post(\"/tasks/{id}/create-entity-in-sd\", h.createEntityFromTask)\n\tr.Get(\"/duplicates\", h.GetDuplicates)\n}\n\n// GetTasks возвращает список задач сверки с фильтрацией, пагинацией и обогащенными данными.\nfunc (h *TaskHandler) GetTasks(w http.ResponseWriter, r *http.Request) {\n\tstatus := r.URL.Query().Get(\"status\")\n\tlimitStr := r.URL.Query().Get(\"limit\")\n\toffsetStr := r.URL.Query().Get(\"offset\")\n\n\tlimit, err := strconv.Atoi(limitStr)\n\tif err != nil || limit <= 0 {\n\t\tlimit = 50\n\t}\n\toffset, err := strconv.Atoi(offsetStr)\n\tif err != nil || offset < 0 {\n\t\toffset = 0\n\t}\n\n\tvar tasks []models.ReconciliationTask\n\tquery := h.db.Model(&models.ReconciliationTask{})\n\tif status != \"\" {\n\t\tquery = query.Where(\"status = ?\", status)\n\t}\n\terr = query.Limit(limit).Offset(offset).Order(\"created_at desc\").Find(&tasks).Error\n\tif err != nil {\n\t\th.logger.Error(\"Не удалось получить задачи из БД\", zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Ошибка получения списка задач\")\n\t\treturn\n\t}\n\n\ttaskDTOs := make([]api.TaskDTO, 0, len(tasks))\n\tfor _, task := range tasks {\n\t\tdto := api.TaskDTO{\n\t\t\tID: task.ID, TaskType: task.TaskType, EntityType: task.EntityType,\n\t\t\tEntityUUID: task.EntityUUID, Status: task.Status, Comment: task.Comment,\n\t\t\tCreatedAt: task.CreatedAt, UpdatedAt: task.UpdatedAt,\n\t\t}\n\t\tvar detailsObject interface{}\n\n\t\tswitch task.TaskType {\n\t\tcase \"add_equipment\":\n\t\t\tvar details struct {\n\t\t\t\tAgentData       api.AgentDataDTO `json:\"agent_data\"`\n\t\t\t\tEtalonOwnerUUID string           `json:\"etalon_owner_id\"` // Имя поля исправлено\n\t\t\t}\n\t\t\tif err := json.Unmarshal(task.Details, &details); err == nil {\n\t\t\t\tvar richDetails interface{}\n\t\t\t\tif task.EntityType == \"FiscalRegister\" {\n\t\t\t\t\trichDetails = struct {\n\t\t\t\t\t\tEtalonOwnerID    string                    `json:\"etalon_owner_id\"`\n\t\t\t\t\t\tEquipmentData    api.FiscalRegisterRichDTO `json:\"equipment_data\"`\n\t\t\t\t\t\tOrganizationName string                    `json:\"organizationName\"`\n\t\t\t\t\t\tSerialNumber     string                    `json:\"serialNumber\"`\n\t\t\t\t\t\tURLRms           string                    `json:\"url_rms\"`\n\t\t\t\t\t\tTeamviewerID     string                    `json:\"teamviewer_id\"`\n\t\t\t\t\t\tAnydeskID        string                    `json:\"anydesk_id\"`\n\t\t\t\t\t\tLitemanagerID    string                    `json:\"litemanager_id\"`\n\t\t\t\t\t\tAgentCurrentTime string                    `json:\"agent_current_time\"`\n\t\t\t\t\t}{\n\t\t\t\t\t\tEtalonOwnerID:    details.EtalonOwnerUUID, // Используем внутренний ID\n\t\t\t\t\t\tEquipmentData:    agentDataToFiscalRegisterRichDTO(details.AgentData),\n\t\t\t\t\t\tOrganizationName: details.AgentData.OrganizationName,\n\t\t\t\t\t\tSerialNumber:     details.AgentData.SerialNumber,\n\t\t\t\t\t\tURLRms:           details.AgentData.URLRms,\n\t\t\t\t\t\tTeamviewerID:     details.AgentData.TeamviewerID,\n\t\t\t\t\t\tAnydeskID:        details.AgentData.AnydeskID,\n\t\t\t\t\t\tLitemanagerID:    details.AgentData.LitemanagerID,\n\t\t\t\t\t\tAgentCurrentTime: details.AgentData.CurrentTime,\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tdetailsObject = richDetails\n\t\t\t} else {\n\t\t\t\tdetailsObject = task.Details\n\t\t\t}\n\t\tcase \"need_update\", \"data_conflict\", \"resolve_duplicate\":\n\t\t\tdetailsObject = task.Details\n\t\tdefault:\n\t\t\tvar richDetails interface{}\n\t\t\tswitch task.EntityType {\n\t\t\tcase \"FiscalRegister\":\n\t\t\t\tif fr, _ := h.frRepo.GetByID(r.Context(), task.EntityUUID); fr != nil {\n\t\t\t\t\trichDetails = h.modelToFiscalRegisterRichDTO(r.Context(), *fr)\n\t\t\t\t}\n\t\t\tcase \"Server\":\n\t\t\t\tif server, _ := h.serverRepo.GetByID(r.Context(), task.EntityUUID); server != nil {\n\t\t\t\t\trichDetails = h.modelToServerRichDTO(r.Context(), *server)\n\t\t\t\t}\n\t\t\tcase \"Workstation\":\n\t\t\t\tif ws, _ := h.workstationRepo.GetByID(r.Context(), task.EntityUUID); ws != nil {\n\t\t\t\t\trichDetails = h.modelToWorkstationRichDTO(r.Context(), *ws)\n\t\t\t\t}\n\t\t\t}\n\t\t\tif richDetails != nil {\n\t\t\t\tdetailsObject = richDetails\n\t\t\t} else {\n\t\t\t\tdetailsObject = task.Details\n\t\t\t}\n\t\t}\n\n\t\tvar detailsMap map[string]interface{}\n\t\tdetailsBytes, err := json.Marshal(detailsObject)\n\t\tif err == nil {\n\t\t\tjson.Unmarshal(detailsBytes, &detailsMap)\n\t\t} else if rawJson, ok := detailsObject.(json.RawMessage); ok {\n\t\t\tjson.Unmarshal(rawJson, &detailsMap)\n\t\t}\n\t\tif detailsMap == nil {\n\t\t\tdetailsMap = make(map[string]interface{})\n\t\t}\n\n\t\t// Добавляем externalUUID в details для задач, связанных с существующими сущностями.\n\t\tif task.EntityType != \"\" && task.EntityUUID != \"\" && task.TaskType != \"add_equipment\" {\n\t\t\tlink, _ := h.linkRepo.GetByInternalID(r.Context(), nil, \"naumen\", task.EntityUUID)\n\t\t\tif link != nil {\n\t\t\t\tdetailsMap[\"externalUUID\"] = link.ExternalID\n\t\t\t}\n\t\t}\n\t\tdto.Details = detailsMap\n\t\ttaskDTOs = append(taskDTOs, dto)\n\t}\n\tRespondWithJSON(w, http.StatusOK, taskDTOs)\n}\n\n// ResolveTask изменяет статус задачи и выполняет связанные с решением действия.\nfunc (h *TaskHandler) ResolveTask(w http.ResponseWriter, r *http.Request) {\n\ttaskIDStr := chi.URLParam(r, \"id\")\n\ttaskID, err := strconv.ParseUint(taskIDStr, 10, 32)\n\tif err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Некорректный ID задачи\")\n\t\treturn\n\t}\n\n\tvar dto api.ResolveTaskRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Некорректное тело запроса\")\n\t\treturn\n\t}\n\n\tif dto.Status == \"\" {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Поле 'status' обязательно для заполнения\")\n\t\treturn\n\t}\n\n\tupdatedTask, err := h.resolutionSvc.Resolve(r.Context(), uint(taskID), &dto)\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrTaskNotFound):\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Задача не найдена\")\n\t\tcase errors.Is(err, services.ErrTaskAlreadyDone):\n\t\t\tRespondWithError(w, http.StatusConflict, \"Задача уже была решена или отклонена\")\n\t\tcase errors.Is(err, services.ErrInvalidPayload):\n\t\t\tRespondWithError(w, http.StatusBadRequest, err.Error())\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка при решении задачи\", zap.Uint64(\"taskID\", taskID), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Внутренняя ошибка сервера при решении задачи\")\n\t\t}\n\t\treturn\n\t}\n\n\t// Проверяем статус для корректного HTTP-ответа\n\tif updatedTask.Status == \"pending_sd_action\" {\n\t\tresponse := api.AcceptedResponseDTO{\n\t\t\tMessage: \"Запрос на операцию в ServiceDesk принят в обработку.\",\n\t\t\tTaskID:  updatedTask.ID,\n\t\t}\n\t\tRespondWithJSON(w, http.StatusAccepted, response)\n\t} else {\n\t\t// Для всех остальных случаев (включая 'resolved', 'rejected') возвращаем 200 OK\n\t\tRespondWithJSON(w, http.StatusOK, updatedTask)\n\t}\n}\n\n// createEntityFromTask обрабатывает запрос на создание сущности в ServiceDesk на основе задачи.\nfunc (h *TaskHandler) createEntityFromTask(w http.ResponseWriter, r *http.Request) {\n\ttaskIDStr := chi.URLParam(r, \"id\")\n\ttaskID, err := strconv.ParseUint(taskIDStr, 10, 32)\n\tif err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Некорректный ID задачи\")\n\t\treturn\n\t}\n\n\tvar dto api.CreateEntityInSDRequestDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\tRespondWithError(w, http.StatusBadRequest, \"Неверный формат тела запроса\")\n\t\treturn\n\t}\n\t// TODO: Добавить валидацию DTO\n\n\t// Вызываем новый асинхронный метод\n\tupdatedTask, err := h.resolutionSvc.RequestSDEntityCreation(r.Context(), uint(taskID), dto.EntityType)\n\n\tif err != nil {\n\t\tswitch {\n\t\tcase errors.Is(err, services.ErrTaskNotFound):\n\t\t\tRespondWithError(w, http.StatusNotFound, \"Задача не найдена\")\n\t\tcase errors.Is(err, services.ErrTaskAlreadyDone):\n\t\t\tRespondWithError(w, http.StatusConflict, \"Задача уже находится в обработке или решена\")\n\t\tdefault:\n\t\t\th.logger.Error(\"Ошибка при отправке запроса на создание сущности в ServiceDesk\",\n\t\t\t\tzap.Uint64(\"taskID\", taskID),\n\t\t\t\tzap.String(\"entityType\", dto.EntityType),\n\t\t\t\tzap.Error(err),\n\t\t\t)\n\t\t\tRespondWithError(w, http.StatusInternalServerError, fmt.Sprintf(\"Внутренняя ошибка: %v\", err))\n\t\t}\n\t\treturn\n\t}\n\n\t// Отвечаем 202 Accepted\n\tresponse := api.AcceptedResponseDTO{\n\t\tMessage: \"Запрос на создание сущности в ServiceDesk принят в обработку.\",\n\t\tTaskID:  updatedTask.ID,\n\t}\n\tRespondWithJSON(w, http.StatusAccepted, response)\n}\n\n// GetDuplicates находит и возвращает группы дубликатов в формате JSON.\nfunc (h *TaskHandler) GetDuplicates(w http.ResponseWriter, r *http.Request) {\n\tvar allGroups []api.DuplicateGroupDTO\n\n\twsFields := []string{\"anydesk\", \"teamviewer\", \"litemanager\"}\n\tfor _, field := range wsFields {\n\t\tgroups, err := h.findDuplicateGroups(field, \"Workstation\")\n\t\tif err != nil {\n\t\t\th.logger.Error(\"Ошибка поиска дубликатов Workstation\", zap.String(\"field\", field), zap.Error(err))\n\t\t\tRespondWithError(w, http.StatusInternalServerError, \"Ошибка поиска дубликатов\")\n\t\t\treturn\n\t\t}\n\t\tallGroups = append(allGroups, groups...)\n\t}\n\n\tserverGroups, err := h.findDuplicateGroups(\"ip\", \"Server\")\n\tif err != nil {\n\t\th.logger.Error(\"Ошибка поиска дубликатов Server\", zap.String(\"field\", \"ip\"), zap.Error(err))\n\t\tRespondWithError(w, http.StatusInternalServerError, \"Ошибка поиска дубликатов\")\n\t\treturn\n\t}\n\tallGroups = append(allGroups, serverGroups...)\n\n\tRespondWithJSON(w, http.StatusOK, allGroups)\n}\n\nfunc (h *TaskHandler) findDuplicateGroups(field string, entityType string) ([]api.DuplicateGroupDTO, error) {\n\tvar results []struct {\n\t\tValue string\n\t\tCount int\n\t}\n\tmodel := h.getModel(entityType)\n\tif model == nil {\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности: %s\", entityType)\n\t}\n\n\terr := h.db.Model(model).\n\t\tSelect(fmt.Sprintf(\"%s as value, count(*) as count\", field)).\n\t\tWhere(fmt.Sprintf(\"%s IS NOT NULL AND %s != ''\", field, field)).\n\t\tGroup(field).\n\t\tHaving(\"count(*) > 1\").\n\t\tFind(&results).Error\n\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\tvar groups []api.DuplicateGroupDTO\n\tfor _, res := range results {\n\t\tvar records []interface{}\n\t\tswitch entityType {\n\t\tcase \"Workstation\":\n\t\t\tvar wsRecords []models.Workstation\n\t\t\th.db.Where(fmt.Sprintf(\"%s = ?\", field), res.Value).Find(&wsRecords)\n\t\t\tfor i := range wsRecords {\n\t\t\t\trecords = append(records, wsRecords[i])\n\t\t\t}\n\t\tcase \"Server\":\n\t\t\tvar srvRecords []models.Server\n\t\t\th.db.Where(fmt.Sprintf(\"%s = ?\", field), res.Value).Find(&srvRecords)\n\t\t\tfor i := range srvRecords {\n\t\t\t\trecords = append(records, srvRecords[i])\n\t\t\t}\n\t\t}\n\n\t\tif len(records) < 2 {\n\t\t\tcontinue\n\t\t}\n\n\t\tsort.Slice(records, func(i, j int) bool {\n\t\t\tdateI := getLMDFromInterface(records[i])\n\t\t\tdateJ := getLMDFromInterface(records[j])\n\t\t\tif dateI == nil {\n\t\t\t\treturn false\n\t\t\t}\n\t\t\tif dateJ == nil {\n\t\t\t\treturn true\n\t\t\t}\n\t\t\treturn dateI.After(*dateJ)\n\t\t})\n\n\t\tgroups = append(groups, api.DuplicateGroupDTO{\n\t\t\tField:      field,\n\t\t\tValue:      res.Value,\n\t\t\tMainRecord: records[0],\n\t\t\tDuplicates: records[1:],\n\t\t\tEntityType: entityType,\n\t\t})\n\t}\n\treturn groups, nil\n}\n\nfunc (h *TaskHandler) getModel(entityType string) interface{} {\n\tswitch entityType {\n\tcase \"Workstation\":\n\t\treturn &models.Workstation{}\n\tcase \"Server\":\n\t\treturn &models.Server{}\n\tdefault:\n\t\treturn nil\n\t}\n}\n\nfunc getLMDFromInterface(record interface{}) *time.Time {\n\tswitch v := record.(type) {\n\tcase models.Workstation:\n\t\treturn v.LastModifiedDate\n\tcase models.Server:\n\t\treturn v.LastModifiedDate\n\tcase models.FiscalRegister:\n\t\treturn v.LastModifiedDate\n\tdefault:\n\t\treturn nil\n\t}\n}\n\n// --- Вспомогательные функции-мапперы ---\n\n// agentDataToFiscalRegisterRichDTO преобразует сырые данные от агента в компактный DTO для UI.\nfunc agentDataToFiscalRegisterRichDTO(data api.AgentDataDTO) api.FiscalRegisterRichDTO {\n\treturn api.FiscalRegisterRichDTO{\n\t\tRNKKT:              &data.RNM,\n\t\tModelKKT:           &data.ModelName,\n\t\tFNExpireDate:       utils.ParseAgentTime(data.DateTimeEnd),\n\t\tFNRegistrationDate: utils.ParseAgentTime(data.DateTimeReg),\n\t\tDriverVersion:      &data.InstalledDriver,\n\t\tFRFirmware:         utils.StringPtr(utils.CalculateFRFirmware(data.Licenses)),\n\t\tFRDownloader:       utils.StringPtr(data.BootVersion),\n\t}\n}\n\n// modelToFiscalRegisterRichDTO преобразует модель БД в DTO для UI.\n// modelToFiscalRegisterRichDTO преобразует модель БД в DTO для UI, обогащая внешним ID.\nfunc (h *TaskHandler) modelToFiscalRegisterRichDTO(ctx context.Context, fr models.FiscalRegister) api.FiscalRegisterRichDTO {\n\tdto := api.FiscalRegisterRichDTO{\n\t\tUUID:               fr.ID, // ИСПОЛЬЗУЕМ ВНУТРЕННИЙ ID\n\t\tStatus:             fr.Status,\n\t\tRNKKT:              fr.RNKKT,\n\t\tModelKKT:           fr.ModelKKT,\n\t\tFNRegistrationDate: fr.KKTRegDate,\n\t\tFNExpireDate:       fr.FNExpireDate,\n\t\tDriverVersion:      fr.DriverVersion,\n\t\tFRFirmware:         fr.FRFirmware,\n\t\tFRDownloader:       fr.FRDownloader,\n\t\tOrganizationName:   fr.LegalName,\n\t\tINN:                fr.INN,\n\t\tSerialNumber:       fr.FRSerialNumber,\n\t\tIsMarkingActive:    true,\n\t\tIsExciseActive:     false,\n\t}\n\tlink, err := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", fr.ID)\n\tif err == nil && link != nil {\n\t\tdto.ExternalUUID = &link.ExternalID\n\t}\n\treturn dto\n}\n\n// modelToServerRichDTO преобразует модель БД в DTO для UI, обогащая внешним ID.\nfunc (h *TaskHandler) modelToServerRichDTO(ctx context.Context, server models.Server) api.ServerRichDTO {\n\tdto := api.ServerRichDTO{\n\t\tUUID:        server.ID, // ИСПОЛЬЗУЕМ ВНУТРЕННИЙ ID\n\t\tDeviceName:  server.DeviceName,\n\t\tIP:          server.IP,\n\t\tStatus:      server.Status,\n\t\tAnydesk:     server.Anydesk,\n\t\tTeamviewer:  server.Teamviewer,\n\t\tRDP:         server.RDP,\n\t\tLitemanager: server.Litemanager,\n\t\tUniqueID:    server.UniqueID,\n\t}\n\tlink, err := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", server.ID)\n\tif err == nil && link != nil {\n\t\tdto.ExternalUUID = &link.ExternalID\n\t}\n\treturn dto\n}\n\n// modelToWorkstationRichDTO преобразует модель БД в DTO для UI, обогащая внешним ID.\nfunc (h *TaskHandler) modelToWorkstationRichDTO(ctx context.Context, ws models.Workstation) api.WorkstationRichDTO {\n\tdto := api.WorkstationRichDTO{\n\t\tUUID:        ws.ID, // ИСПОЛЬЗУЕМ ВНУТРЕННИЙ ID\n\t\tDeviceName:  ws.DeviceName,\n\t\tStatus:      ws.Status,\n\t\tAnydesk:     ws.Anydesk,\n\t\tTeamviewer:  ws.Teamviewer,\n\t\tLitemanager: ws.Litemanager,\n\t}\n\tlink, err := h.linkRepo.GetByInternalID(ctx, nil, \"naumen\", ws.ID)\n\tif err == nil && link != nil {\n\t\tdto.ExternalUUID = &link.ExternalID\n\t}\n\treturn dto\n}\n",
    "internal/logger/logger.go": "package logger\n\nimport (\n\t\"os\"\n\t\"path/filepath\"\n\t\"strings\"\n\n\t\"github.com/natefinch/lumberjack\"\n\t\"go.uber.org/zap\"\n\t\"go.uber.org/zap/zapcore\"\n)\n\n// New инициализирует логгер zap.\n// Он может писать логи как в консоль, так и в файл с ротацией.\nfunc New(logDir, loggerName, logLevel string, disableFileLogging bool) *zap.Logger {\n\tlevel := getZapLevel(logLevel)\n\t// Конфигурация для логгирования в консоль\n\tconsoleCore := zapcore.NewCore(\n\t\tzapcore.NewConsoleEncoder(zap.NewDevelopmentEncoderConfig()),\n\t\tzapcore.Lock(os.Stdout),\n\t\tlevel,\n\t)\n\n\tcores := []zapcore.Core{consoleCore}\n\n\t// Конфигурация для логгирования в файл с ротацией\n\tif !disableFileLogging {\n\t\t// Создаем директорию для логов, если ее нет\n\t\tif err := os.MkdirAll(logDir, 0755); err != nil {\n\t\t\t// В случае ошибки просто не будем писать в файл\n\t\t\tconsoleLogger := zap.New(consoleCore)\n\t\t\tconsoleLogger.Error(\"Не удалось создать директорию для логов, файловое логирование отключено.\", zap.String(\"dir\", logDir), zap.Error(err))\n\t\t} else {\n\t\t\tlogPath := filepath.Join(logDir, loggerName+\".log\")\n\t\t\tfileWriter := zapcore.AddSync(&lumberjack.Logger{\n\t\t\t\tFilename:   logPath,\n\t\t\t\tMaxSize:    10, // megabytes\n\t\t\t\tMaxBackups: 3,\n\t\t\t\tMaxAge:     28, // days\n\t\t\t\tCompress:   true,\n\t\t\t})\n\n\t\t\tfileCore := zapcore.NewCore(\n\t\t\t\tzapcore.NewJSONEncoder(zap.NewProductionEncoderConfig()),\n\t\t\t\tfileWriter,\n\t\t\t\tlevel,\n\t\t\t)\n\t\t\tcores = append(cores, fileCore)\n\t\t}\n\t}\n\n\t// Объединяем ядра для вывода в несколько мест\n\tcore := zapcore.NewTee(cores...)\n\n\t// Создаем логгер с опцией AddCaller для вывода имени файла и строки\n\tlogger := zap.New(core, zap.AddCaller(), zap.AddStacktrace(zapcore.ErrorLevel), zap.Fields(zap.String(\"logger\", loggerName)))\n\n\treturn logger\n}\n\n// getZapLevel преобразует строковый уровень логирования в zapcore.Level.\nfunc getZapLevel(level string) zapcore.Level {\n\tswitch strings.ToLower(level) {\n\tcase \"debug\":\n\t\treturn zap.DebugLevel\n\tcase \"info\":\n\t\treturn zap.InfoLevel\n\tcase \"warn\", \"warning\":\n\t\treturn zap.WarnLevel\n\tcase \"error\":\n\t\treturn zap.ErrorLevel\n\tcase \"fatal\":\n\t\treturn zap.FatalLevel\n\tdefault:\n\t\treturn zap.InfoLevel\n\t}\n}\n",
    "internal/models/models.go": "// internal/models/models.go\npackage models\n\nimport (\n\t\"time\"\n\n\t\"github.com/google/uuid\"\n\t\"golang.org/x/crypto/bcrypt\"\n\t\"gorm.io/datatypes\"\n\t\"gorm.io/gorm\"\n)\n\n// ExternalSystemLink хранит связь между нашей внутренней сущностью и ее ID во внешней системе.\ntype ExternalSystemLink struct {\n\tInternalID   string `gorm:\"primaryKey;type:text\"`        // UUID нашей сущности (из поля Base.ID)\n\tSystemName   string `gorm:\"primaryKey;type:varchar(50)\"` // Название внешней системы, например, \"servicedesk\", \"zabbix\"\n\tExternalID   string `gorm:\"type:text;unique;not null\"`   // ID сущности во внешней системе\n\tEntityType   string `gorm:\"type:varchar(50);not null\"`   // Тип нашей сущности: \"Company\", \"Server\" и т.д.\n\tLastSyncedAt time.Time\n}\n\n// Константы для статусов агента\nconst (\n\tStatusPendingOwner       = \"pending_owner\"\n\tStatusPendingZabbix      = \"pending_zabbix_registration\"\n\tStatusActive             = \"active\"\n\tStatusRegistrationFailed = \"registration_failed\"\n)\n\n// Base содержит общие поля для всех моделей.\ntype Base struct {\n\tID            string `gorm:\"primaryKey;type:text\"`\n\tMetaClass     string `gorm:\"type:text\"`\n\tLastUpdatedBy string `gorm:\"type:varchar(50);default:'unknown'\"`\n\tCreatedAt     time.Time\n\tUpdatedAt     time.Time\n\tDeletedAt     gorm.DeletedAt `gorm:\"index\"`\n}\n\n// BeforeCreate будет вызван GORM перед созданием записи.\nfunc (base *Base) BeforeCreate(tx *gorm.DB) (err error) {\n\tif base.ID == \"\" {\n\t\tbase.ID = uuid.New().String()\n\t}\n\treturn\n}\n\n// Company представляет сущность компании.\ntype Company struct {\n\tBase\n\tAddress          *string    `gorm:\"type:text\"`\n\tTitle            *string    `gorm:\"type:text\"`\n\tActiveContract   *bool      `gorm:\"type:boolean\"`\n\tLastModifiedDate *time.Time `json:\"last_modified_date\"`\n\tAdditionalName   *string    `gorm:\"type:text\"`\n\tParentID         *string    `gorm:\"type:text\"`\n\tParent           *Company   `gorm:\"foreignKey:ParentID\"`\n\n\tContracts       []Contract       `gorm:\"many2many:company_contracts;\"`\n\tServers         []Server         `gorm:\"foreignKey:OwnerID\"`\n\tWorkstations    []Workstation    `gorm:\"foreignKey:OwnerID\"`\n\tFiscalRegisters []FiscalRegister `gorm:\"foreignKey:OwnerID\"`\n}\n\n// Contract представляет сущность контракта.\ntype Contract struct {\n\tBase\n\tState            *string `gorm:\"type:varchar(50);index\"`\n\tStateStartTime   *time.Time\n\tServices         datatypes.JSON `gorm:\"type:jsonb\"`\n\tRecipients       datatypes.JSON `gorm:\"type:jsonb\"`\n\tLastModifiedDate *time.Time     `json:\"last_modified_date\"`\n\tServiceLevel     int            `gorm:\"default:-1;index\"`\n\tCompanies        []Company      `gorm:\"many2many:company_contracts;\"`\n}\n\ntype CompanyContract struct {\n\tCompanyID  string   `gorm:\"primaryKey\"`\n\tCompany    Company  `gorm:\"foreignKey:CompanyID\"`\n\tContractID string   `gorm:\"primaryKey\"`\n\tContract   Contract `gorm:\"foreignKey:ContractID\"`\n}\n\n// Server представляет сущность сервера.\ntype Server struct {\n\tBase\n\tUniqueID         *string    `gorm:\"type:text\"`\n\tCRMid            *string    `gorm:\"column:crm_id;type:text;index\"`\n\tTeamviewer       *string    `gorm:\"type:text\"`\n\tRDP              *string    `gorm:\"type:text\"`\n\tAnydesk          *string    `gorm:\"type:text\"`\n\tIP               *string    `gorm:\"type:text\"`\n\tCabinetLink      *string    `gorm:\"type:text\"`\n\tDeviceName       *string    `gorm:\"type:text;index\"`\n\tLastModifiedDate *time.Time `json:\"last_modified_date\"`\n\tLitemanager      *string    `gorm:\"type:text\"`\n\tServerVersion    *string    `gorm:\"type:text\"`\n\tDescription      *string    `gorm:\"type:text\"`\n\tOwnerID          *string    `gorm:\"type:text;index\"`\n\n\tAdditionalOwners []Company `gorm:\"many2many:server_additional_owners;foreignKey:ID;joinForeignKey:ServerID;references:ID;joinReferences:CompanyID\"`\n\n\tServerName       *string    `gorm:\"type:text\"`\n\tServerEdition    *string    `gorm:\"type:varchar(50)\"`\n\tLastPolledAt     *time.Time `gorm:\"column:last_polled_at\"`\n\tStatus           string     `gorm:\"type:varchar(50);default:'unknown';index\"`\n\tStatusBeforeLock *string    `gorm:\"type:varchar(50)\"`\n}\n\n// Workstation представляет сущность рабочей станции.\ntype Workstation struct {\n\tBase\n\tTeamviewer       *string    `gorm:\"type:text\"`\n\tAnydesk          *string    `gorm:\"type:text\"`\n\tLitemanager      *string    `gorm:\"type:text\"`\n\tDeviceName       *string    `gorm:\"type:text\"`\n\tLastModifiedDate *time.Time `json:\"last_modified_date\"`\n\tDescription      *string    `gorm:\"type:text\"`\n\tStatus           *string    `gorm:\"type:varchar(50);default:'offline'\"`\n\tStatusBeforeLock *string    `gorm:\"type:varchar(50)\"`\n\tOwnerID          *string    `gorm:\"type:text;index\"`\n}\n\n// FiscalRegister представляет сущность фискального регистратора.\ntype FiscalRegister struct {\n\tBase\n\tModelKKT         *string        `gorm:\"type:text\"`\n\tFFD              *string        `gorm:\"type:text\"`\n\tRNKKT            *string        `gorm:\"column:rn_kkt;type:text;index\"`\n\tLegalName        *string        `gorm:\"type:text\"`\n\tINN              *string        `gorm:\"column:inn;type:text;index\"`\n\tFRSerialNumber   *string        `gorm:\"type:text;index\"`\n\tFNNumber         *string        `gorm:\"type:text\"`\n\tKKTRegDate       *time.Time     `json:\"kkt_reg_date\"`\n\tFNExpireDate     *time.Time     `json:\"fn_expire_date\"`\n\tLastModifiedDate *time.Time     `json:\"last_modified_date\"`\n\tFRDownloader     *string        `gorm:\"type:varchar(100)\"`\n\tFRFirmware       *string        `gorm:\"type:text\"`\n\tDriverVersion    *string        `gorm:\"type:varchar(50)\"`\n\tStatus           *string        `gorm:\"type:varchar(50);default:'offline'\"`\n\tStatusBeforeLock *string        `gorm:\"type:varchar(50)\"`\n\tOwnerID          *string        `gorm:\"type:text;index\"`\n\tLicenses         datatypes.JSON `gorm:\"type:jsonb\"`\n}\n\n// Agent представляет экземпляр агента, установленного на машине клиента.\ntype Agent struct {\n\tUUID           string         `gorm:\"primaryKey;type:text\"`\n\tType           string         `gorm:\"type:varchar(50);not null\"`\n\tOwnerID        string         `gorm:\"type:text;index\"`\n\tConfig         datatypes.JSON `gorm:\"type:jsonb\"`\n\tLastHeartbeat  time.Time\n\tVersion        string `gorm:\"type:varchar(50)\"`\n\tHostname       string `gorm:\"type:text\"`\n\tZabbixHostname string `gorm:\"type:text\"`\n\tStatus         string `gorm:\"type:varchar(50);index\"`\n\tCreatedAt      time.Time\n\tUpdatedAt      time.Time\n}\n\ntype AgentFile struct {\n\tFileName              string    `gorm:\"primaryKey;type:text\"`\n\tLastProcessedModTime  time.Time `gorm:\"not null\"`\n\tLastProcessedFileSize int64     `gorm:\"not null\"`\n\tLastSeenFRSerial      *string   `gorm:\"type:text;index\"`\n\tLastSeenRMSUrl        *string   `gorm:\"type:text\"`\n\tCreatedAt             time.Time\n\tUpdatedAt             time.Time\n}\n\ntype ReconciliationTask struct {\n\tID         uint           `gorm:\"primarykey\"`\n\tTaskType   string         `gorm:\"type:varchar(50);not null;index\"`\n\tEntityType string         `gorm:\"type:varchar(50)\"`\n\tEntityUUID string         `gorm:\"type:text\"`\n\tDetails    datatypes.JSON `gorm:\"type:jsonb\"`\n\tStatus     string         `gorm:\"type:varchar(50);default:'new';index\"`\n\tComment    string         `gorm:\"type:text\"`\n\tCreatedAt  time.Time\n\tUpdatedAt  time.Time\n}\n\ntype User struct {\n\tID           uint           `gorm:\"primarykey\"`\n\tUsername     string         `gorm:\"type:varchar(100);uniqueIndex;not null\"`\n\tPasswordHash string         `gorm:\"type:text;not null\"`\n\tFullName     string         `gorm:\"type:text\"`\n\tRoles        datatypes.JSON `gorm:\"type:jsonb\"`\n\tCreatedAt    time.Time\n\tUpdatedAt    time.Time\n}\n\nfunc (u *User) HashPassword(password string) error {\n\tbytes, err := bcrypt.GenerateFromPassword([]byte(password), 14)\n\tif err != nil {\n\t\treturn err\n\t}\n\tu.PasswordHash = string(bytes)\n\treturn nil\n}\n\nfunc (u *User) CheckPassword(password string) bool {\n\terr := bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(password))\n\treturn err == nil\n}\n",
    "internal/plugins/naumen/client.go": "package naumen\n\nimport (\n\t\"bytes\"\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/internal/validators\"\n\t\"fmt\"\n\t\"io\"\n\t\"net\"\n\t\"net/http\"\n\t\"regexp\"\n\t\"strings\"\n\t\"sync\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"golang.org/x/time/rate\"\n\t\"gorm.io/datatypes\"\n\t\"gorm.io/gorm\"\n)\n\n// карты атрибутов, специфичные для Naumen ServiceDesk.\nvar attrsMap = map[string]string{\n\t\"ou$company\":             \"adress,UUID,title,lastModifiedDate,additionalName,parent,recipientAgreements\",\n\t\"objectBase$Server\":      \"UniqueID,Teamviewer,RDP,AnyDesk,UUID,IP,CabinetLink,DeviceName,lastModifiedDate,iikoVersion,description,nameforclient,owner,litemanagerID\",\n\t\"objectBase$Workstation\": \"Commentariy,Teamviewer,AnyDesk,DeviceName,litemanagerID,lastModifiedDate,UUID,owner\",\n\t\"objectBase$FR\":          \"UUID,ModelKKT,lastModifiedDate,owner,FFD,FRDownloader,RNKKT,KKTRegDate,FNExpireDate,LegalName,FRSerialNumber,FNNumber,FRFirmware\",\n\t\"agreement$agreement\":    \"state,stateStartTime,services,recipientsOU,lastModifiedDate\", // Добавлено для контрактов\n}\n\n// карты минимальных атрибутов, специфичные для Naumen ServiceDesk.\nvar minimalAttrsMap = map[string]string{\n\t\"ou$company\":             \"UUID,lastModifiedDate,parent\",\n\t\"objectBase$Server\":      \"UUID,lastModifiedDate,owner\",\n\t\"objectBase$Workstation\": \"UUID,lastModifiedDate,owner\",\n\t\"objectBase$FR\":          \"UUID,lastModifiedDate,owner\",\n}\n\ntype naumenClientImpl struct {\n\tclient         *http.Client\n\tbaseURL        string\n\tapiKey         string\n\tlimiter        *rate.Limiter\n\tlogger         *zap.Logger\n\tmaxRetries     int\n\tdryRun         bool\n\treferenceCache map[string]string\n\tcacheMutex     sync.RWMutex\n\tmapper         external.Mapper\n}\n\n// NewNaumenClient создает новый клиент для Naumen ServiceDesk.\n// Возвращает тип интерфейса external.ExternalSystemClient.\nfunc NewNaumenClient(cfg *config.Config, logger *zap.Logger, db *gorm.DB, linkRepo repositories.LinkRepo) external.ExternalSystemClient {\n\ttransport := &http.Transport{\n\t\tDialContext:           (&net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}).DialContext,\n\t\tMaxIdleConns:          100,\n\t\tIdleConnTimeout:       90 * time.Second,\n\t\tTLSHandshakeTimeout:   10 * time.Second,\n\t\tExpectContinueTimeout: 1 * time.Second,\n\t}\n\tclient := &naumenClientImpl{\n\t\tclient:         &http.Client{Transport: transport, Timeout: cfg.RequestTimeout},\n\t\tbaseURL:        strings.TrimRight(cfg.ServiceDeskBaseURL, \"/\"),\n\t\tapiKey:         cfg.ServiceDeskKey,\n\t\tlimiter:        rate.NewLimiter(rate.Limit(cfg.RateLimit), 1),\n\t\tlogger:         logger,\n\t\tmaxRetries:     cfg.MaxRetries,\n\t\tdryRun:         cfg.ServiceDeskDryRun,\n\t\treferenceCache: make(map[string]string),\n\t}\n\tclient.mapper = newNaumenMapper(db, linkRepo, logger)\n\treturn client\n}\n\n// Mapper возвращает реализацию маппера, специфичную для Naumen.\nfunc (s *naumenClientImpl) Mapper() external.Mapper {\n\treturn s.mapper\n}\n\n// FetchCompanyContractStates реализует метод интерфейса, инкапсулируя логику Naumen.\nfunc (s *naumenClientImpl) FetchCompanyContractStates(ctx context.Context) (map[string]external.ContractState, error) {\n\tremoteContracts, err := s.FetchEntityList(ctx, \"Contract\") // Используем наш внутренний тип \"Contract\"\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось получить список контрактов для определения статусов: %w\", err)\n\t}\n\n\tcompanyStates := make(map[string]external.ContractState)\n\tfor _, contractData := range remoteContracts {\n\t\tstate, _ := contractData[\"state\"].(string)\n\t\tisActive := state == \"active\"\n\n\t\tif recipients, ok := contractData[\"recipientsOU\"].([]interface{}); ok {\n\t\t\tfor _, r := range recipients {\n\t\t\t\tif rMap, rOk := r.(map[string]interface{}); rOk {\n\t\t\t\t\tif uuid, uuidOk := rMap[\"UUID\"].(string); uuidOk {\n\t\t\t\t\t\tif existing, exists := companyStates[uuid]; !exists || !existing.IsActive {\n\t\t\t\t\t\t\tcompanyStates[uuid] = external.ContractState{IsActive: isActive}\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\n\treturn companyStates, nil\n}\n\n// FetchEntityList получает список сущностей.\nfunc (s *naumenClientImpl) FetchEntityList(ctx context.Context, entityType string) ([]map[string]interface{}, error) {\n\tmetaClass, ok := s.mapEntityTypeToMetaClass(entityType)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности для Naumen: %s\", entityType)\n\t}\n\tattrs := attrsMap[metaClass]\n\turl := fmt.Sprintf(\"%s/find/%s\", s.baseURL, metaClass)\n\tparams := map[string]string{\"attrs\": attrs}\n\tvar responseList []map[string]interface{}\n\terr := s.doWithRetry(ctx, http.MethodPost, url, nil, &responseList, params)\n\treturn responseList, err\n}\n\n// FetchEntitySummaries получает КРАТКИЙ список сущностей для быстрой сверки.\nfunc (s *naumenClientImpl) FetchEntitySummaries(ctx context.Context, entityType string) ([]map[string]interface{}, error) {\n\tmetaClass, ok := s.mapEntityTypeToMetaClass(entityType)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности для Naumen: %s\", entityType)\n\t}\n\tattrs, ok := minimalAttrsMap[metaClass]\n\tif !ok {\n\t\t// Для некоторых типов (например, Contract) может не быть минимального набора, тогда берем полный\n\t\tattrs = attrsMap[metaClass]\n\t}\n\turl := fmt.Sprintf(\"%s/find/%s\", s.baseURL, metaClass)\n\tparams := map[string]string{\"attrs\": attrs}\n\tvar responseList []map[string]interface{}\n\terr := s.doWithRetry(ctx, http.MethodPost, url, nil, &responseList, params)\n\treturn responseList, err\n}\n\n// FetchEntityDetails получает детальную информацию о сущности.\nfunc (s *naumenClientImpl) FetchEntityDetails(ctx context.Context, externalID string, entityType string) (map[string]interface{}, error) {\n\tmetaClass, ok := s.mapEntityTypeToMetaClass(entityType)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности для Naumen: %s\", entityType)\n\t}\n\tattrs := attrsMap[metaClass]\n\turl := fmt.Sprintf(\"%s/get/%s\", s.baseURL, externalID)\n\tparams := map[string]string{\"attrs\": attrs}\n\tvar response map[string]interface{}\n\terr := s.doWithRetry(ctx, http.MethodGet, url, nil, &response, params)\n\treturn response, err\n}\n\n// UpdateEntity обновляет сущность.\nfunc (s *naumenClientImpl) UpdateEntity(ctx context.Context, externalID string, entityType string, data map[string]interface{}) error {\n\tif len(data) == 0 {\n\t\treturn nil\n\t}\n\tif s.dryRun {\n\t\ts.logger.Warn(\"[DRY RUN] Отправка запроса на ОБНОВЛЕНИЕ в Naumen SD пропущена.\",\n\t\t\tzap.String(\"externalID\", externalID),\n\t\t\tzap.Any(\"params\", data),\n\t\t)\n\t\treturn nil\n\t}\n\turl := fmt.Sprintf(\"%s/edit/%s\", s.baseURL, externalID)\n\tqueryParams := make(map[string]string)\n\tfor key, value := range data {\n\t\tqueryParams[key] = fmt.Sprintf(\"%v\", value)\n\t}\n\treturn s.doWithRetry(ctx, http.MethodPost, url, nil, nil, queryParams)\n}\n\n// CreateEntity создает сущность.\nfunc (s *naumenClientImpl) CreateEntity(ctx context.Context, entityType string, data map[string]interface{}) (map[string]interface{}, error) {\n\tmetaClass, ok := s.mapEntityTypeToMetaClass(entityType)\n\tif !ok {\n\t\treturn nil, fmt.Errorf(\"неизвестный тип сущности для Naumen: %s\", entityType)\n\t}\n\tif s.dryRun {\n\t\ts.logger.Warn(\"[DRY RUN] Отправка запроса на СОЗДАНИЕ в Naumen SD пропущена.\", zap.String(\"metaClass\", metaClass))\n\t\treturn map[string]interface{}{\"UUID\": \"dry-run-fake-uuid\"}, nil\n\t}\n\turl := fmt.Sprintf(\"%s/create-m2m/%s\", s.baseURL, metaClass)\n\tbodyBytes, err := json.Marshal(data)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"ошибка сериализации данных: %w\", err)\n\t}\n\tvar response map[string]interface{}\n\tparams := map[string]string{\"attrs\": \"UUID\"}\n\terr = s.doWithRetry(ctx, http.MethodPost, url, bytes.NewBuffer(bodyBytes), &response, params)\n\treturn response, err\n}\n\n// FindReferenceID ищет ID в справочнике.\nfunc (s *naumenClientImpl) FindReferenceID(ctx context.Context, referenceType, title string, useSubstringSearch bool) (string, error) {\n\tmetaClass, ok := s.mapEntityTypeToMetaClass(referenceType)\n\tif !ok {\n\t\treturn \"\", fmt.Errorf(\"неизвестный тип справочника для Naumen: %s\", referenceType)\n\t}\n\tcacheKey := fmt.Sprintf(\"%s:%s\", metaClass, title)\n\ts.cacheMutex.RLock()\n\tcachedID, found := s.referenceCache[cacheKey]\n\ts.cacheMutex.RUnlock()\n\tif found {\n\t\treturn cachedID, nil\n\t}\n\turl := fmt.Sprintf(\"%s/find/%s\", s.baseURL, metaClass)\n\tparams := map[string]string{\"attrs\": \"UUID,title\"}\n\tvar response []map[string]interface{}\n\terr := s.doWithRetry(ctx, http.MethodPost, url, nil, &response, params)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"ошибка получения справочника %s: %w\", metaClass, err)\n\t}\n\tvar foundUUID, foundTitle string\n\tfor _, item := range response {\n\t\titemTitle, okT := item[\"title\"].(string)\n\t\titemUUID, okU := item[\"UUID\"].(string)\n\t\tif !okT || !okU {\n\t\t\tcontinue\n\t\t}\n\t\tmatch := false\n\t\tif useSubstringSearch {\n\t\t\tif strings.Contains(itemTitle, title) {\n\t\t\t\tmatch = true\n\t\t\t}\n\t\t} else {\n\t\t\tif itemTitle == title {\n\t\t\t\tmatch = true\n\t\t\t}\n\t\t}\n\t\tif match {\n\t\t\tif foundUUID != \"\" {\n\t\t\t\ts.logger.Warn(\"Найдено несколько значений в справочнике, будет использовано первое\",\n\t\t\t\t\tzap.String(\"metaClass\", metaClass), zap.String(\"title\", title),\n\t\t\t\t\tzap.String(\"found1\", foundTitle), zap.String(\"found2\", itemTitle))\n\t\t\t\tbreak\n\t\t\t}\n\t\t\tfoundUUID = itemUUID\n\t\t\tfoundTitle = itemTitle\n\t\t}\n\t}\n\tif foundUUID == \"\" {\n\t\treturn \"\", fmt.Errorf(\"не найдено значение '%s' в справочнике %s\", title, metaClass)\n\t}\n\ts.cacheMutex.Lock()\n\ts.referenceCache[cacheKey] = foundUUID\n\ts.cacheMutex.Unlock()\n\treturn foundUUID, nil\n}\n\n// doWithRetry выполняет HTTP-запрос с политикой повторов и улучшенным логированием.\nfunc (s *naumenClientImpl) doWithRetry(ctx context.Context, method, url string, body io.Reader, target interface{}, queryParams ...map[string]string) error {\n\tvar bodyBytes []byte\n\tvar err error\n\tif body != nil {\n\t\tbodyBytes, err = io.ReadAll(body)\n\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"не удалось прочитать тело запроса для логирования: %w\", err)\n\t\t}\n\t}\n\tfor i := 0; i < s.maxRetries; i++ {\n\t\tif err = s.limiter.Wait(ctx); err != nil {\n\t\t\treturn err\n\t\t}\n\t\tvar requestBody io.Reader\n\t\tif bodyBytes != nil {\n\t\t\trequestBody = bytes.NewBuffer(bodyBytes)\n\t\t}\n\t\treq, reqErr := http.NewRequestWithContext(ctx, method, url, requestBody)\n\t\tif reqErr != nil {\n\t\t\treturn fmt.Errorf(\"не удалось создать запрос: %w\", reqErr)\n\t\t}\n\t\tq := req.URL.Query()\n\t\tq.Add(\"accessKey\", s.apiKey)\n\t\tif len(queryParams) > 0 {\n\t\t\tfor k, v := range queryParams[0] {\n\t\t\t\tq.Add(k, v)\n\t\t\t}\n\t\t}\n\t\treq.URL.RawQuery = q.Encode()\n\t\tif body != nil {\n\t\t\treq.Header.Set(\"Content-Type\", \"application/json\")\n\t\t}\n\n\t\t// ИЗМЕНЕНИЕ 2.0: Маскирование ключа в логах\n\t\turlToLog := *req.URL\n\t\tqLog := urlToLog.Query()\n\t\tif qLog.Has(\"accessKey\") {\n\t\t\tqLog.Set(\"accessKey\", \"[REDACTED]\")\n\t\t}\n\t\turlToLog.RawQuery = qLog.Encode()\n\n\t\ts.logger.Info(\"Отправка запроса в Naumen ServiceDesk\",\n\t\t\tzap.String(\"метод\", method),\n\t\t\tzap.String(\"url\", urlToLog.String()),\n\t\t\tzap.String(\"тело\", string(bodyBytes)),\n\t\t)\n\n\t\tresp, doErr := s.client.Do(req)\n\t\tif doErr != nil {\n\t\t\terr = fmt.Errorf(\"ошибка выполнения запроса: %w\", doErr)\n\t\t\ts.logger.Warn(\"Запрос не удался, повторная попытка...\", zap.Error(err), zap.Int(\"попытка\", i+1))\n\t\t\ttime.Sleep(time.Duration(i+1) * 500 * time.Millisecond)\n\t\t\tcontinue\n\t\t}\n\t\tdefer resp.Body.Close()\n\n\t\tif resp.StatusCode >= 400 {\n\t\t\trespBodyBytes, _ := io.ReadAll(resp.Body)\n\t\t\tbodyString := string(respBodyBytes)\n\t\t\terr = fmt.Errorf(\"API Naumen SD вернуло ошибку: статус %d, тело: %s\", resp.StatusCode, bodyString)\n\t\t\ts.logger.Error(\"Получена ошибка от Naumen ServiceDesk\",\n\t\t\t\tzap.Int(\"статус\", resp.StatusCode),\n\t\t\t\tzap.String(\"ответ\", bodyString),\n\t\t\t\tzap.String(\"url_запроса\", urlToLog.String()),\n\t\t\t)\n\t\t\tif resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {\n\t\t\t\t// Ошибка авторизации, нет смысла повторять\n\t\t\t\treturn err\n\t\t\t}\n\t\t\tif resp.StatusCode == 500 && strings.Contains(bodyString, \"ключ авторизации\") && strings.Contains(bodyString, \"не найден\") {\n\t\t\t\ts.logger.Fatal(\"Критическая ошибка: ключ доступа ServiceDesk (accessKey) невалиден. Проверьте конфигурацию.\",\n\t\t\t\t\tzap.String(\"sd_ответ\", bodyString),\n\t\t\t\t)\n\t\t\t}\n\t\t\ts.logger.Warn(\"Ошибка сервера Naumen ServiceDesk, повторная попытка...\", zap.Error(err), zap.Int(\"попытка\", i+1))\n\t\t\ttime.Sleep(time.Duration(i+1) * 500 * time.Millisecond)\n\t\t\tcontinue\n\t\t}\n\t\tif target != nil {\n\t\t\tif resp.StatusCode != http.StatusNoContent && resp.ContentLength != 0 {\n\t\t\t\tif decodeErr := json.NewDecoder(resp.Body).Decode(target); decodeErr != nil {\n\t\t\t\t\treturn fmt.Errorf(\"не удалось декодировать ответ: %w\", decodeErr)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn nil\n\t}\n\treturn fmt.Errorf(\"запрос не удался после %d попыток: %w\", s.maxRetries, err)\n}\n\n// naumenMapper реализует интерфейс external.Mapper.\ntype naumenMapper struct {\n\tdb       *gorm.DB\n\tlinkRepo repositories.LinkRepo\n\tlogger   *zap.Logger\n}\n\n// newNaumenMapper создает новый экземпляр маппера для Naumen.\nfunc newNaumenMapper(db *gorm.DB, linkRepo repositories.LinkRepo, logger *zap.Logger) external.Mapper {\n\treturn &naumenMapper{\n\t\tdb:       db,\n\t\tlinkRepo: linkRepo,\n\t\tlogger:   logger,\n\t}\n}\n\n// --- СПЕЦИФИЧНЫЕ ДЛЯ NAUMEN КОНСТАНТЫ ---\nconst (\n\tmetaClassCompany     = \"ou$company\"\n\tmetaClassServer      = \"objectBase$Server\"\n\tmetaClassWorkstation = \"objectBase$Workstation\"\n\tmetaClassFR          = \"objectBase$FR\"\n\tmetaClassAgreement   = \"agreement$agreement\"\n)\n\n// DataToCompany преобразует мапу от Naumen в модель Company.\nfunc (m *naumenMapper) DataToCompany(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Company, error) {\n\tcompany := &models.Company{}\n\tcompany.MetaClass = metaClassCompany\n\n\tif title, ok := data[\"title\"].(string); ok {\n\t\tcompany.Title = &title\n\t}\n\tif address, ok := data[\"adress\"].(string); ok {\n\t\tcompany.Address = &address\n\t}\n\tif addName, ok := data[\"additionalName\"].(string); ok {\n\t\tcompany.AdditionalName = &addName\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tcompany.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\n\tif parent, ok := data[\"parent\"].(map[string]interface{}); ok {\n\t\tif parentUUID, p_ok := parent[\"UUID\"].(string); p_ok {\n\t\t\tparentInternalID, err := m.linkRepo.FindInternalIDByExternalID(ctx, m.db, \"naumen\", parentUUID)\n\t\t\tif err != nil {\n\t\t\t\treturn nil, fmt.Errorf(\"ошибка поиска внутреннего ID родителя %s: %w\", parentUUID, err)\n\t\t\t}\n\t\t\tif parentInternalID != \"\" {\n\t\t\t\tcompany.ParentID = &parentInternalID\n\t\t\t} else {\n\t\t\t\tm.logger.Warn(\"Родительская компания не найдена в локальной БД, связь не будет установлена\", zap.String(\"parent_external_uuid\", parentUUID))\n\t\t\t}\n\t\t}\n\t}\n\n\tinitialActiveState := false\n\tcompany.ActiveContract = &initialActiveState\n\treturn company, nil\n}\n\n// getOwnerInternalID - хелпер для получения внутреннего ID владельца.\nfunc (m *naumenMapper) getOwnerInternalID(ctx context.Context, data map[string]interface{}) (string, error) {\n\tif owner, ok := data[\"owner\"].(map[string]interface{}); ok {\n\t\tif ownerUUID, oOk := owner[\"UUID\"].(string); oOk {\n\t\t\tinternalID, err := m.linkRepo.FindInternalIDByExternalID(ctx, m.db, \"naumen\", ownerUUID)\n\t\t\tif err != nil {\n\t\t\t\treturn \"\", fmt.Errorf(\"ошибка поиска внутреннего ID владельца %s: %w\", ownerUUID, err)\n\t\t\t}\n\t\t\tif internalID == \"\" {\n\t\t\t\treturn \"\", fmt.Errorf(\"владелец с внешним ID %s не найден в локальной БД\", ownerUUID)\n\t\t\t}\n\t\t\treturn internalID, nil\n\t\t}\n\t}\n\treturn \"\", fmt.Errorf(\"данные о владельце отсутствуют или некорректны\")\n}\n\n// DataToServer преобразует мапу от Naumen в модель Server.\nfunc (m *naumenMapper) DataToServer(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Server, error) {\n\townerInternalID, err := m.getOwnerInternalID(ctx, data)\n\tif err != nil {\n\t\texternalUUID, _ := data[\"UUID\"].(string)\n\t\treturn nil, fmt.Errorf(\"сервер (ext: %s): %w\", externalUUID, err)\n\t}\n\tserver := &models.Server{OwnerID: &ownerInternalID}\n\tserver.MetaClass = metaClassServer\n\n\trawUniqueID, _ := data[\"UniqueID\"].(string)\n\trawTeamviewer, _ := data[\"Teamviewer\"].(string)\n\trawRDP, _ := data[\"RDP\"].(string)\n\trawAnydesk, _ := data[\"AnyDesk\"].(string)\n\trawIP, _ := data[\"IP\"].(string)\n\trawDeviceName, _ := data[\"DeviceName\"].(string)\n\trawIikoVersion, _ := data[\"iikoVersion\"].(string)\n\trawDescription, _ := data[\"description\"].(string)\n\trawNameForClient, _ := data[\"nameforclient\"].(string)\n\trawLitemanager, _ := data[\"litemanagerID\"].(string)\n\n\tserver.UniqueID = validators.ValidateUniqueID(rawUniqueID)\n\tserver.Teamviewer = validators.ValidateRemoteAccessID(rawTeamviewer)\n\tserver.Anydesk = validators.ValidateRemoteAccessID(rawAnydesk)\n\tserver.IP = validators.ValidateIPAddress(rawIP)\n\n\tif rawRDP != \"\" {\n\t\tserver.RDP = &rawRDP\n\t}\n\tif rawDeviceName != \"\" {\n\t\tserver.DeviceName = &rawDeviceName\n\t}\n\tif rawIikoVersion != \"\" {\n\t\tserver.ServerVersion = &rawIikoVersion\n\t}\n\n\tvar descriptionParts []string\n\tif rawNameForClient != \"\" {\n\t\tdescriptionParts = append(descriptionParts, \"Имя для клиента: \"+rawNameForClient)\n\t}\n\tif rawDescription != \"\" {\n\t\tdescriptionParts = append(descriptionParts, \"Описание: \"+rawDescription)\n\t}\n\t// добавление остальных полей в description\n\tfullDescription := strings.Join(descriptionParts, \" | \")\n\tif fullDescription != \"\" {\n\t\tserver.Description = &fullDescription\n\t}\n\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tserver.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\n\tif rawLitemanager != \"\" && validators.LiteManagerIDRegex.MatchString(rawLitemanager) {\n\t\tserver.Litemanager = &rawLitemanager\n\t} else {\n\t\tserver.Litemanager = validators.ExtractLiteManagerID(data, fullDescription)\n\t}\n\n\tif cl, ok := data[\"CabinetLink\"].(string); ok && server.IP != nil {\n\t\tcompanyType := validators.DetermineCompanyTypeFromIP(*server.IP)\n\t\tlink := validators.ValidateCabinetLink(cl, companyType)\n\t\tserver.CabinetLink = &link\n\t}\n\treturn server, nil\n}\n\n// DataToWorkstation преобразует мапу от Naumen в модель Workstation.\nfunc (m *naumenMapper) DataToWorkstation(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Workstation, error) {\n\townerInternalID, err := m.getOwnerInternalID(ctx, data)\n\tif err != nil {\n\t\texternalUUID, _ := data[\"UUID\"].(string)\n\t\treturn nil, fmt.Errorf(\"рабочая станция (ext: %s): %w\", externalUUID, err)\n\t}\n\tws := &models.Workstation{OwnerID: &ownerInternalID}\n\tws.MetaClass = metaClassWorkstation\n\tif tv, ok := data[\"Teamviewer\"].(string); ok {\n\t\tws.Teamviewer = validators.ValidateRemoteAccessID(tv)\n\t}\n\tif ad, ok := data[\"AnyDesk\"].(string); ok {\n\t\tws.Anydesk = validators.ValidateRemoteAccessID(ad)\n\t}\n\tif dn, ok := data[\"DeviceName\"].(string); ok {\n\t\tws.DeviceName = &dn\n\t}\n\tif desc, ok := data[\"Commentariy\"].(string); ok {\n\t\tws.Description = &desc\n\t\tws.Litemanager = validators.ExtractLiteManagerID(data, desc)\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tws.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\treturn ws, nil\n}\n\n// DataToFiscalRegister преобразует мапу от Naumen в модель FiscalRegister.\nfunc (m *naumenMapper) DataToFiscalRegister(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.FiscalRegister, error) {\n\townerInternalID, err := m.getOwnerInternalID(ctx, data)\n\tif err != nil {\n\t\texternalUUID, _ := data[\"UUID\"].(string)\n\t\treturn nil, fmt.Errorf(\"фискальный регистратор (ext: %s): %w\", externalUUID, err)\n\t}\n\tfr := &models.FiscalRegister{OwnerID: &ownerInternalID}\n\tfr.MetaClass = metaClassFR\n\n\tif val, ok := data[\"ModelKKT\"].(map[string]interface{}); ok {\n\t\tif title, ok2 := val[\"title\"].(string); ok2 {\n\t\t\tfr.ModelKKT = &title\n\t\t}\n\t} else if val, ok := data[\"ModelKKT\"].(string); ok {\n\t\tfr.ModelKKT = &val\n\t}\n\tif val, ok := data[\"FFD\"].(map[string]interface{}); ok {\n\t\tif title, ok2 := val[\"title\"].(string); ok2 {\n\t\t\tfr.FFD = &title\n\t\t}\n\t} else if val, ok := data[\"FFD\"].(string); ok {\n\t\tfr.FFD = &val\n\t}\n\tif val, ok := data[\"FRDownloader\"].(string); ok {\n\t\tfr.FRDownloader = &val\n\t}\n\tif val, ok := data[\"FRFirmware\"].(string); ok {\n\t\tfr.FRFirmware = &val\n\t}\n\tif val, ok := data[\"RNKKT\"].(string); ok {\n\t\tnormalizedRNKKT := utils.NormalizeRNKKT(val)\n\t\tfr.RNKKT = &normalizedRNKKT\n\t}\n\tif val, ok := data[\"LegalName\"].(string); ok {\n\t\tmatches := innRegex.FindStringSubmatch(val)\n\t\tif len(matches) > 1 {\n\t\t\tinn := matches[1]\n\t\t\tfr.INN = &inn\n\t\t\tcleanName := strings.TrimSpace(innRegex.ReplaceAllString(val, \"\"))\n\t\t\tfr.LegalName = &cleanName\n\t\t} else {\n\t\t\tfr.LegalName = &val\n\t\t}\n\t}\n\tif val, ok := data[\"FRSerialNumber\"].(string); ok {\n\t\tfr.FRSerialNumber = &val\n\t}\n\tif val, ok := data[\"FNNumber\"].(string); ok {\n\t\tfr.FNNumber = &val\n\t}\n\tif val, ok := data[\"KKTRegDate\"].(string); ok {\n\t\tfr.KKTRegDate = utils.ParseServiceDeskTime(val)\n\t}\n\tif val, ok := data[\"FNExpireDate\"].(string); ok {\n\t\tfr.FNExpireDate = utils.ParseServiceDeskTime(val)\n\t}\n\tif val, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tfr.LastModifiedDate = utils.ParseServiceDeskTime(val)\n\t}\n\treturn fr, nil\n}\n\nvar innRegex = regexp.MustCompile(`ИНН:\\s*(\\d{10,12})`)\n\n// DataToContract преобразует мапу от Naumen в модель Contract.\nfunc (m *naumenMapper) DataToContract(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Contract, error) {\n\tcontract := &models.Contract{}\n\tcontract.MetaClass = metaClassAgreement\n\n\tif state, ok := data[\"state\"].(string); ok {\n\t\tcontract.State = &state\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tcontract.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\tif sst, ok := data[\"stateStartTime\"].(string); ok {\n\t\tcontract.StateStartTime = utils.ParseServiceDeskTime(sst)\n\t}\n\n\tvar serviceTitles []string\n\tif services, ok := data[\"services\"].([]interface{}); ok {\n\t\tfor _, serviceItem := range services {\n\t\t\tif serviceMap, smOk := serviceItem.(map[string]interface{}); smOk {\n\t\t\t\tif title, tOk := serviceMap[\"title\"].(string); tOk {\n\t\t\t\t\tserviceTitles = append(serviceTitles, title)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif servicesJSON, err := json.Marshal(serviceTitles); err == nil {\n\t\t\tcontract.Services = datatypes.JSON(servicesJSON)\n\t\t}\n\t}\n\n\tcontract.ServiceLevel = m.determineServiceLevel(serviceTitles)\n\n\tif recipients, ok := data[\"recipientsOU\"].([]interface{}); ok {\n\t\tvar recipientUUIDs []string\n\t\tfor _, recipientItem := range recipients {\n\t\t\tif recipientMap, rmOk := recipientItem.(map[string]interface{}); rmOk {\n\t\t\t\tif recipientUUID, uOk := recipientMap[\"UUID\"].(string); uOk {\n\t\t\t\t\trecipientUUIDs = append(recipientUUIDs, recipientUUID)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif recipientsJSON, err := json.Marshal(recipientUUIDs); err == nil {\n\t\t\tcontract.Recipients = datatypes.JSON(recipientsJSON)\n\t\t}\n\t}\n\n\treturn contract, nil\n}\n\n// determineServiceLevel - специфичная для Naumen логика определения уровня сервиса.\nfunc (m *naumenMapper) determineServiceLevel(serviceTitles []string) int {\n\tserviceSet := make(map[string]struct{})\n\tfor _, title := range serviceTitles {\n\t\tserviceSet[title] = struct{}{}\n\t}\n\t// Специфичные для Naumen названия услуг\n\tif _, ok := serviceSet[\"TS Standard (без выездов)\"]; ok {\n\t\treturn 3\n\t}\n\tif _, ok := serviceSet[\"TS Standard\"]; ok {\n\t\treturn 2\n\t}\n\tif _, ok := serviceSet[\"TS Cloud\"]; ok {\n\t\treturn 1\n\t}\n\tif _, ok := serviceSet[\"Прием на АО\"]; ok {\n\t\treturn 0\n\t}\n\tif _, ok := serviceSet[\"Разовое обращение\"]; ok {\n\t\treturn 5\n\t}\n\tif _, ok := serviceSet[\"Базовая услуга\"]; ok {\n\t\treturn 5\n\t}\n\treturn -1\n}\n\n// GetCompanyUUIDsFromContract - специфичная для Naumen логика извлечения UUID.\nfunc (m *naumenMapper) GetCompanyUUIDsFromContract(data map[string]interface{}) []string {\n\tvar uuids []string\n\tif recipients, ok := data[\"recipientsOU\"].([]interface{}); ok {\n\t\tfor _, r := range recipients {\n\t\t\tif rMap, rOk := r.(map[string]interface{}); rOk {\n\t\t\t\tif uuid, uuidOk := rMap[\"UUID\"].(string); uuidOk {\n\t\t\t\t\tuuids = append(uuids, uuid)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\treturn uuids\n}\n\n// Вспомогательная функция для маппинга.\nfunc (s *naumenClientImpl) mapEntityTypeToMetaClass(entityType string) (string, bool) {\n\tswitch entityType {\n\tcase \"Company\":\n\t\treturn \"ou$company\", true\n\tcase \"Server\":\n\t\treturn \"objectBase$Server\", true\n\tcase \"Workstation\":\n\t\treturn \"objectBase$Workstation\", true\n\tcase \"FiscalRegister\":\n\t\treturn \"objectBase$FR\", true\n\tcase \"Contract\":\n\t\treturn \"agreement$agreement\", true\n\tcase \"ModeliFR\":\n\t\treturn \"ModeliFR\", true\n\tcase \"FFD\":\n\t\treturn \"FFD\", true\n\tcase \"SrokiFN\":\n\t\treturn \"SrokiFN\", true\n\tdefault:\n\t\treturn \"\", false\n\t}\n}\n\ntype HttpError struct {\n\tStatusCode int\n\tMessage    string\n}\n\nfunc (e *HttpError) Error() string { return fmt.Sprintf(\"HTTP %d: %s\", e.StatusCode, e.Message) }\nfunc NewHttpError(code int, message string) *HttpError {\n\treturn &HttpError{StatusCode: code, Message: message}\n}\n",
    "internal/processing/engine.go": "// internal/processing/engine.go\npackage processing\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/services\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/internal/validators\"\n\t\"fmt\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/datatypes\"\n)\n\n// ActionType определяет тип действия, которое должен выполнить Оркестратор.\ntype ActionType string\n\nconst (\n\tActionCreateTask         ActionType = \"create_task\"\n\tActionUpdate             ActionType = \"update\"\n\tActionAddAdditionalOwner ActionType = \"add_additional_owner\"\n)\n\n// Action представляет одно действие в плане.\ntype Action struct {\n\tType                ActionType\n\tEntityType          string\n\tEntityUUID          string // Внутренний ID сущности\n\tUpdates             map[string]interface{}\n\tTask                *models.ReconciliationTask\n\tAdditionalOwnerUUID string // Внутренний ID доп. владельца\n}\n\n// ProcessingResult - это \"план действий\", который Процессор возвращает Оркестратору.\ntype ProcessingResult struct {\n\tActions []Action\n}\n\n// ProcessingEngine содержит всю сложную бизнес-логику сверки.\ntype ProcessingEngine interface {\n\tProcessAgentData(ctx context.Context, source string, data *api.AgentDataDTO) *ProcessingResult\n}\n\ntype processingEngineImpl struct {\n\tlogger          *zap.Logger\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\tcompanyRepo     repositories.CompanyRepo\n\ttaskRepo        repositories.TaskRepo\n\tmatcherSvc      services.EntityMatcherService\n}\n\n// NewProcessingEngine создает новый экземпляр движка.\nfunc NewProcessingEngine(\n\tlogger *zap.Logger,\n\tserverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo,\n\tcompanyRepo repositories.CompanyRepo,\n\ttaskRepo repositories.TaskRepo,\n\tmatcherSvc services.EntityMatcherService,\n) ProcessingEngine {\n\treturn &processingEngineImpl{\n\t\tlogger, serverRepo, workstationRepo, frRepo, companyRepo, taskRepo, matcherSvc,\n\t}\n}\n\n// ProcessAgentData - главный метод, реализующий согласованную логику.\nfunc (p *processingEngineImpl) ProcessAgentData(ctx context.Context, source string, data *api.AgentDataDTO) *ProcessingResult {\n\tresult := &ProcessingResult{Actions: []Action{}}\n\tlog := p.logger.With(zap.String(\"source\", source))\n\n\tcurrentTime := utils.ParseAgentTime(data.CurrentTime)\n\tif currentTime == nil {\n\t\tlog.Warn(\"Не удалось распознать 'current_time' из данных агента. Обработка прервана.\")\n\t\treturn result\n\t}\n\tif currentTime.Before(time.Now().AddDate(0, 0, -60)) {\n\t\tlog.Info(\"Данные от агента пропущены, так как они старше 60 дней.\", zap.Time(\"current_time\", *currentTime))\n\t\treturn result\n\t}\n\n\tunidentifiedTaskUUID := fmt.Sprintf(\"%s@%s\", data.Hostname, data.URLRms)\n\n\tmainMatch := p.matcherSvc.FindEntityByAgentData(ctx, data)\n\tif mainMatch == nil {\n\t\tp.createTaskIfNotExists(ctx, result, \"new_client\", \"\", unidentifiedTaskUUID, \"\", data, \"Не удалось идентифицировать оборудование. Требуется создать нового клиента и привязать оборудование.\")\n\t\treturn result\n\t}\n\n\tfoundServer, _ := p.serverRepo.FindByCRMidOrIP(ctx, data.CRMID, utils.SafeStringDereference(validators.ValidateIPAddress(data.URLRms)))\n\tfoundWS, _ := p.workstationRepo.FindByRemoteIDs(ctx, data.TeamviewerID, \"\", data.LitemanagerID)\n\tfoundFR, _ := p.frRepo.FindBySerialNumber(ctx, data.SerialNumber)\n\n\tetalonOwnerID, err := p.getEquipmentOwnerID(foundWS, foundFR)\n\tif err != nil {\n\t\tif foundServer != nil && foundServer.OwnerID != nil {\n\t\t\tetalonOwnerID = *foundServer.OwnerID\n\t\t} else {\n\t\t\tp.createTaskIfNotExists(ctx, result, \"data_conflict\", \"\", unidentifiedTaskUUID, \"\", data, err.Error())\n\t\t\treturn result\n\t\t}\n\t}\n\n\tlog.Info(\"Эталонный владелец оборудования определен\", zap.String(\"ownerID\", etalonOwnerID))\n\n\townerCompany, err := p.companyRepo.GetByID(ctx, etalonOwnerID)\n\tif err != nil || ownerCompany == nil {\n\t\tlog.Error(\"Не удалось получить данные о компании-владельце, обработка прервана\", zap.String(\"ownerID\", etalonOwnerID), zap.Error(err))\n\t\treturn result\n\t}\n\n\tif ownerCompany.ActiveContract == nil || !*ownerCompany.ActiveContract {\n\t\tlog.Debug(\"Обработка данных от агента пропущена: неактивный контракт у владельца\", zap.String(\"ownerID\", etalonOwnerID))\n\t\treturn result\n\t}\n\n\tp.processServerActions(ctx, result, etalonOwnerID, foundServer, data)\n\tp.processWorkstationActions(ctx, result, etalonOwnerID, foundWS, data)\n\tp.processFiscalRegisterActions(ctx, result, etalonOwnerID, foundFR, data)\n\n\treturn result\n}\n\n// getEquipmentOwnerID определяет владельца по оборудованию (РС или ФР).\nfunc (p *processingEngineImpl) getEquipmentOwnerID(ws *models.Workstation, fr *models.FiscalRegister) (string, error) {\n\twsOwner := \"\"\n\tif ws != nil && ws.OwnerID != nil {\n\t\twsOwner = *ws.OwnerID\n\t}\n\tfrOwner := \"\"\n\tif fr != nil && fr.OwnerID != nil {\n\t\tfrOwner = *fr.OwnerID\n\t}\n\n\tif wsOwner != \"\" && frOwner != \"\" && wsOwner != frOwner {\n\t\treturn \"\", fmt.Errorf(\"конфликт владельцев: РС принадлежит '%s', а ФР - '%s'\", wsOwner, frOwner)\n\t}\n\tif wsOwner != \"\" {\n\t\treturn wsOwner, nil\n\t}\n\tif frOwner != \"\" {\n\t\treturn frOwner, nil\n\t}\n\treturn \"\", fmt.Errorf(\"не удалось определить владельца оборудования: не найдено ни РС, ни ФР с владельцем\")\n}\n\n// processServerActions формирует план действий для Сервера.\nfunc (p *processingEngineImpl) processServerActions(ctx context.Context, res *ProcessingResult, equipmentOwnerID string, server *models.Server, data *api.AgentDataDTO) {\n\tif server == nil {\n\t\treturn\n\t}\n\tcurrentTime := utils.ParseAgentTime(data.CurrentTime)\n\tif currentTime != nil && server.LastModifiedDate != nil && currentTime.Before(*server.LastModifiedDate) {\n\t\tp.logger.Info(\"Обновление сервера пропущено: данные от агента старше, чем запись в БД\", zap.String(\"server_id\", server.ID), zap.Time(\"agent_time\", *currentTime), zap.Time(\"db_time\", *server.LastModifiedDate))\n\t\treturn\n\t}\n\tif server.Status == \"locked\" {\n\t\tp.logger.Debug(\"Обработка сервера пропущена: статус 'locked'\", zap.String(\"id\", server.ID))\n\t\treturn\n\t}\n\n\tserverPrimaryOwnerID := *server.OwnerID\n\tequipmentOwnerParents, _ := p.companyRepo.GetAllParentIDs(ctx, equipmentOwnerID)\n\tserverOwnerParents, _ := p.companyRepo.GetAllParentIDs(ctx, serverPrimaryOwnerID)\n\tareRelated := p.areCompaniesRelated(equipmentOwnerID, serverPrimaryOwnerID, equipmentOwnerParents, serverOwnerParents)\n\n\tif areRelated {\n\t\t// Логика добавления доп. владельца (уже работает с внутренними ID, но нужно проверить)\n\t} else {\n\t\tcomment := fmt.Sprintf(\"Конфликт владения сервером! Оборудование принадлежит '%s', но оно подключено к серверу '%s', который принадлежит '%s'.\", equipmentOwnerID, server.ID, serverPrimaryOwnerID)\n\t\tp.createTaskIfNotExists(ctx, res, \"data_conflict\", \"Server\", server.ID, equipmentOwnerID, data, comment)\n\t}\n\n\tupdates := make(map[string]interface{})\n\tif (server.CRMid == nil || *server.CRMid == \"\") && data.CRMID != \"\" {\n\t\tupdates[\"crm_id\"] = data.CRMID\n\t}\n\tif len(updates) > 0 {\n\t\tres.Actions = append(res.Actions, Action{Type: ActionUpdate, EntityType: \"Server\", EntityUUID: server.ID, Updates: updates})\n\t}\n}\n\n// areCompaniesRelated проверяет, связаны ли две компании.\nfunc (p *processingEngineImpl) areCompaniesRelated(owner1, owner2 string, parents1, parents2 []string) bool {\n\tif owner1 == owner2 {\n\t\treturn true\n\t}\n\tfor _, p1 := range parents1 {\n\t\tif p1 == owner2 {\n\t\t\treturn true\n\t\t}\n\t}\n\tfor _, p2 := range parents2 {\n\t\tif p2 == owner1 {\n\t\t\treturn true\n\t\t}\n\t}\n\tparents1Set := make(map[string]struct{})\n\tfor _, p1 := range parents1 {\n\t\tparents1Set[p1] = struct{}{}\n\t}\n\tfor _, p2 := range parents2 {\n\t\tif _, ok := parents1Set[p2]; ok {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// processWorkstationActions формирует план действий для Рабочей станции.\nfunc (p *processingEngineImpl) processWorkstationActions(ctx context.Context, res *ProcessingResult, ownerID string, ws *models.Workstation, data *api.AgentDataDTO) {\n\tagentTV := utils.SafeStringDereference(validators.ValidateRemoteAccessID(data.TeamviewerID))\n\tagentLM := utils.SafeStringDereference(validators.ValidateRemoteAccessID(data.LitemanagerID))\n\n\tif ws != nil {\n\t\tif ws.Status != nil && *ws.Status == \"locked\" {\n\t\t\treturn\n\t\t}\n\t\tupdates := make(map[string]interface{})\n\t\tif (ws.Teamviewer == nil || *ws.Teamviewer == \"\") && agentTV != \"\" {\n\t\t\tupdates[\"teamviewer\"] = agentTV\n\t\t}\n\t\tif (ws.Litemanager == nil || *ws.Litemanager == \"\") && agentLM != \"\" {\n\t\t\tupdates[\"litemanager\"] = agentLM\n\t\t}\n\t\tif len(updates) > 0 {\n\t\t\tres.Actions = append(res.Actions, Action{Type: ActionUpdate, EntityType: \"Workstation\", EntityUUID: ws.ID, Updates: updates})\n\t\t}\n\t} else if agentTV != \"\" || agentLM != \"\" {\n\t\tentityID := agentTV\n\t\tif entityID == \"\" {\n\t\t\tentityID = agentLM\n\t\t}\n\t\tcomment := fmt.Sprintf(\"Добавить новую рабочую станцию для владельца '%s'. TV: %s, LM: %s.\", ownerID, agentTV, agentLM)\n\t\tp.createTaskIfNotExists(ctx, res, \"add_equipment\", \"Workstation\", entityID, ownerID, data, comment)\n\t}\n}\n\n// processFiscalRegisterActions формирует план действий для ФР.\nfunc (p *processingEngineImpl) processFiscalRegisterActions(ctx context.Context, res *ProcessingResult, ownerID string, fr *models.FiscalRegister, data *api.AgentDataDTO) {\n\tif fr != nil {\n\t\tif fr.Status != nil && *fr.Status == \"locked\" {\n\t\t\treturn\n\t\t}\n\t\tupdates := make(map[string]interface{})\n\t\t// ... (логика обновления полей ФР)\n\t\tres.Actions = append(res.Actions, Action{Type: ActionUpdate, EntityType: \"FiscalRegister\", EntityUUID: fr.ID, Updates: updates})\n\t} else if data.SerialNumber != \"\" {\n\t\tcomment := fmt.Sprintf(\"Добавить новый ФР (СН: %s) для владельца '%s'.\", data.SerialNumber, ownerID)\n\t\tp.createTaskIfNotExists(ctx, res, \"add_equipment\", \"FiscalRegister\", data.SerialNumber, ownerID, data, comment)\n\t}\n}\n\n// createTaskIfNotExists создает задачу, если активной задачи такого типа еще нет.\nfunc (p *processingEngineImpl) createTaskIfNotExists(ctx context.Context, res *ProcessingResult, taskType, entityType, entityUUID, etalonOwnerID string, data *api.AgentDataDTO, comment string) {\n\texistingTask, _ := p.taskRepo.FindActiveTask(ctx, taskType, entityUUID)\n\tif existingTask != nil {\n\t\treturn\n\t}\n\tdetailsMap := make(map[string]interface{})\n\tdetailsMap[\"agent_data\"] = data\n\tif etalonOwnerID != \"\" {\n\t\tdetailsMap[\"etalon_owner_id\"] = etalonOwnerID\n\t}\n\tdetails, _ := json.Marshal(detailsMap)\n\ttask := &models.ReconciliationTask{\n\t\tTaskType: taskType, EntityType: entityType, EntityUUID: entityUUID,\n\t\tDetails: datatypes.JSON(details), Status: \"new\", Comment: comment,\n\t}\n\tres.Actions = append(res.Actions, Action{Type: ActionCreateTask, Task: task})\n}\n",
    "internal/processing/orchestrator.go": "// internal/processing/orchestrator.go\npackage processing\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"strings\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/datatypes\"\n\t\"gorm.io/gorm\"\n)\n\n// Orchestrator - центральный сервис для обработки бизнес-логики на основе событий.\ntype Orchestrator struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tbus             eventbus.EventBus\n\tsdClient        external.ExternalSystemClient\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\ttaskRepo        repositories.TaskRepo\n\tlinkRepo        repositories.LinkRepo\n\tengine          ProcessingEngine\n}\n\n// NewOrchestrator создает новый экземпляр Оркестратора.\nfunc NewOrchestrator(\n\tlogger *zap.Logger, db *gorm.DB, bus eventbus.EventBus, sdClient external.ExternalSystemClient,\n\tcompanyRepo repositories.CompanyRepo, serverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo, frRepo repositories.FiscalRegisterRepo,\n\ttaskRepo repositories.TaskRepo, linkRepo repositories.LinkRepo, engine ProcessingEngine,\n) *Orchestrator {\n\treturn &Orchestrator{\n\t\tlogger, db, bus, sdClient, companyRepo, serverRepo, workstationRepo,\n\t\tfrRepo, taskRepo, linkRepo, engine,\n\t}\n}\n\n// Start запускает Оркестратор, подписывая его на необходимые события.\nfunc (o *Orchestrator) Start(ctx context.Context) {\n\to.logger.Info(\"Оркестратор запущен и подписан на события.\")\n\to.bus.Subscribe(events.ServiceDeskEntityUpdated, o.handleServiceDeskEntityUpdate)\n\to.bus.Subscribe(events.ServiceDeskEntityDeleted, o.handleServiceDeskEntityDelete)\n\to.bus.Subscribe(events.ContractsStatusRecalculated, o.handleContractsStatusRecalculated)\n\to.bus.Subscribe(events.DuplicatesFound, o.handleDuplicatesFound)\n\to.bus.Subscribe(events.AgentDataReceived, o.handleAgentDataReceived)\n\to.bus.Subscribe(events.ServerPollingSucceeded, o.handleServerPollingSucceeded)\n\to.bus.Subscribe(events.ServerPollingFailed, o.handleServerPollingFailed)\n\to.bus.Subscribe(events.FiscalRegisterDiscrepancyFound, o.handleFiscalRegisterDiscrepancy)\n}\n\n// handleServiceDeskEntityUpdate обрабатывает обновление сущности из внешней системы.\nfunc (o *Orchestrator) handleServiceDeskEntityUpdate(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServiceDeskEntityPayload)\n\tif !ok {\n\t\to.logger.Error(\"Некорректная полезная нагрузка для события ServiceDeskEntityUpdated\")\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"entityType\", payload.EntityType), zap.String(\"externalUUID\", payload.ExternalUUID))\n\n\tvar updates map[string]interface{}\n\tvar diffLog []zap.Field\n\tvar isNewEntity bool\n\tvar internalID string\n\tvar currentEntity, newEntityModel interface{}\n\n\terr := o.db.Transaction(func(tx *gorm.DB) error {\n\t\ttxCtx := context.WithValue(ctx, \"tx\", tx)\n\t\tmapperCtx := &external.MapperContext{DB: tx, LinkRepo: o.linkRepo, Logger: log}\n\n\t\tlink, err := o.linkRepo.GetByExternalID(txCtx, tx, \"naumen\", payload.ExternalUUID)\n\t\tif err != nil {\n\t\t\treturn fmt.Errorf(\"ошибка поиска связи по внешнему ID: %w\", err)\n\t\t}\n\n\t\tisNewEntity = link == nil\n\n\t\tswitch payload.EntityType {\n\t\tcase \"Company\":\n\t\t\tnewEntityModel, err = o.sdClient.Mapper().DataToCompany(txCtx, mapperCtx, payload.Data)\n\t\t\tif err == nil && !isNewEntity {\n\t\t\t\tcurrentEntity, _ = o.companyRepo.GetByIDUnscoped(txCtx, link.InternalID)\n\t\t\t}\n\t\tcase \"Server\":\n\t\t\tnewEntityModel, err = o.sdClient.Mapper().DataToServer(txCtx, mapperCtx, payload.Data)\n\t\t\tif err == nil && !isNewEntity {\n\t\t\t\tcurrentEntity, _ = o.serverRepo.GetByIDUnscoped(txCtx, link.InternalID)\n\t\t\t}\n\t\tcase \"Workstation\":\n\t\t\tnewEntityModel, err = o.sdClient.Mapper().DataToWorkstation(txCtx, mapperCtx, payload.Data)\n\t\t\tif err == nil && !isNewEntity {\n\t\t\t\tcurrentEntity, _ = o.workstationRepo.GetByIDUnscoped(txCtx, link.InternalID)\n\t\t\t}\n\t\tcase \"FiscalRegister\":\n\t\t\tnewEntityModel, err = o.sdClient.Mapper().DataToFiscalRegister(txCtx, mapperCtx, payload.Data)\n\t\t\tif err == nil && !isNewEntity {\n\t\t\t\tcurrentEntity, _ = o.frRepo.GetByIDUnscoped(txCtx, link.InternalID)\n\t\t\t}\n\t\tdefault:\n\t\t\treturn fmt.Errorf(\"неизвестный тип сущности для обработки: %s\", payload.EntityType)\n\t\t}\n\t\tif err != nil {\n\t\t\tlog.Warn(\"Пропуск обработки сущности из-за ошибки маппинга\", zap.Error(err))\n\t\t\treturn nil\n\t\t}\n\n\t\tif isNewEntity {\n\t\t\tinternalID, err = o.createEntity(txCtx, payload.EntityType, newEntityModel)\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\n\t\t\tnewLink := &models.ExternalSystemLink{\n\t\t\t\tInternalID: internalID, SystemName: \"naumen\", ExternalID: payload.ExternalUUID,\n\t\t\t\tEntityType: payload.EntityType, LastSyncedAt: time.Now(),\n\t\t\t}\n\t\t\treturn o.linkRepo.Create(txCtx, tx, newLink)\n\t\t}\n\n\t\tinternalID = link.InternalID\n\t\tswitch payload.EntityType {\n\t\tcase \"Company\":\n\t\t\tupdates, diffLog = getCompanyDiff(currentEntity.(*models.Company), newEntityModel.(*models.Company))\n\t\tcase \"Server\":\n\t\t\tupdates, diffLog = getServerDiff(currentEntity.(*models.Server), newEntityModel.(*models.Server))\n\t\tcase \"Workstation\":\n\t\t\tupdates, diffLog = getWorkstationDiff(currentEntity.(*models.Workstation), newEntityModel.(*models.Workstation))\n\t\tcase \"FiscalRegister\":\n\t\t\tupdates, diffLog = getFiscalRegisterDiff(currentEntity.(*models.FiscalRegister), newEntityModel.(*models.FiscalRegister))\n\t\t}\n\n\t\tif newLMD := getLMDFromModel(newEntityModel); newLMD != nil {\n\t\t\tif updates == nil {\n\t\t\t\tupdates = make(map[string]interface{})\n\t\t\t}\n\t\t\tupdates[\"last_modified_date\"] = newLMD\n\t\t}\n\n\t\tif len(updates) > 0 {\n\t\t\tupdates[\"last_updated_by\"] = \"naumen_gateway\"\n\t\t\treturn o.performUpdate(txCtx, tx, payload.EntityType, internalID, updates)\n\t\t}\n\t\treturn nil\n\t})\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка в транзакции обработки обновления из SD\", zap.Error(err))\n\t\treturn\n\t}\n\n\tif !isNewEntity && len(diffLog) > 0 {\n\t\tlog.Warn(\"Обнаружено критическое расхождение данных. Создание/обновление задачи.\", diffLog...)\n\t}\n\n\tif isNewEntity {\n\t\tlog.Info(\"Новая сущность успешно создана.\", zap.String(\"internalID\", internalID))\n\t} else if len(updates) == 0 {\n\t\tlog.Debug(\"Изменений не найдено, обновление не требуется.\")\n\t} else {\n\t\tlog.Info(\"Сущность успешно обновлена.\", zap.Any(\"updates\", updates), zap.String(\"internalID\", internalID))\n\t}\n}\n\n// handleServiceDeskEntityDelete обрабатывает удаление сущности.\nfunc (o *Orchestrator) handleServiceDeskEntityDelete(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServiceDeskEntityDeletePayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"entityType\", payload.EntityType), zap.String(\"externalUUID\", payload.ExternalUUID))\n\n\terr := o.db.Transaction(func(tx *gorm.DB) error {\n\t\ttxCtx := context.WithValue(ctx, \"tx\", tx)\n\t\tlink, err := o.linkRepo.GetByExternalID(txCtx, tx, \"naumen\", payload.ExternalUUID)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif link == nil {\n\t\t\tlog.Warn(\"Связь для удаляемой сущности не найдена, возможно, она уже удалена.\")\n\t\t\treturn nil\n\t\t}\n\n\t\tif err := o.performDelete(txCtx, tx, payload.EntityType, link.InternalID); err != nil {\n\t\t\treturn err\n\t\t}\n\t\treturn tx.Delete(link).Error\n\t})\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при 'мягком удалении' сущности\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"Сущность и ее связь успешно 'мягко удалены'.\")\n\t}\n}\n\n// handleContractsStatusRecalculated обрабатывает событие о пересчете статусов контрактов.\nfunc (o *Orchestrator) handleContractsStatusRecalculated(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ContractsStatusPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"event\", event.Type))\n\tlog.Info(\"Получено событие для обновления статусов контрактов у компаний\", zap.Int(\"count\", len(payload.CompanyActiveContract)))\n\n\tactiveIDs := make([]string, 0)\n\tinactiveIDs := make([]string, 0)\n\tfor id, isActive := range payload.CompanyActiveContract {\n\t\tif isActive {\n\t\t\tactiveIDs = append(activeIDs, id)\n\t\t} else {\n\t\t\tinactiveIDs = append(inactiveIDs, id)\n\t\t}\n\t}\n\n\terr := o.db.Transaction(func(tx *gorm.DB) error {\n\t\tsource := \"contract_gateway\"\n\n\t\tif len(activeIDs) > 0 {\n\t\t\tif res := tx.Model(&models.Company{}).Where(\"id IN ?\", activeIDs).Updates(map[string]interface{}{\"active_contract\": true, \"last_updated_by\": source}); res.Error != nil {\n\t\t\t\treturn res.Error\n\t\t\t}\n\t\t}\n\t\tif len(inactiveIDs) > 0 {\n\t\t\tif res := tx.Model(&models.Company{}).Where(\"id IN ?\", inactiveIDs).Updates(map[string]interface{}{\"active_contract\": false, \"last_updated_by\": source}); res.Error != nil {\n\t\t\t\treturn res.Error\n\t\t\t}\n\t\t}\n\n\t\tif len(inactiveIDs) > 0 {\n\t\t\tif err := o.lockEquipment(ctx, tx, inactiveIDs, log); err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t}\n\t\tif len(activeIDs) > 0 {\n\t\t\tif err := o.unlockEquipment(ctx, tx, activeIDs, log); err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t}\n\t\treturn nil\n\t})\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка транзакции при обновлении статусов контрактов и оборудования\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"Обновление статусов контрактов и оборудования успешно завершено.\")\n\t}\n}\n\n// handleDuplicatesFound создает или обновляет задачу на разрешение дубликатов.\nfunc (o *Orchestrator) handleDuplicatesFound(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.DuplicatesFoundPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(\n\t\tzap.String(\"entityType\", payload.EntityType),\n\t\tzap.String(\"field\", payload.Field),\n\t\tzap.String(\"value\", payload.Value),\n\t)\n\n\ttaskIdentifier := fmt.Sprintf(\"duplicate-%s-%s-%s\", payload.EntityType, payload.Field, payload.Value)\n\texistingTask, err := o.taskRepo.FindActiveTask(ctx, \"resolve_duplicate\", taskIdentifier)\n\tif err != nil || existingTask != nil {\n\t\tif err != nil {\n\t\t\tlog.Error(\"Ошибка проверки существующей задачи на дубликат\", zap.Error(err))\n\t\t}\n\t\treturn\n\t}\n\n\tdetailsJSON, _ := json.Marshal(map[string]interface{}{\"uuids\": payload.InternalIDs})\n\tcomment := fmt.Sprintf(\"Обнаружены дубликаты (%d шт.) по полю '%s'. Требуется выбрать эталонную запись.\", len(payload.InternalIDs), payload.Field)\n\ttask := models.ReconciliationTask{\n\t\tTaskType: \"resolve_duplicate\", EntityType: payload.EntityType, EntityUUID: taskIdentifier,\n\t\tDetails: datatypes.JSON(detailsJSON), Status: \"new\", Comment: comment,\n\t}\n\tif err := o.db.WithContext(ctx).Create(&task).Error; err != nil {\n\t\tlog.Error(\"Не удалось создать задачу на разрешение дубликатов\", zap.Error(err))\n\t}\n}\n\n// handleServerPollingSucceeded обрабатывает успешный результат опроса сервера.\nfunc (o *Orchestrator) handleServerPollingSucceeded(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServerPollingSucceededPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"internalServerUUID\", payload.ServerUUID))\n\tupdates := map[string]interface{}{\n\t\t\"server_name\":     payload.ServerName,\n\t\t\"server_edition\":  payload.ServerEdition,\n\t\t\"server_version\":  payload.ServerVersion,\n\t\t\"status\":          payload.NewStatus,\n\t\t\"last_polled_at\":  payload.LastPolledAt,\n\t\t\"last_updated_by\": \"rms_polling\",\n\t}\n\tif _, err := o.serverRepo.Update(ctx, nil, payload.ServerUUID, updates); err != nil {\n\t\tlog.Error(\"Не удалось обновить данные сервера после успешного опроса\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"Данные сервера успешно обновлены\", zap.String(\"new_status\", payload.NewStatus))\n\t}\n}\n\n// handleServerPollingFailed обрабатывает неудачный результат опроса сервера.\nfunc (o *Orchestrator) handleServerPollingFailed(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServerPollingFailedPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"internalServerUUID\", payload.ServerUUID))\n\tupdates := map[string]interface{}{\n\t\t\"status\":          payload.NewStatus,\n\t\t\"last_polled_at\":  payload.LastPolledAt,\n\t\t\"last_updated_by\": \"rms_polling\",\n\t}\n\tif _, err := o.serverRepo.Update(ctx, nil, payload.ServerUUID, updates); err != nil {\n\t\tlog.Error(\"Не удалось обновить статус сервера после неудачного опроса\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"Статус сервера обновлен после неудачного опроса\", zap.String(\"new_status\", payload.NewStatus))\n\t}\n}\n\n// handleFiscalRegisterDiscrepancy обрабатывает событие о расхождении данных ФР.\nfunc (o *Orchestrator) handleFiscalRegisterDiscrepancy(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.FiscalRegisterDiscrepancyPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := o.logger.With(zap.String(\"fr_external_uuid\", payload.FRServiceDeskUUID))\n\n\texistingTask, err := o.taskRepo.FindActiveTask(ctx, \"need_update\", payload.FRServiceDeskUUID)\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при поиске существующей задачи 'need_update'\", zap.Error(err))\n\t\treturn\n\t}\n\tif existingTask != nil {\n\t\tlog.Debug(\"Активная задача 'need_update' для этого ФР уже существует, новая не создается.\")\n\t\treturn\n\t}\n\n\tvar commentBuilder strings.Builder\n\tcommentBuilder.WriteString(fmt.Sprintf(\"Обнаружено расхождение данных для ФР (%s) между эталонной БД и ServiceDesk. Требуется обновить данные в ServiceDesk.\\n\\nРасхождения:\\n\", payload.FRServiceDeskUUID))\n\tfor field, details := range payload.Discrepancies {\n\t\tcommentBuilder.WriteString(fmt.Sprintf(\"- Поле '%s':\\n  - Эталон: %v\\n  - ServiceDesk: %v\\n\", field, details.EtalonValue, details.ServiceDeskValue))\n\t}\n\n\tdetailsJSON, _ := json.Marshal(payload.Discrepancies)\n\ttask := models.ReconciliationTask{\n\t\tTaskType: \"need_update\", EntityType: \"FiscalRegister\", EntityUUID: payload.FRServiceDeskUUID,\n\t\tDetails: datatypes.JSON(detailsJSON), Status: \"new\", Comment: commentBuilder.String(),\n\t}\n\tif err := o.db.WithContext(ctx).Create(&task).Error; err != nil {\n\t\tlog.Error(\"Не удалось создать задачу 'need_update'\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"Успешно создана задача 'need_update' на основе расхождений данных ФР.\")\n\t}\n}\n\n// handleAgentDataReceived вызывает движок обработки и исполняет его план.\nfunc (o *Orchestrator) handleAgentDataReceived(ctx context.Context, event eventbus.Event) {\n\t// ИЗМЕНЕНИЕ: Распаковываем новую полезную нагрузку.\n\tpayload, ok := event.Payload.(events.AgentDataPayload)\n\tif !ok {\n\t\to.logger.Error(\"Некорректная полезная нагрузка для события AgentDataReceived\")\n\t\treturn\n\t}\n\n\t// ИЗМЕНЕНИЕ: Используем Source для логирования.\n\tlog := o.logger.With(zap.String(\"source\", payload.Source))\n\tlog.Debug(\"Оркестратор НАЧАЛ обработку события AgentDataReceived\")\n\n\t// ИЗМЕНЕНИЕ: Передаем source и data в движок.\n\tresult := o.engine.ProcessAgentData(ctx, payload.Source, &payload.Data)\n\n\tif len(result.Actions) == 0 {\n\t\tlog.Info(\"Движок не вернул никаких действий для выполнения.\")\n\t\treturn\n\t}\n\n\terr := o.db.Transaction(func(tx *gorm.DB) error {\n\t\tfor _, action := range result.Actions {\n\t\t\tlog.Debug(\"Выполнение действия из плана\", zap.String(\"action\", string(action.Type)), zap.String(\"entity\", action.EntityType))\n\t\t\tswitch action.Type {\n\t\t\tcase ActionCreateTask:\n\t\t\t\tif err := tx.Create(action.Task).Error; err != nil {\n\t\t\t\t\treturn err\n\t\t\t\t}\n\t\t\tcase ActionUpdate:\n\t\t\t\taction.Updates[\"last_updated_by\"] = \"agent\"\n\t\t\t\tif err := o.performUpdate(ctx, tx, action.EntityType, action.EntityUUID, action.Updates); err != nil {\n\t\t\t\t\treturn err\n\t\t\t\t}\n\t\t\tcase ActionAddAdditionalOwner:\n\t\t\t\t// TODO: Адаптировать под внутренние ID\n\t\t\t}\n\t\t}\n\t\treturn nil\n\t})\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при выполнении плана действий от движка\", zap.Error(err))\n\t} else {\n\t\tlog.Info(\"План действий от движка успешно выполнен.\", zap.Int(\"actions_count\", len(result.Actions)))\n\t}\n}\n",
    "internal/processing/orchestrator_helpers.go": "// internal/processing/orchestrator_helpers.go\npackage processing\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\t\"fmt\"\n\t\"reflect\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// --- CRUD-хелперы ---\n\nfunc (o *Orchestrator) createEntity(ctx context.Context, entityType string, entity interface{}) (string, error) {\n\ttx := ctx.Value(\"tx\").(*gorm.DB)\n\tvar id string\n\tvar err error\n\tswitch v := entity.(type) {\n\tcase *models.Company:\n\t\terr = o.companyRepo.Create(ctx, tx, v)\n\t\tid = v.ID\n\tcase *models.Server:\n\t\terr = o.serverRepo.Create(ctx, tx, v)\n\t\tid = v.ID\n\tcase *models.Workstation:\n\t\terr = o.workstationRepo.Create(ctx, tx, v)\n\t\tid = v.ID\n\tcase *models.FiscalRegister:\n\t\terr = o.frRepo.Create(ctx, tx, v)\n\t\tid = v.ID\n\tdefault:\n\t\treturn \"\", fmt.Errorf(\"неподдерживаемый тип для создания: %T\", entity)\n\t}\n\treturn id, err\n}\n\nfunc (o *Orchestrator) performUpdate(ctx context.Context, tx *gorm.DB, entityType, internalID string, updates map[string]interface{}) error {\n\tvar err error\n\tswitch entityType {\n\tcase \"Company\":\n\t\t_, err = o.companyRepo.Update(ctx, tx, internalID, updates)\n\tcase \"Server\":\n\t\t_, err = o.serverRepo.Update(ctx, tx, internalID, updates)\n\tcase \"Workstation\":\n\t\t_, err = o.workstationRepo.Update(ctx, tx, internalID, updates)\n\tcase \"FiscalRegister\":\n\t\t_, err = o.frRepo.Update(ctx, tx, internalID, updates)\n\tdefault:\n\t\treturn fmt.Errorf(\"неподдерживаемый тип для обновления: %s\", entityType)\n\t}\n\treturn err\n}\n\nfunc (o *Orchestrator) performDelete(ctx context.Context, tx *gorm.DB, entityType, internalID string) error {\n\tvar err error\n\tswitch entityType {\n\tcase \"Company\":\n\t\t_, err = o.companyRepo.Delete(ctx, tx, internalID)\n\tcase \"Server\":\n\t\t_, err = o.serverRepo.Delete(ctx, tx, internalID)\n\tcase \"Workstation\":\n\t\t_, err = o.workstationRepo.Delete(ctx, tx, internalID)\n\tcase \"FiscalRegister\":\n\t\t_, err = o.frRepo.Delete(ctx, tx, internalID)\n\tdefault:\n\t\treturn fmt.Errorf(\"неподдерживаемый тип для удаления: %s\", entityType)\n\t}\n\treturn err\n}\n\n// --- Хелперы для управления оборудованием ---\n\nfunc (o *Orchestrator) lockEquipment(ctx context.Context, tx *gorm.DB, inactiveIDs []string, log *zap.Logger) error {\n\tfor _, model := range []interface{}{&models.Server{}, &models.Workstation{}, &models.FiscalRegister{}} {\n\t\tres := tx.WithContext(ctx).Model(model).Where(\"owner_id IN ? AND status != ?\", inactiveIDs, \"locked\").\n\t\t\tUpdates(map[string]interface{}{\"status_before_lock\": gorm.Expr(\"status\"), \"status\": \"locked\"})\n\t\tif res.Error != nil {\n\t\t\treturn res.Error\n\t\t}\n\t\tif res.RowsAffected > 0 {\n\t\t\tlog.Info(\"Заморожено единиц оборудования\", zap.Int64(\"count\", res.RowsAffected))\n\t\t}\n\t}\n\treturn nil\n}\n\nfunc (o *Orchestrator) unlockEquipment(ctx context.Context, tx *gorm.DB, activeIDs []string, log *zap.Logger) error {\n\tfor _, model := range []interface{}{&models.Server{}, &models.Workstation{}, &models.FiscalRegister{}} {\n\t\tres := tx.WithContext(ctx).Model(model).Where(\"owner_id IN ? AND status = ? AND status_before_lock IS NOT NULL\", activeIDs, \"locked\").\n\t\t\tUpdates(map[string]interface{}{\"status\": gorm.Expr(\"status_before_lock\"), \"status_before_lock\": nil})\n\t\tif res.Error != nil {\n\t\t\treturn res.Error\n\t\t}\n\t\tif res.RowsAffected > 0 {\n\t\t\tlog.Info(\"Разморожено единиц оборудования\", zap.Int64(\"count\", res.RowsAffected))\n\t\t}\n\t}\n\treturn nil\n}\n\n// --- Хелперы для сравнения (diff) ---\n\nfunc getLMDFromModel(entity interface{}) *time.Time {\n\tswitch v := entity.(type) {\n\tcase *models.Company:\n\t\treturn v.LastModifiedDate\n\tcase *models.Server:\n\t\treturn v.LastModifiedDate\n\tcase *models.Workstation:\n\t\treturn v.LastModifiedDate\n\tcase *models.FiscalRegister:\n\t\treturn v.LastModifiedDate\n\t}\n\treturn nil\n}\n\nfunc formatDiffValue(v interface{}) string {\n\tif v == nil {\n\t\treturn \"<nil>\"\n\t}\n\tval := reflect.ValueOf(v)\n\tif val.Kind() == reflect.Ptr {\n\t\tif val.IsNil() {\n\t\t\treturn \"<nil>\"\n\t\t}\n\t\treturn fmt.Sprintf(\"'%v'\", val.Elem().Interface())\n\t}\n\treturn fmt.Sprintf(\"'%v'\", v)\n}\n\nfunc compareAndLog[T comparable](updates map[string]interface{}, diffs *[]zap.Field, key string, current, new *T) {\n\tisCurrentNil := current == nil || reflect.ValueOf(current).IsNil()\n\tisNewNil := new == nil || reflect.ValueOf(new).IsNil()\n\tif isCurrentNil && isNewNil {\n\t\treturn\n\t}\n\tif isCurrentNil != isNewNil || *current != *new {\n\t\tupdates[key] = new\n\t\t*diffs = append(*diffs, zap.String(key, fmt.Sprintf(\"%s -> %s\", formatDiffValue(current), formatDiffValue(new))))\n\t}\n}\n\nfunc getCompanyDiff(current *models.Company, new *models.Company) (map[string]interface{}, []zap.Field) {\n\tupdates, diffs := make(map[string]interface{}), make([]zap.Field, 0)\n\tcompareAndLog(updates, &diffs, \"title\", current.Title, new.Title)\n\tcompareAndLog(updates, &diffs, \"address\", current.Address, new.Address)\n\tcompareAndLog(updates, &diffs, \"additional_name\", current.AdditionalName, new.AdditionalName)\n\tcompareAndLog(updates, &diffs, \"parent_id\", current.ParentID, new.ParentID)\n\tif current.DeletedAt.Valid {\n\t\tupdates[\"deleted_at\"] = gorm.Expr(\"NULL\")\n\t\tdiffs = append(diffs, zap.String(\"status\", \"deleted -> restored\"))\n\t}\n\treturn updates, diffs\n}\n\nfunc getServerDiff(current *models.Server, new *models.Server) (map[string]interface{}, []zap.Field) {\n\tupdates, diffs := make(map[string]interface{}), make([]zap.Field, 0)\n\tcompareAndLog(updates, &diffs, \"owner_id\", current.OwnerID, new.OwnerID)\n\tcompareAndLog(updates, &diffs, \"unique_id\", current.UniqueID, new.UniqueID)\n\tcompareAndLog(updates, &diffs, \"rdp\", current.RDP, new.RDP)\n\tcompareAndLog(updates, &diffs, \"server_version\", current.ServerVersion, new.ServerVersion)\n\tif current.DeletedAt.Valid {\n\t\tupdates[\"deleted_at\"] = gorm.Expr(\"NULL\")\n\t\tdiffs = append(diffs, zap.String(\"status\", \"deleted -> restored\"))\n\t}\n\treturn updates, diffs\n}\n\nfunc getWorkstationDiff(current *models.Workstation, new *models.Workstation) (map[string]interface{}, []zap.Field) {\n\tupdates, diffs := make(map[string]interface{}), make([]zap.Field, 0)\n\tcompareAndLog(updates, &diffs, \"owner_id\", current.OwnerID, new.OwnerID)\n\tif current.DeletedAt.Valid {\n\t\tupdates[\"deleted_at\"] = gorm.Expr(\"NULL\")\n\t\tdiffs = append(diffs, zap.String(\"status\", \"deleted -> restored\"))\n\t}\n\treturn updates, diffs\n}\n\nfunc getFiscalRegisterDiff(current *models.FiscalRegister, new *models.FiscalRegister) (map[string]interface{}, []zap.Field) {\n\tupdates, diffs := make(map[string]interface{}), make([]zap.Field, 0)\n\tcompareAndLog(updates, &diffs, \"owner_id\", current.OwnerID, new.OwnerID)\n\tif current.DeletedAt.Valid {\n\t\tupdates[\"deleted_at\"] = gorm.Expr(\"NULL\")\n\t\tdiffs = append(diffs, zap.String(\"status\", \"deleted -> restored\"))\n\t}\n\treturn updates, diffs\n}\n",
    "internal/repositories/agent_repo.go": "package repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// AgentRepo определяет интерфейс для работы с хранилищем агентов.\ntype AgentRepo interface {\n\tGetByUUID(ctx context.Context, uuid string) (*models.Agent, error)\n\tCreate(ctx context.Context, agent *models.Agent) error\n\tUpdate(ctx context.Context, agent *models.Agent) error\n\tCountByOwnerUUID(ctx context.Context, ownerUUID string) (int64, error)\n}\n\ntype agentRepo struct {\n\tdb *gorm.DB\n}\n\n// NewAgentRepo создает новый экземпляр репозитория агентов.\nfunc NewAgentRepo(db *gorm.DB) AgentRepo {\n\treturn &agentRepo{db: db}\n}\n\nfunc (r *agentRepo) GetByUUID(ctx context.Context, uuid string) (*models.Agent, error) {\n\tvar agent models.Agent\n\terr := r.db.WithContext(ctx).Where(\"uuid = ?\", uuid).First(&agent).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil // Это не ошибка, а нормальный случай \"не найдено\"\n\t}\n\treturn &agent, err\n}\n\nfunc (r *agentRepo) Create(ctx context.Context, agent *models.Agent) error {\n\treturn r.db.WithContext(ctx).Create(agent).Error\n}\n\nfunc (r *agentRepo) Update(ctx context.Context, agent *models.Agent) error {\n\treturn r.db.WithContext(ctx).Save(agent).Error\n}\n\n// CountByOwnerUUID подсчитывает количество агентов, принадлежащих одной компании.\nfunc (r *agentRepo) CountByOwnerUUID(ctx context.Context, ownerUUID string) (int64, error) {\n\tvar count int64\n\terr := r.db.WithContext(ctx).Model(&models.Agent{}).Where(\"owner_service_desk_uuid = ?\", ownerUUID).Count(&count).Error\n\treturn count, err\n}\n",
    "internal/repositories/company_repo.go": "// internal/repositories/company_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// CompanyRepo определяет интерфейс для работы с хранилищем компаний.\ntype CompanyRepo interface {\n\tCreate(ctx context.Context, tx *gorm.DB, company *models.Company) error\n\tUpdate(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error)\n\tDelete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error)\n\tGetByID(ctx context.Context, internalID string) (*models.Company, error)\n\tGetByIDs(ctx context.Context, internalIDs []string) ([]models.Company, error)\n\tGetByIDUnscoped(ctx context.Context, internalID string) (*models.Company, error)\n\tGetAllParentIDs(ctx context.Context, childID string) ([]string, error)\n\tGetAllIDsAndDates(ctx context.Context) (map[string]*models.Company, error)\n\tSearch(ctx context.Context, term string, showInactive bool, limit, offset int) ([]models.Company, error)\n}\n\n// companyRepo реализует интерфейс CompanyRepo.\ntype companyRepo struct {\n\tdb *gorm.DB\n}\n\n// NewCompanyRepo создает новый экземпляр репозитория компаний.\nfunc NewCompanyRepo(db *gorm.DB) CompanyRepo {\n\treturn &companyRepo{db: db}\n}\n\n// dbOrTx возвращает переданную транзакцию или основное подключение к БД.\nfunc (r *companyRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\n// Create создает новую компанию в базе данных.\nfunc (r *companyRepo) Create(ctx context.Context, tx *gorm.DB, company *models.Company) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(company).Error\n}\n\n// Update обновляет данные компании по ее внутреннему ID.\nfunc (r *companyRepo) Update(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Model(&models.Company{}).Where(\"id = ?\", internalID).Updates(updateData)\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// Delete выполняет \"мягкое удаление\" компании по ее внутреннему ID.\nfunc (r *companyRepo) Delete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Where(\"id = ?\", internalID).Delete(&models.Company{})\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// GetByID находит компанию по ее внутреннему ID.\nfunc (r *companyRepo) GetByID(ctx context.Context, internalID string) (*models.Company, error) {\n\tvar company models.Company\n\terr := r.db.WithContext(ctx).Where(\"id = ?\", internalID).First(&company).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &company, err\n}\n\n// GetByIDs находит компании по списку их внутренних ID.\nfunc (r *companyRepo) GetByIDs(ctx context.Context, internalIDs []string) ([]models.Company, error) {\n\tif len(internalIDs) == 0 {\n\t\treturn nil, nil\n\t}\n\tvar companies []models.Company\n\terr := r.db.WithContext(ctx).Where(\"id IN ?\", internalIDs).Find(&companies).Error\n\treturn companies, err\n}\n\n// GetByIDUnscoped находит компанию по внутреннему ID, включая \"мягко удаленные\".\nfunc (r *companyRepo) GetByIDUnscoped(ctx context.Context, internalID string) (*models.Company, error) {\n\tvar company models.Company\n\terr := r.db.WithContext(ctx).Unscoped().Where(\"id = ?\", internalID).First(&company).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &company, err\n}\n\n// GetAllParentIDs находит все родительские внутренние ID для дочерней компании.\nfunc (r *companyRepo) GetAllParentIDs(ctx context.Context, childID string) ([]string, error) {\n\tvar parentIDs []string\n\tcurrentID := childID\n\n\t// Защита от бесконечного цикла, максимум 10 уровней вложенности\n\tfor i := 0; i < 10; i++ {\n\t\tvar company models.Company\n\t\terr := r.db.WithContext(ctx).\n\t\t\tSelect(\"parent_id\").\n\t\t\tWhere(\"id = ?\", currentID).\n\t\t\tFirst(&company).Error\n\n\t\tif err == gorm.ErrRecordNotFound {\n\t\t\tbreak // Дошли до корня или компания не найдена\n\t\t}\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\n\t\tif company.ParentID != nil && *company.ParentID != \"\" {\n\t\t\tparentIDs = append(parentIDs, *company.ParentID)\n\t\t\tcurrentID = *company.ParentID\n\t\t} else {\n\t\t\tbreak // Нет родителя\n\t\t}\n\t}\n\treturn parentIDs, nil\n}\n\n// GetAllIDsAndDates извлекает все внутренние ID, даты модификации и статусы удаления.\nfunc (r *companyRepo) GetAllIDsAndDates(ctx context.Context) (map[string]*models.Company, error) {\n\tvar companies []*models.Company\n\terr := r.db.WithContext(ctx).Unscoped().Select(\"id\", \"last_modified_date\", \"deleted_at\").Find(&companies).Error\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tcompanyMap := make(map[string]*models.Company, len(companies))\n\tfor _, c := range companies {\n\t\tcompanyMap[c.ID] = c\n\t}\n\treturn companyMap, nil\n}\n\n// Search выполняет поиск компаний по текстовому запросу.\nfunc (r *companyRepo) Search(ctx context.Context, term string, showInactive bool, limit, offset int) ([]models.Company, error) {\n\tvar companies []models.Company\n\tquery := r.db.WithContext(ctx).\n\t\tWhere(\"title ILIKE ? OR address ILIKE ? OR additional_name ILIKE ?\", \"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\")\n\n\tif !showInactive {\n\t\tquery = query.Where(\"active_contract = ?\", true)\n\t}\n\n\terr := query.Limit(limit).Offset(offset).Find(&companies).Error\n\treturn companies, err\n}\n",
    "internal/repositories/contract_repo.go": "// internal/repositories/contract_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// ContractRepo определяет интерфейс для работы с хранилищем контрактов.\ntype ContractRepo interface {\n\tCreate(ctx context.Context, tx *gorm.DB, contract *models.Contract) error\n\tUpdate(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error)\n\tDelete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error)\n\tGetByID(ctx context.Context, internalID string) (*models.Contract, error)\n\tGetByIDUnscoped(ctx context.Context, internalID string) (*models.Contract, error)\n\tGetAllIDsAndDates(ctx context.Context) (map[string]*models.Contract, error)\n\tGetActiveContractIDsForCompany(ctx context.Context, companyID string) ([]string, error)\n}\n\ntype contractRepo struct {\n\tdb *gorm.DB\n}\n\n// NewContractRepo создает новый экземпляр репозитория.\nfunc NewContractRepo(db *gorm.DB) ContractRepo {\n\treturn &contractRepo{db: db}\n}\n\nfunc (r *contractRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\nfunc (r *contractRepo) Create(ctx context.Context, tx *gorm.DB, contract *models.Contract) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(contract).Error\n}\n\nfunc (r *contractRepo) Update(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Model(&models.Contract{}).Where(\"id = ?\", internalID).Updates(updateData)\n\treturn res.RowsAffected > 0, res.Error\n}\n\nfunc (r *contractRepo) Delete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Where(\"id = ?\", internalID).Delete(&models.Contract{})\n\treturn res.RowsAffected > 0, res.Error\n}\n\nfunc (r *contractRepo) GetByID(ctx context.Context, internalID string) (*models.Contract, error) {\n\tvar contract models.Contract\n\terr := r.db.WithContext(ctx).Where(\"id = ?\", internalID).First(&contract).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &contract, err\n}\n\nfunc (r *contractRepo) GetByIDUnscoped(ctx context.Context, internalID string) (*models.Contract, error) {\n\tvar contract models.Contract\n\terr := r.db.WithContext(ctx).Unscoped().Where(\"id = ?\", internalID).First(&contract).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &contract, err\n}\n\nfunc (r *contractRepo) GetAllIDsAndDates(ctx context.Context) (map[string]*models.Contract, error) {\n\tvar contracts []*models.Contract\n\terr := r.db.WithContext(ctx).Unscoped().Select(\"id\", \"last_modified_date\", \"deleted_at\").Find(&contracts).Error\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tcontractMap := make(map[string]*models.Contract, len(contracts))\n\tfor _, c := range contracts {\n\t\tcontractMap[c.ID] = c\n\t}\n\treturn contractMap, nil\n}\n\n// GetActiveContractIDsForCompany находит все активные контракты для компании по ее внутреннему ID.\nfunc (r *contractRepo) GetActiveContractIDsForCompany(ctx context.Context, companyID string) ([]string, error) {\n\tvar contractIDs []string\n\terr := r.db.WithContext(ctx).Model(&models.Contract{}).\n\t\tJoins(\"JOIN company_contracts ON company_contracts.contract_id = contracts.id\").\n\t\tWhere(\"company_contracts.company_id = ? AND contracts.state = ?\", companyID, \"active\").\n\t\tPluck(\"contracts.id\", &contractIDs).Error\n\treturn contractIDs, err\n}\n",
    "internal/repositories/fr_repo.go": "// internal/repositories/fr_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// FiscalRegisterRepo определяет интерфейс для работы с хранилищем фискальных регистраторов.\ntype FiscalRegisterRepo interface {\n\tCreate(ctx context.Context, tx *gorm.DB, fr *models.FiscalRegister) error\n\tUpdate(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error)\n\tDelete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error)\n\tGetByID(ctx context.Context, internalID string) (*models.FiscalRegister, error)\n\tGetByIDUnscoped(ctx context.Context, internalID string) (*models.FiscalRegister, error)\n\tGetAllIDsAndDates(ctx context.Context) (map[string]*models.FiscalRegister, error)\n\tSearch(ctx context.Context, term string, limit, offset int) ([]models.FiscalRegister, error)\n\tFindBySerialNumber(ctx context.Context, sn string) (*models.FiscalRegister, error)\n\tFindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.FiscalRegister, error)\n}\n\n// frRepo реализует интерфейс FiscalRegisterRepo.\ntype frRepo struct {\n\tdb *gorm.DB\n}\n\n// NewFiscalRegisterRepo создает новый экземпляр репозитория.\nfunc NewFiscalRegisterRepo(db *gorm.DB) FiscalRegisterRepo {\n\treturn &frRepo{db: db}\n}\n\nfunc (r *frRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\n// Create создает новый фискальный регистратор в базе данных.\nfunc (r *frRepo) Create(ctx context.Context, tx *gorm.DB, fr *models.FiscalRegister) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(fr).Error\n}\n\n// Update обновляет данные фискального регистратора по его внутреннему ID.\nfunc (r *frRepo) Update(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Model(&models.FiscalRegister{}).Where(\"id = ?\", internalID).Updates(updateData)\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// Delete выполняет \"мягкое удаление\" фискального регистратора по его внутреннему ID.\nfunc (r *frRepo) Delete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Where(\"id = ?\", internalID).Delete(&models.FiscalRegister{})\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// GetByID находит фискальный регистратор по его внутреннему ID.\nfunc (r *frRepo) GetByID(ctx context.Context, internalID string) (*models.FiscalRegister, error) {\n\tvar fr models.FiscalRegister\n\terr := r.db.WithContext(ctx).Where(\"id = ?\", internalID).First(&fr).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &fr, err\n}\n\n// GetByIDUnscoped находит запись по внутреннему ID, включая \"мягко удаленные\".\nfunc (r *frRepo) GetByIDUnscoped(ctx context.Context, internalID string) (*models.FiscalRegister, error) {\n\tvar fr models.FiscalRegister\n\terr := r.db.WithContext(ctx).Unscoped().Where(\"id = ?\", internalID).First(&fr).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &fr, err\n}\n\n// GetAllIDsAndDates извлекает все внутренние ID, даты модификации и статусы удаления.\nfunc (r *frRepo) GetAllIDsAndDates(ctx context.Context) (map[string]*models.FiscalRegister, error) {\n\tvar frs []*models.FiscalRegister\n\tif err := r.db.WithContext(ctx).Unscoped().Select(\"id\", \"last_modified_date\", \"deleted_at\").Find(&frs).Error; err != nil {\n\t\treturn nil, err\n\t}\n\tfrMap := make(map[string]*models.FiscalRegister, len(frs))\n\tfor _, fr := range frs {\n\t\tfrMap[fr.ID] = fr\n\t}\n\treturn frMap, nil\n}\n\n// Search выполняет поиск фискальных регистраторов по текстовому запросу.\nfunc (r *frRepo) Search(ctx context.Context, term string, limit, offset int) ([]models.FiscalRegister, error) {\n\tvar frs []models.FiscalRegister\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"rn_kkt ILIKE ? OR fr_serial_number ILIKE ? OR fn_number ILIKE ? OR legal_name ILIKE ?\",\n\t\t\t\"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\").\n\t\tLimit(limit).Offset(offset).Find(&frs).Error\n\treturn frs, err\n}\n\n// FindBySerialNumber ищет фискальный регистратор по серийному номеру.\nfunc (r *frRepo) FindBySerialNumber(ctx context.Context, sn string) (*models.FiscalRegister, error) {\n\tif sn == \"\" {\n\t\treturn nil, nil\n\t}\n\tvar fr models.FiscalRegister\n\terr := r.db.WithContext(ctx).Where(\"fr_serial_number = ?\", sn).Order(\"updated_at DESC\").First(&fr).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &fr, err\n}\n\n// FindByOwnerIDs находит все фискальные регистраторы, принадлежащие указанным владельцам.\nfunc (r *frRepo) FindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.FiscalRegister, error) {\n\tif len(ownerIDs) == 0 {\n\t\treturn nil, nil\n\t}\n\tvar frs []models.FiscalRegister\n\terr := r.db.WithContext(ctx).Where(\"owner_id IN ?\", ownerIDs).Find(&frs).Error\n\treturn frs, err\n}\n",
    "internal/repositories/link_repo.go": "// internal/repositories/link_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// LinkRepo определяет интерфейс для работы с хранилищем связей с внешними системами.\ntype LinkRepo interface {\n\tGetByExternalID(ctx context.Context, tx *gorm.DB, systemName, externalID string) (*models.ExternalSystemLink, error)\n\tGetByInternalID(ctx context.Context, tx *gorm.DB, systemName, internalID string) (*models.ExternalSystemLink, error)\n\tCreate(ctx context.Context, tx *gorm.DB, link *models.ExternalSystemLink) error\n\tDeleteByInternalID(ctx context.Context, tx *gorm.DB, systemName, internalID string) error\n\tFindInternalIDByExternalID(ctx context.Context, tx *gorm.DB, systemName, externalID string) (string, error)\n}\n\ntype linkRepo struct {\n\tdb *gorm.DB\n}\n\n// NewLinkRepo создает новый экземпляр репозитория.\nfunc NewLinkRepo(db *gorm.DB) LinkRepo {\n\treturn &linkRepo{db: db}\n}\n\nfunc (r *linkRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\n// GetByExternalID находит связь по внешнему ID.\nfunc (r *linkRepo) GetByExternalID(ctx context.Context, tx *gorm.DB, systemName, externalID string) (*models.ExternalSystemLink, error) {\n\tvar link models.ExternalSystemLink\n\terr := r.dbOrTx(tx).WithContext(ctx).\n\t\tWhere(\"system_name = ? AND external_id = ?\", systemName, externalID).\n\t\tFirst(&link).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &link, err\n}\n\n// GetByInternalID находит связь по внутреннему ID.\nfunc (r *linkRepo) GetByInternalID(ctx context.Context, tx *gorm.DB, systemName, internalID string) (*models.ExternalSystemLink, error) {\n\tvar link models.ExternalSystemLink\n\terr := r.dbOrTx(tx).WithContext(ctx).\n\t\tWhere(\"system_name = ? AND internal_id = ?\", systemName, internalID).\n\t\tFirst(&link).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &link, err\n}\n\n// Create создает новую запись о связи.\nfunc (r *linkRepo) Create(ctx context.Context, tx *gorm.DB, link *models.ExternalSystemLink) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(link).Error\n}\n\n// DeleteByInternalID удаляет связь по внутреннему ID.\nfunc (r *linkRepo) DeleteByInternalID(ctx context.Context, tx *gorm.DB, systemName, internalID string) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).\n\t\tWhere(\"system_name = ? AND internal_id = ?\", systemName, internalID).\n\t\tDelete(&models.ExternalSystemLink{}).Error\n}\n\n// FindInternalIDByExternalID быстро находит внутренний ID по внешнему без загрузки всей структуры.\nfunc (r *linkRepo) FindInternalIDByExternalID(ctx context.Context, tx *gorm.DB, systemName, externalID string) (string, error) {\n\tvar internalID string\n\terr := r.dbOrTx(tx).WithContext(ctx).Model(&models.ExternalSystemLink{}).\n\t\tWhere(\"system_name = ? AND external_id = ?\", systemName, externalID).\n\t\tPluck(\"internal_id\", &internalID).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn \"\", nil // Возвращаем пустую строку, а не ошибку, если не найдено\n\t}\n\treturn internalID, err\n}\n",
    "internal/repositories/server_repo.go": "// internal/repositories/server_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\t\"time\"\n\n\t\"gorm.io/gorm\"\n)\n\n// ServerRepo определяет интерфейс для работы с хранилищем серверов.\ntype ServerRepo interface {\n\tCreate(ctx context.Context, tx *gorm.DB, server *models.Server) error\n\tUpdate(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error)\n\tDelete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error)\n\tGetByID(ctx context.Context, internalID string) (*models.Server, error)\n\tGetByIDUnscoped(ctx context.Context, internalID string) (*models.Server, error)\n\tGetAllIDsAndDates(ctx context.Context) (map[string]*models.Server, error)\n\tSearch(ctx context.Context, term string, limit, offset int) ([]models.Server, error)\n\tFindByCRMidOrIP(ctx context.Context, crmid string, ip string) (*models.Server, error)\n\tFindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.Server, error)\n\tFindForPolling(ctx context.Context, limit int, interval time.Duration) ([]models.Server, error)\n}\n\ntype serverRepo struct {\n\tdb *gorm.DB\n}\n\n// NewServerRepo создает новый экземпляр репозитория.\nfunc NewServerRepo(db *gorm.DB) ServerRepo {\n\treturn &serverRepo{db: db}\n}\n\nfunc (r *serverRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\n// Create создает новый сервер в базе данных.\nfunc (r *serverRepo) Create(ctx context.Context, tx *gorm.DB, server *models.Server) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(server).Error\n}\n\n// Update обновляет данные сервера по его внутреннему ID.\nfunc (r *serverRepo) Update(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Model(&models.Server{}).Where(\"id = ?\", internalID).Updates(updateData)\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// Delete выполняет \"мягкое удаление\" сервера по его внутреннему ID.\nfunc (r *serverRepo) Delete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Where(\"id = ?\", internalID).Delete(&models.Server{})\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// GetByID находит сервер по его внутреннему ID.\nfunc (r *serverRepo) GetByID(ctx context.Context, internalID string) (*models.Server, error) {\n\tvar server models.Server\n\terr := r.db.WithContext(ctx).Preload(\"AdditionalOwners\").Where(\"id = ?\", internalID).First(&server).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &server, err\n}\n\n// GetByIDUnscoped находит сервер по внутреннему ID, включая \"мягко удаленные\".\nfunc (r *serverRepo) GetByIDUnscoped(ctx context.Context, internalID string) (*models.Server, error) {\n\tvar server models.Server\n\terr := r.db.WithContext(ctx).Unscoped().Preload(\"AdditionalOwners\").Where(\"id = ?\", internalID).First(&server).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &server, err\n}\n\n// GetAllIDsAndDates извлекает все внутренние ID, даты модификации и статусы удаления.\nfunc (r *serverRepo) GetAllIDsAndDates(ctx context.Context) (map[string]*models.Server, error) {\n\tvar servers []*models.Server\n\tif err := r.db.WithContext(ctx).Unscoped().Select(\"id\", \"last_modified_date\", \"deleted_at\").Find(&servers).Error; err != nil {\n\t\treturn nil, err\n\t}\n\tserverMap := make(map[string]*models.Server, len(servers))\n\tfor _, s := range servers {\n\t\tserverMap[s.ID] = s\n\t}\n\treturn serverMap, nil\n}\n\n// Search выполняет поиск серверов по текстовому запросу.\nfunc (r *serverRepo) Search(ctx context.Context, term string, limit, offset int) ([]models.Server, error) {\n\tvar servers []models.Server\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"device_name ILIKE ? OR ip ILIKE ? OR unique_id ILIKE ? OR description ILIKE ? OR server_name ILIKE ?\",\n\t\t\t\"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\", \"%\"+term+\"%\").\n\t\tLimit(limit).Offset(offset).Find(&servers).Error\n\treturn servers, err\n}\n\n// FindForPolling находит серверы, которые необходимо опросить.\nfunc (r *serverRepo) FindForPolling(ctx context.Context, limit int, interval time.Duration) ([]models.Server, error) {\n\tvar servers []models.Server\n\tthreshold := time.Now().Add(-interval)\n\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"ip IS NOT NULL AND ip != ''\").\n\t\tWhere(\"status NOT IN (?, ?)\", \"archived\", \"locked\").\n\t\tWhere(\"last_polled_at IS NULL OR last_polled_at < ?\", threshold).\n\t\tLimit(limit).\n\t\tOrder(\"last_polled_at ASC NULLS FIRST\").\n\t\tFind(&servers).Error\n\treturn servers, err\n}\n\n// FindByCRMidOrIP ищет сервер по CRMid (приоритет) или по IP.\nfunc (r *serverRepo) FindByCRMidOrIP(ctx context.Context, crmid string, ip string) (*models.Server, error) {\n\tvar server models.Server\n\tquery := r.db.WithContext(ctx).Preload(\"AdditionalOwners\")\n\n\tif crmid != \"\" {\n\t\terr := query.Where(\"crm_id = ? AND status != ?\", crmid, \"locked\").First(&server).Error\n\t\tif err == nil {\n\t\t\treturn &server, nil\n\t\t}\n\t\tif err != gorm.ErrRecordNotFound {\n\t\t\treturn nil, err\n\t\t}\n\t}\n\n\tif ip != \"\" {\n\t\terr := query.Where(\"ip = ? AND status != ?\", ip, \"locked\").First(&server).Error\n\t\tif err == gorm.ErrRecordNotFound {\n\t\t\treturn nil, nil\n\t\t}\n\t\treturn &server, err\n\t}\n\n\treturn nil, nil\n}\n\n// FindByOwnerIDs находит все серверы, принадлежащие указанным владельцам.\nfunc (r *serverRepo) FindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.Server, error) {\n\tif len(ownerIDs) == 0 {\n\t\treturn nil, nil\n\t}\n\tvar servers []models.Server\n\terr := r.db.WithContext(ctx).Where(\"owner_id IN ?\", ownerIDs).Find(&servers).Error\n\treturn servers, err\n}\n",
    "internal/repositories/task_repo.go": "// internal/repositories/task_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\t\"time\"\n\n\t\"gorm.io/gorm\"\n)\n\n// TaskRepo определяет интерфейс для работы с хранилищем задач.\ntype TaskRepo interface {\n\tGetByID(ctx context.Context, id uint) (*models.ReconciliationTask, error) // <-- ДОБАВЛЕНО\n\tFindActiveDuplicateTaskByMemberUUIDs(ctx context.Context, uuids []string) (*models.ReconciliationTask, error)\n\tFindActiveTask(ctx context.Context, taskType, entityUUID string) (*models.ReconciliationTask, error)\n\tFindRecentlyResolvedTask(ctx context.Context, taskType, entityUUID string, window time.Duration) (*models.ReconciliationTask, error)\n}\n\ntype taskRepo struct {\n\tdb *gorm.DB\n}\n\n// NewTaskRepo создает новый экземпляр репозитория.\nfunc NewTaskRepo(db *gorm.DB) TaskRepo {\n\treturn &taskRepo{db: db}\n}\n\n// FindActiveTask ищет активную задачу по типу и UUID связанной сущности.\nfunc (r *taskRepo) FindActiveTask(ctx context.Context, taskType, entityUUID string) (*models.ReconciliationTask, error) {\n\tif taskType == \"\" || entityUUID == \"\" {\n\t\t// Не ищем задачи без ключевых идентификаторов\n\t\treturn nil, nil\n\t}\n\n\tvar task models.ReconciliationTask\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"task_type = ? AND entity_uuid = ? AND status = 'new'\", taskType, entityUUID).\n\t\tFirst(&task).Error\n\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &task, nil\n}\n\n// FindActiveDuplicateTaskByMemberUUIDs ищет активную задачу 'resolve_duplicate',\n// в которой участвует хотя бы одна из переданных сущностей.\nfunc (r *taskRepo) FindActiveDuplicateTaskByMemberUUIDs(ctx context.Context, uuids []string) (*models.ReconciliationTask, error) {\n\tif len(uuids) == 0 {\n\t\treturn nil, nil\n\t}\n\tvar task models.ReconciliationTask\n\n\t// Этот запрос более сложный, но более надежный для GORM.\n\t// Он \"разворачивает\" JSON-массив entityUUIDs в строки и проверяет,\n\t// есть ли среди них хотя бы одно совпадение с нашим списком uuids.\n\tsubQuery := r.db.Model(&models.ReconciliationTask{}).\n\t\tSelect(\"id\").\n\t\tJoins(\"join jsonb_array_elements_text(details->'entityUUIDs') as uuid on true\").\n\t\tWhere(\"task_type = ? AND status = 'new'\", \"resolve_duplicate\").\n\t\tWhere(\"uuid IN ?\", uuids)\n\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"id IN (?)\", subQuery).\n\t\tFirst(&task).Error\n\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &task, nil\n}\n\n// GetByID находит задачу по ее первичному ключу (ID).\nfunc (r *taskRepo) GetByID(ctx context.Context, id uint) (*models.ReconciliationTask, error) {\n\tvar task models.ReconciliationTask\n\terr := r.db.WithContext(ctx).First(&task, id).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &task, err\n}\n\n// FindRecentlyResolvedTask ищет решенную задачу в заданном временном окне.\n// Это нужно, чтобы найти исходную задачу add_equipment после того, как сущность была создана в SD и пришла через шлюз.\nfunc (r *taskRepo) FindRecentlyResolvedTask(ctx context.Context, taskType, entityUUID string, window time.Duration) (*models.ReconciliationTask, error) {\n\tif taskType == \"\" || entityUUID == \"\" {\n\t\treturn nil, nil\n\t}\n\n\tvar task models.ReconciliationTask\n\t// Ищем задачу, которая была решена (updated_at) не так давно\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"task_type = ? AND entity_uuid = ? AND status = 'resolved' AND updated_at > ?\", taskType, entityUUID, time.Now().Add(-window)).\n\t\tOrder(\"updated_at DESC\"). // Берем самую свежую\n\t\tFirst(&task).Error\n\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\treturn &task, nil\n}\n",
    "internal/repositories/user_repo.go": "// <-- НОВЫЙ ФАЙЛ -->\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\n\t\"gorm.io/gorm\"\n)\n\n// UserRepo определяет интерфейс для работы с хранилищем пользователей.\ntype UserRepo interface {\n\tGetAll(ctx context.Context) ([]models.User, error)\n\tGetByID(ctx context.Context, id uint) (*models.User, error)\n\tGetByUsername(ctx context.Context, username string) (*models.User, error)\n\tCreate(ctx context.Context, user *models.User) error\n\tUpdate(ctx context.Context, user *models.User) error\n\tDelete(ctx context.Context, id uint) error\n\tIsUsernameTaken(ctx context.Context, username string, excludeID uint) (bool, error)\n}\n\ntype userRepo struct{ db *gorm.DB }\n\nfunc NewUserRepo(db *gorm.DB) UserRepo {\n\treturn &userRepo{db: db}\n}\n\nfunc (r *userRepo) GetAll(ctx context.Context) ([]models.User, error) {\n\tvar users []models.User\n\terr := r.db.WithContext(ctx).Find(&users).Error\n\treturn users, err\n}\n\nfunc (r *userRepo) GetByID(ctx context.Context, id uint) (*models.User, error) {\n\tvar user models.User\n\terr := r.db.WithContext(ctx).First(&user, id).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &user, err\n}\n\nfunc (r *userRepo) GetByUsername(ctx context.Context, username string) (*models.User, error) {\n\tvar user models.User\n\terr := r.db.WithContext(ctx).Where(\"username = ?\", username).First(&user).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &user, err\n}\n\nfunc (r *userRepo) Create(ctx context.Context, user *models.User) error {\n\treturn r.db.WithContext(ctx).Create(user).Error\n}\n\nfunc (r *userRepo) Update(ctx context.Context, user *models.User) error {\n\treturn r.db.WithContext(ctx).Save(user).Error\n}\n\nfunc (r *userRepo) Delete(ctx context.Context, id uint) error {\n\treturn r.db.WithContext(ctx).Delete(&models.User{}, id).Error\n}\n\nfunc (r *userRepo) IsUsernameTaken(ctx context.Context, username string, excludeID uint) (bool, error) {\n\tvar count int64\n\tquery := r.db.WithContext(ctx).Model(&models.User{}).Where(\"username = ?\", username)\n\tif excludeID > 0 {\n\t\tquery = query.Where(\"id != ?\", excludeID)\n\t}\n\terr := query.Count(&count).Error\n\treturn count > 0, err\n}\n",
    "internal/repositories/workstation_repo.go": "// internal/repositories/workstation_repo.go\npackage repositories\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/models\"\n\t\"strings\"\n\n\t\"gorm.io/gorm\"\n)\n\n// WorkstationRepo определяет интерфейс для работы с хранилищем рабочих станций.\ntype WorkstationRepo interface {\n\tCreate(ctx context.Context, tx *gorm.DB, workstation *models.Workstation) error\n\tUpdate(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error)\n\tDelete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error)\n\tGetByID(ctx context.Context, internalID string) (*models.Workstation, error)\n\tGetByIDUnscoped(ctx context.Context, internalID string) (*models.Workstation, error)\n\tGetAllIDsAndDates(ctx context.Context) (map[string]*models.Workstation, error)\n\tSearch(ctx context.Context, term string, limit, offset int) ([]models.Workstation, error)\n\tFindByRemoteIDs(ctx context.Context, tv, ad, lm string) (*models.Workstation, error)\n\tFindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.Workstation, error)\n}\n\n// workstationRepo реализует интерфейс WorkstationRepo.\ntype workstationRepo struct {\n\tdb *gorm.DB\n}\n\n// NewWorkstationRepo создает новый экземпляр репозитория.\nfunc NewWorkstationRepo(db *gorm.DB) WorkstationRepo {\n\treturn &workstationRepo{db: db}\n}\n\nfunc (r *workstationRepo) dbOrTx(tx *gorm.DB) *gorm.DB {\n\tif tx != nil {\n\t\treturn tx\n\t}\n\treturn r.db\n}\n\n// Create создает новую рабочую станцию в базе данных.\nfunc (r *workstationRepo) Create(ctx context.Context, tx *gorm.DB, workstation *models.Workstation) error {\n\treturn r.dbOrTx(tx).WithContext(ctx).Create(workstation).Error\n}\n\n// Update обновляет данные рабочей станции по ее внутреннему ID.\nfunc (r *workstationRepo) Update(ctx context.Context, tx *gorm.DB, internalID string, updateData map[string]interface{}) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Model(&models.Workstation{}).Where(\"id = ?\", internalID).Updates(updateData)\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// Delete выполняет \"мягкое удаление\" рабочей станции по ее внутреннему ID.\nfunc (r *workstationRepo) Delete(ctx context.Context, tx *gorm.DB, internalID string) (bool, error) {\n\tres := r.dbOrTx(tx).WithContext(ctx).Where(\"id = ?\", internalID).Delete(&models.Workstation{})\n\treturn res.RowsAffected > 0, res.Error\n}\n\n// GetByID находит рабочую станцию по ее внутреннему ID.\nfunc (r *workstationRepo) GetByID(ctx context.Context, internalID string) (*models.Workstation, error) {\n\tvar workstation models.Workstation\n\terr := r.db.WithContext(ctx).Where(\"id = ?\", internalID).First(&workstation).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &workstation, err\n}\n\n// GetByIDUnscoped находит рабочую станцию по внутреннему ID, включая \"мягко удаленные\".\nfunc (r *workstationRepo) GetByIDUnscoped(ctx context.Context, internalID string) (*models.Workstation, error) {\n\tvar workstation models.Workstation\n\terr := r.db.WithContext(ctx).Unscoped().Where(\"id = ?\", internalID).First(&workstation).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &workstation, err\n}\n\n// GetAllIDsAndDates извлекает все внутренние ID, даты модификации и статусы удаления.\nfunc (r *workstationRepo) GetAllIDsAndDates(ctx context.Context) (map[string]*models.Workstation, error) {\n\tvar workstations []*models.Workstation\n\tif err := r.db.WithContext(ctx).Unscoped().Select(\"id\", \"last_modified_date\", \"deleted_at\").Find(&workstations).Error; err != nil {\n\t\treturn nil, err\n\t}\n\tworkstationMap := make(map[string]*models.Workstation, len(workstations))\n\tfor _, ws := range workstations {\n\t\tworkstationMap[ws.ID] = ws\n\t}\n\treturn workstationMap, nil\n}\n\n// Search выполняет поиск рабочих станций по текстовому запросу.\nfunc (r *workstationRepo) Search(ctx context.Context, term string, limit, offset int) ([]models.Workstation, error) {\n\tvar workstations []models.Workstation\n\terr := r.db.WithContext(ctx).\n\t\tWhere(\"device_name ILIKE ? OR description ILIKE ?\", \"%\"+term+\"%\", \"%\"+term+\"%\").\n\t\tLimit(limit).Offset(offset).Find(&workstations).Error\n\treturn workstations, err\n}\n\n// FindByRemoteIDs ищет рабочую станцию по любому из ID удаленного доступа.\nfunc (r *workstationRepo) FindByRemoteIDs(ctx context.Context, tv, ad, lm string) (*models.Workstation, error) {\n\tvar ws models.Workstation\n\tquery := r.db.WithContext(ctx).Where(\"status != ?\", \"locked\")\n\n\tvar conditions []string\n\tvar values []interface{}\n\n\tif tv != \"\" && tv != \"None\" {\n\t\tconditions = append(conditions, \"teamviewer = ?\")\n\t\tvalues = append(values, tv)\n\t}\n\tif ad != \"\" && ad != \"None\" {\n\t\tconditions = append(conditions, \"anydesk = ?\")\n\t\tvalues = append(values, ad)\n\t}\n\tif lm != \"\" && lm != \"None\" {\n\t\tconditions = append(conditions, \"litemanager = ?\")\n\t\tvalues = append(values, lm)\n\t}\n\n\tif len(conditions) == 0 {\n\t\treturn nil, nil\n\t}\n\n\tquery = query.Where(strings.Join(conditions, \" OR \"), values...)\n\n\terr := query.Order(\"updated_at DESC\").First(&ws).Error\n\tif err == gorm.ErrRecordNotFound {\n\t\treturn nil, nil\n\t}\n\treturn &ws, err\n}\n\n// FindByOwnerIDs находит все рабочие станции, принадлежащие указанным владельцам.\nfunc (r *workstationRepo) FindByOwnerIDs(ctx context.Context, ownerIDs []string) ([]models.Workstation, error) {\n\tif len(ownerIDs) == 0 {\n\t\treturn nil, nil\n\t}\n\tvar workstations []models.Workstation\n\terr := r.db.WithContext(ctx).Where(\"owner_id IN ?\", ownerIDs).Find(&workstations).Error\n\treturn workstations, err\n}\n",
    "internal/seeder/mock_client.go": "// internal/seeder/mock_client.go\npackage seeder\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/internal/validators\"\n\t\"fmt\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"regexp\"\n\t\"strings\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/datatypes\"\n)\n\n// MockServiceDeskClient имитирует клиент ServiceDesk для чтения данных из локальных файлов.\ntype MockServiceDeskClient struct {\n\tlogger   *zap.Logger\n\tdataPath string\n\tmapper   external.Mapper\n}\n\n// NewMockServiceDeskClient создает новый мок-клиент.\nfunc NewMockServiceDeskClient(logger *zap.Logger, dataPath string) external.ExternalSystemClient {\n\treturn &MockServiceDeskClient{\n\t\tlogger:   logger,\n\t\tdataPath: dataPath,\n\t\tmapper:   newMockMapper(logger),\n\t}\n}\n\nfunc (m *MockServiceDeskClient) Mapper() external.Mapper {\n\treturn m.mapper\n}\n\nfunc (m *MockServiceDeskClient) FetchEntityList(ctx context.Context, entityType string) ([]map[string]interface{}, error) {\n\tvar fileName string\n\tswitch entityType {\n\tcase \"Company\":\n\t\tfileName = \"companies.json\"\n\tcase \"Server\":\n\t\tfileName = \"servers.json\"\n\tcase \"Workstation\":\n\t\tfileName = \"workstations.json\"\n\tcase \"FiscalRegister\":\n\t\tfileName = \"fiscal_registers.json\"\n\tcase \"Contract\":\n\t\tfileName = \"agreements.json\"\n\tdefault:\n\t\treturn nil, fmt.Errorf(\"неизвестный entityType для мок-клиента: %s\", entityType)\n\t}\n\tfullPath := filepath.Join(m.dataPath, fileName)\n\tfile, err := os.ReadFile(fullPath)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tvar responseList []map[string]interface{}\n\tif err := json.Unmarshal(file, &responseList); err != nil {\n\t\treturn nil, err\n\t}\n\treturn responseList, nil\n}\n\n// --- Заглушки для методов интерфейса, не используемых в сидере ---\nfunc (m *MockServiceDeskClient) FetchEntitySummaries(ctx context.Context, entityType string) ([]map[string]interface{}, error) {\n\treturn m.FetchEntityList(ctx, entityType)\n}\nfunc (m *MockServiceDeskClient) FetchEntityDetails(ctx context.Context, externalID string, entityType string) (map[string]interface{}, error) {\n\treturn nil, nil\n}\nfunc (m *MockServiceDeskClient) FetchCompanyContractStates(ctx context.Context) (map[string]external.ContractState, error) {\n\treturn nil, nil\n}\nfunc (m *MockServiceDeskClient) UpdateEntity(ctx context.Context, externalID string, entityType string, data map[string]interface{}) error {\n\treturn nil\n}\nfunc (m *MockServiceDeskClient) CreateEntity(ctx context.Context, entityType string, data map[string]interface{}) (map[string]interface{}, error) {\n\treturn nil, nil\n}\nfunc (m *MockServiceDeskClient) FindReferenceID(ctx context.Context, referenceType, title string, useSubstringSearch bool) (string, error) {\n\treturn \"\", nil\n}\n\n// --- Мок-реализация маппера специально для сидера ---\ntype mockMapper struct {\n\tlogger *zap.Logger\n}\n\nfunc newMockMapper(logger *zap.Logger) external.Mapper { return &mockMapper{logger: logger} }\n\nvar innRegex = regexp.MustCompile(`ИНН:\\s*(\\d{10,12})`)\n\nfunc getOwnerUUID(data map[string]interface{}) string {\n\tif owner, ok := data[\"owner\"].(map[string]interface{}); ok {\n\t\tif oUUID, oOk := owner[\"UUID\"].(string); oOk {\n\t\t\treturn oUUID\n\t\t}\n\t}\n\treturn \"\"\n}\n\nfunc (m *mockMapper) DataToCompany(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Company, error) {\n\tcompany := &models.Company{}\n\tcompany.MetaClass = \"ou$company\"\n\tif title, ok := data[\"title\"].(string); ok {\n\t\tcompany.Title = &title\n\t}\n\tif address, ok := data[\"adress\"].(string); ok {\n\t\tcompany.Address = &address\n\t}\n\tif addName, ok := data[\"additionalName\"].(string); ok {\n\t\tcompany.AdditionalName = &addName\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tcompany.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\tif parent, ok := data[\"parent\"].(map[string]interface{}); ok {\n\t\tif parentUUID, p_ok := parent[\"UUID\"].(string); p_ok {\n\t\t\tcompany.MetaClass = parentUUID\n\t\t}\n\t}\n\treturn company, nil\n}\n\nfunc (m *mockMapper) DataToServer(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Server, error) {\n\tserver := &models.Server{}\n\tserver.MetaClass = \"objectBase$Server\"\n\townerExtID := getOwnerUUID(data)\n\tserver.OwnerID = &ownerExtID\n\trawUniqueID, _ := data[\"UniqueID\"].(string)\n\tserver.UniqueID = validators.ValidateUniqueID(rawUniqueID)\n\trawTeamviewer, _ := data[\"Teamviewer\"].(string)\n\tserver.Teamviewer = validators.ValidateRemoteAccessID(rawTeamviewer)\n\trawAnydesk, _ := data[\"AnyDesk\"].(string)\n\tserver.Anydesk = validators.ValidateRemoteAccessID(rawAnydesk)\n\trawIP, _ := data[\"IP\"].(string)\n\tserver.IP = validators.ValidateIPAddress(rawIP)\n\tif rawRDP, ok := data[\"RDP\"].(string); ok && rawRDP != \"\" {\n\t\tserver.RDP = &rawRDP\n\t}\n\tif rawDeviceName, ok := data[\"DeviceName\"].(string); ok && rawDeviceName != \"\" {\n\t\tserver.DeviceName = &rawDeviceName\n\t}\n\tif rawIikoVersion, ok := data[\"iikoVersion\"].(string); ok && rawIikoVersion != \"\" {\n\t\tserver.ServerVersion = &rawIikoVersion\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tserver.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\treturn server, nil\n}\n\nfunc (m *mockMapper) DataToWorkstation(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Workstation, error) {\n\tws := &models.Workstation{}\n\tws.MetaClass = \"objectBase$Workstation\"\n\townerExtID := getOwnerUUID(data)\n\tws.OwnerID = &ownerExtID\n\tif tv, ok := data[\"Teamviewer\"].(string); ok {\n\t\tws.Teamviewer = validators.ValidateRemoteAccessID(tv)\n\t}\n\tif ad, ok := data[\"AnyDesk\"].(string); ok {\n\t\tws.Anydesk = validators.ValidateRemoteAccessID(ad)\n\t}\n\tif dn, ok := data[\"DeviceName\"].(string); ok {\n\t\tws.DeviceName = &dn\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tws.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\treturn ws, nil\n}\n\nfunc (m *mockMapper) DataToFiscalRegister(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.FiscalRegister, error) {\n\tfr := &models.FiscalRegister{}\n\tfr.MetaClass = \"objectBase$FR\"\n\townerExtID := getOwnerUUID(data)\n\tfr.OwnerID = &ownerExtID\n\tif val, ok := data[\"ModelKKT\"].(map[string]interface{}); ok {\n\t\tif title, ok2 := val[\"title\"].(string); ok2 {\n\t\t\tfr.ModelKKT = &title\n\t\t}\n\t} else if val, ok := data[\"ModelKKT\"].(string); ok {\n\t\tfr.ModelKKT = &val\n\t}\n\tif val, ok := data[\"RNKKT\"].(string); ok {\n\t\tnormalizedRNKKT := utils.NormalizeRNKKT(val)\n\t\tfr.RNKKT = &normalizedRNKKT\n\t}\n\tif val, ok := data[\"LegalName\"].(string); ok {\n\t\tif matches := innRegex.FindStringSubmatch(val); len(matches) > 1 {\n\t\t\tinn := matches[1]\n\t\t\tfr.INN = &inn\n\t\t\tcleanName := strings.TrimSpace(innRegex.ReplaceAllString(val, \"\"))\n\t\t\tfr.LegalName = &cleanName\n\t\t} else {\n\t\t\tfr.LegalName = &val\n\t\t}\n\t}\n\tif val, ok := data[\"FRSerialNumber\"].(string); ok {\n\t\tfr.FRSerialNumber = &val\n\t}\n\tif val, ok := data[\"FNNumber\"].(string); ok {\n\t\tfr.FNNumber = &val\n\t}\n\tif val, ok := data[\"KKTRegDate\"].(string); ok {\n\t\tfr.KKTRegDate = utils.ParseServiceDeskTime(val)\n\t}\n\tif val, ok := data[\"FNExpireDate\"].(string); ok {\n\t\tfr.FNExpireDate = utils.ParseServiceDeskTime(val)\n\t}\n\tif val, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tfr.LastModifiedDate = utils.ParseServiceDeskTime(val)\n\t}\n\treturn fr, nil\n}\n\nfunc (m *mockMapper) DataToContract(ctx context.Context, mc *external.MapperContext, data map[string]interface{}) (*models.Contract, error) {\n\tcontract := &models.Contract{}\n\tcontract.MetaClass = \"agreement$agreement\"\n\tif state, ok := data[\"state\"].(string); ok {\n\t\tcontract.State = &state\n\t}\n\tif lmd, ok := data[\"lastModifiedDate\"].(string); ok {\n\t\tcontract.LastModifiedDate = utils.ParseServiceDeskTime(lmd)\n\t}\n\tif sst, ok := data[\"stateStartTime\"].(string); ok {\n\t\tcontract.StateStartTime = utils.ParseServiceDeskTime(sst)\n\t}\n\tvar serviceTitles []string\n\tif services, ok := data[\"services\"].([]interface{}); ok {\n\t\tfor _, item := range services {\n\t\t\tif m, _ := item.(map[string]interface{}); m != nil {\n\t\t\t\tif t, _ := m[\"title\"].(string); t != \"\" {\n\t\t\t\t\tserviceTitles = append(serviceTitles, t)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif j, err := json.Marshal(serviceTitles); err == nil {\n\t\t\tcontract.Services = datatypes.JSON(j)\n\t\t}\n\t}\n\tcontract.ServiceLevel = m.determineServiceLevel(serviceTitles)\n\tif recipients, ok := data[\"recipientsOU\"].([]interface{}); ok {\n\t\tvar recipientUUIDs []string\n\t\tfor _, item := range recipients {\n\t\t\tif m, _ := item.(map[string]interface{}); m != nil {\n\t\t\t\tif u, _ := m[\"UUID\"].(string); u != \"\" {\n\t\t\t\t\trecipientUUIDs = append(recipientUUIDs, u)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif j, err := json.Marshal(recipientUUIDs); err == nil {\n\t\t\tcontract.Recipients = datatypes.JSON(j)\n\t\t}\n\t}\n\treturn contract, nil\n}\n\nfunc (m *mockMapper) determineServiceLevel(serviceTitles []string) int { return -1 }\n\nfunc (m *mockMapper) GetCompanyUUIDsFromContract(data map[string]interface{}) []string {\n\tvar uuids []string\n\tif recipients, ok := data[\"recipientsOU\"].([]interface{}); ok {\n\t\tfor _, r := range recipients {\n\t\t\tif rMap, rOk := r.(map[string]interface{}); rOk {\n\t\t\t\tif uuid, uuidOk := rMap[\"UUID\"].(string); uuidOk {\n\t\t\t\t\tuuids = append(uuids, uuid)\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\treturn uuids\n}\n",
    "internal/seeder/seeder.go": "// internal/seeder/seeder.go\npackage seeder\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"fmt\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\nconst batchSize = 100\n\ntype Seeder struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n\tcontractRepo    repositories.ContractRepo\n}\n\nfunc NewSeeder(\n\tlogger *zap.Logger, db *gorm.DB, companyRepo repositories.CompanyRepo,\n\tserverRepo repositories.ServerRepo, workstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo, contractRepo repositories.ContractRepo,\n) *Seeder {\n\treturn &Seeder{\n\t\tlogger, db, companyRepo, serverRepo, workstationRepo, frRepo, contractRepo,\n\t}\n}\n\nfunc (s *Seeder) SeedDatabase(sdClient external.ExternalSystemClient) error {\n\ts.logger.Info(\"Начало процесса наполнения базы данных...\")\n\n\tif err := s.clearDatabase(); err != nil {\n\t\treturn err\n\t}\n\n\tctx := context.Background()\n\tmapperCtx := &external.MapperContext{Logger: s.logger}\n\n\tcompanyData, err := sdClient.FetchEntityList(ctx, \"Company\")\n\tif err != nil {\n\t\treturn err\n\t}\n\tserverData, err := sdClient.FetchEntityList(ctx, \"Server\")\n\tif err != nil {\n\t\treturn err\n\t}\n\twsData, err := sdClient.FetchEntityList(ctx, \"Workstation\")\n\tif err != nil {\n\t\treturn err\n\t}\n\tfrData, err := sdClient.FetchEntityList(ctx, \"FiscalRegister\")\n\tif err != nil {\n\t\treturn err\n\t}\n\tcontractData, err := sdClient.FetchEntityList(ctx, \"Contract\")\n\tif err != nil {\n\t\treturn err\n\t}\n\n\textToIntID := make(map[string]string)\n\n\treturn s.db.Transaction(func(tx *gorm.DB) error {\n\t\ts.logger.Info(\"Создание Компаний...\")\n\t\tfor _, data := range companyData {\n\t\t\textID, _ := data[\"UUID\"].(string)\n\t\t\tif extID == \"\" {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tcompany, _ := sdClient.Mapper().DataToCompany(ctx, mapperCtx, data)\n\t\t\tif err := tx.Create(company).Error; err != nil {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\textToIntID[extID] = company.ID\n\t\t\ttx.Create(&models.ExternalSystemLink{InternalID: company.ID, SystemName: \"naumen\", ExternalID: extID, EntityType: \"Company\", LastSyncedAt: time.Now()})\n\t\t}\n\n\t\ts.logger.Info(\"Установка родительских связей для Компаний...\")\n\t\tfor _, data := range companyData {\n\t\t\textID, _ := data[\"UUID\"].(string)\n\t\t\tcompanyModel, _ := sdClient.Mapper().DataToCompany(ctx, mapperCtx, data)\n\t\t\tparentExtID := companyModel.MetaClass // Используем MetaClass как временное хранилище\n\t\t\tif parentExtID != \"ou$company\" {      // Проверяем, что ID родителя был установлен\n\t\t\t\tchildIntID := extToIntID[extID]\n\t\t\t\tparentIntID := extToIntID[parentExtID]\n\t\t\t\tif childIntID != \"\" && parentIntID != \"\" {\n\t\t\t\t\ttx.Model(&models.Company{}).Where(\"id = ?\", childIntID).Update(\"parent_id\", parentIntID)\n\t\t\t\t}\n\t\t\t}\n\t\t\t// Возвращаем правильный MetaClass\n\t\t\ttx.Model(&models.Company{}).Where(\"id = ?\", extToIntID[extID]).Update(\"meta_class\", \"ou$company\")\n\t\t}\n\n\t\ts.logger.Info(\"Создание Оборудования...\")\n\t\tfor _, data := range serverData {\n\t\t\tserver, _ := sdClient.Mapper().DataToServer(ctx, mapperCtx, data)\n\t\t\tif server.OwnerID != nil && *server.OwnerID != \"\" {\n\t\t\t\townerIntID := extToIntID[*server.OwnerID]\n\t\t\t\tserver.OwnerID = &ownerIntID\n\t\t\t} else {\n\t\t\t\tserver.OwnerID = nil\n\t\t\t}\n\t\t\ttx.Create(server)\n\t\t}\n\t\tfor _, data := range wsData {\n\t\t\tws, _ := sdClient.Mapper().DataToWorkstation(ctx, mapperCtx, data)\n\t\t\tif ws.OwnerID != nil && *ws.OwnerID != \"\" {\n\t\t\t\townerIntID := extToIntID[*ws.OwnerID]\n\t\t\t\tws.OwnerID = &ownerIntID\n\t\t\t} else {\n\t\t\t\tws.OwnerID = nil\n\t\t\t}\n\t\t\ttx.Create(ws)\n\t\t}\n\t\tfor _, data := range frData {\n\t\t\tfr, _ := sdClient.Mapper().DataToFiscalRegister(ctx, mapperCtx, data)\n\t\t\tif fr.OwnerID != nil && *fr.OwnerID != \"\" {\n\t\t\t\townerIntID := extToIntID[*fr.OwnerID]\n\t\t\t\tfr.OwnerID = &ownerIntID\n\t\t\t} else {\n\t\t\t\tfr.OwnerID = nil\n\t\t\t}\n\t\t\ttx.Create(fr)\n\t\t}\n\n\t\ts.logger.Info(\"Создание Контрактов и связей...\")\n\t\tvar linksToCreate []models.CompanyContract\n\t\tfor _, data := range contractData {\n\t\t\textID, _ := data[\"UUID\"].(string)\n\t\t\tcontract, _ := sdClient.Mapper().DataToContract(ctx, mapperCtx, data)\n\t\t\ttx.Create(contract)\n\t\t\textToIntID[extID] = contract.ID\n\n\t\t\tcompanyExtIDs := sdClient.Mapper().GetCompanyUUIDsFromContract(data)\n\t\t\tfor _, compExtID := range companyExtIDs {\n\t\t\t\tif compIntID, ok := extToIntID[compExtID]; ok {\n\t\t\t\t\tlinksToCreate = append(linksToCreate, models.CompanyContract{CompanyID: compIntID, ContractID: contract.ID})\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif len(linksToCreate) > 0 {\n\t\t\ttx.Table(\"company_contracts\").CreateInBatches(linksToCreate, batchSize)\n\t\t}\n\n\t\ts.logger.Info(\"Пересчет статусов контрактов...\")\n\t\tactiveCompanyExtIDs := make(map[string]struct{})\n\t\tfor _, data := range contractData {\n\t\t\tif state, _ := data[\"state\"].(string); state == \"active\" {\n\t\t\t\tfor _, compExtID := range sdClient.Mapper().GetCompanyUUIDsFromContract(data) {\n\t\t\t\t\tactiveCompanyExtIDs[compExtID] = struct{}{}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\tvar activeCompanyIntIDs []string\n\t\tfor extID := range activeCompanyExtIDs {\n\t\t\tif intID, ok := extToIntID[extID]; ok {\n\t\t\t\tactiveCompanyIntIDs = append(activeCompanyIntIDs, intID)\n\t\t\t}\n\t\t}\n\n\t\ttx.Model(&models.Company{}).Where(\"id IN ?\", activeCompanyIntIDs).Update(\"active_contract\", true)\n\t\ttx.Model(&models.Company{}).Where(\"id NOT IN ?\", activeCompanyIntIDs).Update(\"active_contract\", false)\n\n\t\treturn nil\n\t})\n}\n\nfunc (s *Seeder) clearDatabase() error {\n\ttables := []string{\n\t\t\"server_additional_owners\", \"company_contracts\", \"external_system_links\",\n\t\t\"reconciliation_tasks\", \"agent_files\", \"fiscal_registers\", \"workstations\",\n\t\t\"servers\", \"contracts\", \"companies\", \"users\",\n\t}\n\tfor _, table := range tables {\n\t\tif err := s.db.Exec(fmt.Sprintf(\"DROP TABLE IF EXISTS %s CASCADE\", table)).Error; err != nil {\n\t\t\treturn fmt.Errorf(\"ошибка при удалении таблицы %s: %w\", table, err)\n\t\t}\n\t}\n\treturn nil\n}\n",
    "internal/services/agent_service.go": "package services\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\nvar (\n\tErrAgentNotFound      = errors.New(\"агент не найден\")\n\tErrAgentAlreadyExists = errors.New(\"агент с таким UUID уже существует\")\n\tErrOwnerNotDetermined = errors.New(\"не удалось определить владельца для агента\")\n)\n\n// AgentService определяет интерфейс для бизнес-логики управления агентами.\ntype AgentService interface {\n\tRegisterAgent(ctx context.Context, req *api.RegistrationRequestDTO) (*models.Agent, error)\n\tProcessData(ctx context.Context, agentUUID string, data *api.AgentDataDTO) error\n\tGetAgentConfig(ctx context.Context, uuid string) (*api.AgentConfigDTO, error)\n}\n\ntype agentServiceImpl struct {\n\tlogger      *zap.Logger\n\tagentRepo   repositories.AgentRepo\n\tcompanyRepo repositories.CompanyRepo\n\tdb          *gorm.DB\n\tbus         eventbus.EventBus\n}\n\n// NewAgentService создает новый экземпляр сервиса агентов.\nfunc NewAgentService(logger *zap.Logger, agentRepo repositories.AgentRepo, companyRepo repositories.CompanyRepo, db *gorm.DB, bus eventbus.EventBus) AgentService {\n\treturn &agentServiceImpl{\n\t\tlogger:      logger,\n\t\tagentRepo:   agentRepo,\n\t\tcompanyRepo: companyRepo,\n\t\tdb:          db,\n\t\tbus:         bus,\n\t}\n}\n\n// RegisterAgent обрабатывает запрос на регистрацию нового агента.\nfunc (s *agentServiceImpl) RegisterAgent(ctx context.Context, req *api.RegistrationRequestDTO) (*models.Agent, error) {\n\texistingAgent, err := s.agentRepo.GetByUUID(ctx, req.AgentUUID)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"ошибка проверки существования агента: %w\", err)\n\t}\n\tif existingAgent != nil {\n\t\treturn nil, ErrAgentAlreadyExists\n\t}\n\n\t// Создаем \"пустого\" агента в статусе ожидания.\n\tagent := &models.Agent{\n\t\tUUID:          req.AgentUUID,\n\t\tHostname:      req.Hostname,\n\t\tVersion:       req.AgentVersion,\n\t\tLastHeartbeat: time.Now(),\n\t\tType:          \"workstation\",\n\t\tStatus:        models.StatusPendingOwner,\n\t}\n\n\tif err := s.agentRepo.Create(ctx, agent); err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось создать агента в БД: %w\", err)\n\t}\n\n\tpayload := events.AgentDataPayload{\n\t\tSource: req.AgentUUID,\n\t\tData:   req.InitialData,\n\t}\n\n\t// Публикуем событие для Оркестратора, чтобы он запустил логику сверки и определения владельца.\n\ts.bus.Publish(eventbus.Event{\n\t\tType:    events.AgentDataReceived,\n\t\tPayload: payload,\n\t})\n\ts.logger.Info(\"Новый агент зарегистрирован, событие на обработку данных отправлено\", zap.String(\"uuid\", req.AgentUUID))\n\n\treturn agent, nil\n}\n\n// ProcessData обрабатывает данные от уже зарегистрированного агента.\nfunc (s *agentServiceImpl) ProcessData(ctx context.Context, agentUUID string, data *api.AgentDataDTO) error {\n\tagent, err := s.agentRepo.GetByUUID(ctx, agentUUID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения агента: %w\", err)\n\t}\n\tif agent == nil {\n\t\treturn ErrAgentNotFound\n\t}\n\n\tagent.LastHeartbeat = time.Now()\n\tif data.AgentVersion != \"\" {\n\t\tagent.Version = data.AgentVersion\n\t}\n\tif err := s.agentRepo.Update(ctx, agent); err != nil {\n\t\ts.logger.Error(\"Не удалось обновить heartbeat агента\", zap.String(\"uuid\", agentUUID), zap.Error(err))\n\t}\n\n\tpayload := events.AgentDataPayload{\n\t\tSource: agentUUID,\n\t\tData:   *data,\n\t}\n\t// Просто публикуем событие, вся логика сверки  выполняeтся в Оркестраторе.\n\ts.bus.Publish(eventbus.Event{\n\t\tType:    events.AgentDataReceived,\n\t\tPayload: payload,\n\t})\n\ts.logger.Info(\"Данные от агента получены, событие на обработку отправлено\", zap.String(\"uuid\", agentUUID))\n\n\treturn nil\n}\n\n// GetAgentConfig возвращает конфигурацию для агента, если он активен.\nfunc (s *agentServiceImpl) GetAgentConfig(ctx context.Context, uuid string) (*api.AgentConfigDTO, error) {\n\tagent, err := s.agentRepo.GetByUUID(ctx, uuid)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"ошибка получения агента: %w\", err)\n\t}\n\tif agent == nil || agent.Status != models.StatusActive {\n\t\t// Если агент не найден или его регистрация не завершена, возвращаем ошибку\n\t\treturn nil, ErrAgentNotFound\n\t}\n\n\t// Распарсим JSON из БД в DTO\n\tvar configDTO api.AgentConfigDTO\n\tif agent.Config != nil {\n\t\tif err := json.Unmarshal(agent.Config, &configDTO); err != nil {\n\t\t\treturn nil, fmt.Errorf(\"не удалось распарсить конфигурацию агента из БД: %w\", err)\n\t\t}\n\t} else {\n\t\t// Этого быть не должно, если статус active, но на всякий случай\n\t\treturn nil, errors.New(\"у активного агента отсутствует конфигурация\")\n\t}\n\n\treturn &configDTO, nil\n}\n\n// // createTaskForUndefinedOwner создает задачу для администратора.\n// func (s *agentServiceImpl) createTaskForUndefinedOwner(ctx context.Context, req *api.RegistrationRequestDTO) error {\n// \tdetails, _ := json.Marshal(req)\n// \ttask := models.ReconciliationTask{\n// \t\tTaskType:   \"agent_owner_required\",\n// \t\tEntityType: \"Agent\",\n// \t\tEntityUUID: req.AgentUUID,\n// \t\tDetails:    datatypes.JSON(details),\n// \t\tStatus:     \"new\",\n// \t\tComment:    fmt.Sprintf(\"Требуется вручную определить и привязать владельца для нового агента с хостом %s.\", req.Hostname),\n// \t}\n// \treturn s.db.WithContext(ctx).Create(&task).Error\n// }\n\n// // generateZabbixHostname создает имя хоста по формату {$COMPANY_NAME_ENG_SHORT}-{$DeviceNameFromSD}-{$INNER_COMPANY_ID}\n// func (s *agentServiceImpl) generateZabbixHostname(ctx context.Context, ownerUUID, agentHostname string) (string, error) {\n// \tcompany, err := s.companyRepo.GetByUUID(ctx, ownerUUID)\n// \tif err != nil || company == nil {\n// \t\treturn \"\", fmt.Errorf(\"не удалось найти компанию-владельца по UUID %s\", ownerUUID)\n// \t}\n\n// \t// 1. $COMPANY_NAME_ENG_SHORT\n// \tcompanyShortName := s.transliterate(*company.Title)\n\n// \t// 2. $DeviceNameFromSD\n// \t// На этапе регистрации у нас еще нет точной привязки к Workstation, используем hostname агента\n// \tdeviceName := agentHostname\n// \tif govalidator.IsDNSName(deviceName) {\n// \t\tdeviceName = strings.Split(deviceName, \".\")[0]\n// \t}\n// \tdeviceName = strings.ToUpper(deviceName)\n\n// \t// 3. $INNER_COMPANY_ID\n// \tcount, err := s.agentRepo.CountByOwnerUUID(ctx, ownerUUID)\n// \tif err != nil {\n// \t\treturn \"\", fmt.Errorf(\"не удалось посчитать агентов для компании %s: %w\", ownerUUID, err)\n// \t}\n// \tinnerID := fmt.Sprintf(\"%02d\", count+1) // +1, так как текущий агент еще не сохранен\n\n// \treturn fmt.Sprintf(\"%s-%s-%s\", companyShortName, deviceName, innerID), nil\n// }\n\n// // transliterate преобразует кириллический текст в латиницу.\n// func (s *agentServiceImpl) transliterate(text string) string {\n// \t// Простая транслитерация\n// \tt := transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)\n// \tresult, _, _ := transform.String(t, text)\n// \tresult = strings.ToLower(result)\n\n// \t// Заменяем специфичные русские буквы и символы\n// \tvar replacements = map[string]string{\n// \t\t\" \": \"-\", \"ъ\": \"\", \"ь\": \"\", \"ы\": \"y\", \"і\": \"i\", \"ї\": \"i\", \"є\": \"e\",\n// \t\t\"а\": \"a\", \"б\": \"b\", \"в\": \"v\", \"г\": \"g\", \"д\": \"d\", \"е\": \"e\", \"ё\": \"e\",\n// \t\t\"ж\": \"zh\", \"з\": \"z\", \"и\": \"i\", \"й\": \"y\", \"к\": \"k\", \"л\": \"l\", \"м\": \"m\",\n// \t\t\"н\": \"n\", \"о\": \"o\", \"п\": \"p\", \"р\": \"r\", \"с\": \"s\", \"т\": \"t\", \"у\": \"u\",\n// \t\t\"ф\": \"f\", \"х\": \"h\", \"ц\": \"c\", \"ч\": \"ch\", \"ш\": \"sh\", \"щ\": \"sch\",\n// \t\t\"ю\": \"yu\", \"я\": \"ya\",\n// \t}\n\n// \tfor rus, lat := range replacements {\n// \t\tresult = strings.ReplaceAll(result, rus, lat)\n// \t}\n\n// \t// Удаляем все неалфавитно-цифровые символы, кроме дефиса\n// \treg, err := regexp.Compile(\"[^a-z0-9-]+\")\n// \tif err != nil {\n// \t\ts.logger.Error(\"Ошибка компиляции regex для транслитерации\", zap.Error(err))\n// \t\treturn \"unknown\"\n// \t}\n// \treturn reg.ReplaceAllString(result, \"\")\n// }\n",
    "internal/services/auth_service.go": "package services\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/repositories\"\n\t\"fmt\"\n\t\"time\"\n\n\t\"github.com/golang-jwt/jwt/v5\"\n)\n\nvar ErrInvalidCredentials = errors.New(\"неверное имя пользователя или пароль\")\n\n// AuthService определяет интерфейс для сервиса аутентификации.\ntype AuthService interface {\n\tLogin(ctx context.Context, username, password string) (*api.LoginResponseDTO, error)\n}\n\ntype authServiceImpl struct {\n\tcfg      *config.Config\n\tuserRepo repositories.UserRepo\n}\n\nfunc NewAuthService(cfg *config.Config, userRepo repositories.UserRepo) AuthService {\n\treturn &authServiceImpl{cfg, userRepo}\n}\n\n// Login проверяет учетные данные и генерирует JWT.\nfunc (s *authServiceImpl) Login(ctx context.Context, username, password string) (*api.LoginResponseDTO, error) {\n\tuser, err := s.userRepo.GetByUsername(ctx, username)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"ошибка получения пользователя: %w\", err)\n\t}\n\tif user == nil || !user.CheckPassword(password) {\n\t\treturn nil, ErrInvalidCredentials\n\t}\n\n\t// Генерация токена\n\texpirationTime := time.Now().Add(time.Duration(s.cfg.JWTExpirationMin) * time.Minute)\n\tvar roles []string\n\t_ = json.Unmarshal(user.Roles, &roles)\n\n\tclaims := &jwt.RegisteredClaims{\n\t\tSubject:   fmt.Sprint(user.ID),\n\t\tExpiresAt: jwt.NewNumericDate(expirationTime),\n\t\tIssuedAt:  jwt.NewNumericDate(time.Now()),\n\t}\n\n\t// Добавляем кастомные поля\n\ttokenClaims := jwt.MapClaims{\n\t\t\"sub\":   claims.Subject,\n\t\t\"exp\":   claims.ExpiresAt.Unix(),\n\t\t\"iat\":   claims.IssuedAt.Unix(),\n\t\t\"roles\": roles,\n\t}\n\n\ttoken := jwt.NewWithClaims(jwt.SigningMethodHS256, tokenClaims)\n\ttokenString, err := token.SignedString([]byte(s.cfg.JWTSecret))\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"ошибка генерации токена: %w\", err)\n\t}\n\n\tresponse := &api.LoginResponseDTO{\n\t\tAccessToken: tokenString,\n\t\tUser: api.UserDTO{\n\t\t\tID:       user.ID,\n\t\t\tUsername: user.Username,\n\t\t\tFullName: user.FullName,\n\t\t\tRoles:    roles,\n\t\t},\n\t}\n\n\treturn response, nil\n}\n",
    "internal/services/entity_matcher_service.go": "// internal/services/entity_matcher_service.go\npackage services\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/internal/validators\"\n\n\t\"go.uber.org/zap\"\n)\n\n// MatchedEntity результат работы EntityMatcherService.\ntype MatchedEntity struct {\n\tEntity     interface{} // Найденная сущность (*models.Server, *models.Workstation, etc.)\n\tEntityType string      // 'Server', 'Workstation', 'FiscalRegister'\n\tOwnerUUID  string      // Внутренний ID владельца\n}\n\n// EntityMatcherService определяет интерфейс для сервиса идентификации сущностей по данным от агента.\ntype EntityMatcherService interface {\n\tFindEntityByAgentData(ctx context.Context, data *api.AgentDataDTO) *MatchedEntity\n}\n\ntype entityMatcherServiceImpl struct {\n\tlogger          *zap.Logger\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n}\n\n// NewEntityMatcherService создает новый экземпляр сервиса.\nfunc NewEntityMatcherService(\n\tlogger *zap.Logger,\n\tserverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo,\n) EntityMatcherService {\n\treturn &entityMatcherServiceImpl{logger, serverRepo, workstationRepo, frRepo}\n}\n\n// FindEntityByAgentData выполняет \"водопадную\" логику поиска.\nfunc (s *entityMatcherServiceImpl) FindEntityByAgentData(ctx context.Context, data *api.AgentDataDTO) *MatchedEntity {\n\tlogIdentifier := data.SerialNumber\n\tif logIdentifier == \"\" {\n\t\tlogIdentifier = data.TeamviewerID\n\t}\n\tlog := s.logger.With(zap.String(\"log_identifier\", logIdentifier))\n\n\tnormalizedIP := validators.ValidateIPAddress(data.URLRms)\n\n\t// Приоритет 1: Поиск по Серверу\n\tif server, _ := s.serverRepo.FindByCRMidOrIP(ctx, data.CRMID, utils.SafeStringDereference(normalizedIP)); server != nil {\n\t\tlog.Info(\"Найдено совпадение по Серверу\", zap.String(\"internal_id\", server.ID))\n\t\treturn &MatchedEntity{\n\t\t\tEntity:     server,\n\t\t\tEntityType: \"Server\",\n\t\t\tOwnerUUID:  utils.SafeStringDereference(server.OwnerID),\n\t\t}\n\t}\n\n\t// Приоритет 2: Поиск по Рабочей станции\n\tif ws, _ := s.workstationRepo.FindByRemoteIDs(ctx, data.TeamviewerID, \"\", data.LitemanagerID); ws != nil {\n\t\tlog.Info(\"Найдено совпадение по Рабочей станции\", zap.String(\"internal_id\", ws.ID))\n\t\treturn &MatchedEntity{\n\t\t\tEntity:     ws,\n\t\t\tEntityType: \"Workstation\",\n\t\t\tOwnerUUID:  utils.SafeStringDereference(ws.OwnerID),\n\t\t}\n\t}\n\n\t// Приоритет 3: Поиск по Фискальному регистратору\n\tif fr, _ := s.frRepo.FindBySerialNumber(ctx, data.SerialNumber); fr != nil {\n\t\tlog.Info(\"Найдено совпадение по Фискальному регистратору\", zap.String(\"internal_id\", fr.ID))\n\t\treturn &MatchedEntity{\n\t\t\tEntity:     fr,\n\t\t\tEntityType: \"FiscalRegister\",\n\t\t\tOwnerUUID:  utils.SafeStringDereference(fr.OwnerID),\n\t\t}\n\t}\n\n\tlog.Warn(\"Не найдено совпадений ни по одному из приоритетов.\")\n\treturn nil\n}\n",
    "internal/services/ftp_client.go": "package services\n\nimport (\n\t\"bytes\"\n\t\"etalon-server/internal/config\"\n\t\"fmt\"\n\t\"io\"\n\t\"time\"\n\n\t\"github.com/jlaffaye/ftp\"\n\t\"go.uber.org/zap\"\n)\n\n// FTPClient определяет интерфейс для работы с FTP-сервером.\ntype FTPClient interface {\n\tListFiles(path string) ([]*ftp.Entry, error)\n\tDownloadFile(path string) ([]byte, error)\n}\n\ntype ftpClientImpl struct {\n\tcfg    *config.Config\n\tlogger *zap.Logger\n}\n\n// NewFTPClient создает новый клиент для FTP.\nfunc NewFTPClient(cfg *config.Config, logger *zap.Logger) FTPClient {\n\treturn &ftpClientImpl{\n\t\tcfg:    cfg,\n\t\tlogger: logger,\n\t}\n}\n\n// getConn устанавливает соединение с FTP сервером.\nfunc (f *ftpClientImpl) getConn() (*ftp.ServerConn, error) {\n\taddr := fmt.Sprintf(\"%s:%s\", f.cfg.FTPHost, f.cfg.FTPPort)\n\tc, err := ftp.Dial(addr, ftp.DialWithTimeout(15*time.Second))\n\tif err != nil {\n\t\tf.logger.Error(\"Не удалось подключиться к FTP\", zap.String(\"addr\", addr), zap.Error(err))\n\t\treturn nil, err\n\t}\n\n\terr = c.Login(f.cfg.FTPUser, f.cfg.FTPPassword)\n\tif err != nil {\n\t\tc.Quit()\n\t\tf.logger.Error(\"Не удалось авторизоваться на FTP\", zap.String(\"user\", f.cfg.FTPUser), zap.Error(err))\n\t\treturn nil, err\n\t}\n\n\treturn c, nil\n}\n\n// ListFiles получает список файлов и их атрибутов из указанной директории.\nfunc (f *ftpClientImpl) ListFiles(path string) ([]*ftp.Entry, error) {\n\tc, err := f.getConn()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tdefer c.Quit()\n\n\tentries, err := c.List(path)\n\tif err != nil {\n\t\tf.logger.Error(\"Не удалось получить список файлов с FTP\", zap.String(\"path\", path), zap.Error(err))\n\t\treturn nil, err\n\t}\n\n\treturn entries, nil\n}\n\n// DownloadFile скачивает файл с FTP и возвращает его содержимое в виде []byte.\nfunc (f *ftpClientImpl) DownloadFile(path string) ([]byte, error) {\n\tc, err := f.getConn()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tdefer c.Quit()\n\n\tr, err := c.Retr(path)\n\tif err != nil {\n\t\tf.logger.Error(\"Не удалось начать скачивание файла\", zap.String(\"path\", path), zap.Error(err))\n\t\treturn nil, err\n\t}\n\tdefer r.Close()\n\n\tbuf, err := io.ReadAll(r)\n\tif err != nil {\n\t\tf.logger.Error(\"Ошибка во время чтения скачиваемого файла\", zap.String(\"path\", path), zap.Error(err))\n\t\treturn nil, err\n\t}\n\n\t// Для отладки можно использовать bytes.NewReader(buf) если нужно будет передать io.Reader\n\t_ = bytes.NewReader(buf)\n\n\treturn buf, nil\n}\n",
    "internal/services/sd_editor_service.go": "// internal/services/sd_editor_service.go\npackage services\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"regexp\"\n\t\"strings\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\n// SDEditorService определяет интерфейс для сервиса, который асинхронно изменяет данные в ServiceDesk.\ntype SDEditorService interface {\n\tStart(ctx context.Context)\n}\n\n// sdEditorServiceImpl реализует интерфейс SDEditorService.\ntype sdEditorServiceImpl struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tbus             eventbus.EventBus\n\tsdClient        external.ExternalSystemClient\n\ttaskRepo        repositories.TaskRepo\n\tlinkRepo        repositories.LinkRepo // Новая зависимость\n\tcompanyRepo     repositories.CompanyRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n}\n\n// NewSDEditorService создает новый экземпляр воркера SDEditorService.\nfunc NewSDEditorService(\n\tlogger *zap.Logger,\n\tdb *gorm.DB,\n\tbus eventbus.EventBus,\n\tsdClient external.ExternalSystemClient,\n\ttaskRepo repositories.TaskRepo,\n\tlinkRepo repositories.LinkRepo, // Новая зависимость\n\tcompanyRepo repositories.CompanyRepo,\n\tserverRepo repositories.ServerRepo,\n\tworkstationRepo repositories.WorkstationRepo,\n\tfrRepo repositories.FiscalRegisterRepo,\n) SDEditorService {\n\treturn &sdEditorServiceImpl{\n\t\tlogger:          logger,\n\t\tdb:              db,\n\t\tbus:             bus,\n\t\tsdClient:        sdClient,\n\t\ttaskRepo:        taskRepo,\n\t\tlinkRepo:        linkRepo, // Инициализация\n\t\tcompanyRepo:     companyRepo,\n\t\tserverRepo:      serverRepo,\n\t\tworkstationRepo: workstationRepo,\n\t\tfrRepo:          frRepo,\n\t}\n}\n\n// Start запускает воркер и подписывает его на события.\nfunc (s *sdEditorServiceImpl) Start(ctx context.Context) {\n\ts.logger.Info(\"Запуск воркера SDEditorService\")\n\ts.bus.Subscribe(events.ServiceDeskCreateRequested, s.handleCreateRequest)\n\ts.bus.Subscribe(events.ServiceDeskUpdateRequested, s.handleUpdateRequest)\n}\n\n// handleUpdateRequest обрабатывает запрос на обновление сущности в ServiceDesk.\nfunc (s *sdEditorServiceImpl) handleUpdateRequest(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServiceDeskModificationPayload)\n\tif !ok {\n\t\treturn\n\t}\n\n\tlog := s.logger.With(zap.Uint(\"taskID\", payload.TaskID), zap.String(\"internalUUID\", payload.EntityUUID))\n\tlog.Info(\"Получен запрос на обновление сущности в ServiceDesk\")\n\n\t// 1. Находим внешний ID по внутреннему ID.\n\tlink, err := s.linkRepo.GetByInternalID(ctx, nil, \"naumen\", payload.EntityUUID)\n\tif err != nil || link == nil {\n\t\tmsg := fmt.Sprintf(\"Не найдена связь с ServiceDesk для сущности с внутренним ID %s\", payload.EntityUUID)\n\t\tlog.Error(msg, zap.Error(err))\n\t\ts.updateTaskStatus(ctx, payload.TaskID, \"sd_error\", msg)\n\t\treturn\n\t}\n\n\t// 2. Собираем payload для ServiceDesk на основе эталонных данных из нашей БД.\n\tpayloadForSD, err := s.buildUpdatePayload(ctx, payload.EntityType, payload.EntityUUID)\n\tif err != nil {\n\t\tlog.Error(\"Не удалось собрать payload для обновления\", zap.Error(err))\n\t\ts.updateTaskStatus(ctx, payload.TaskID, \"sd_error\", fmt.Sprintf(\"Ошибка сборки данных для SD: %v\", err))\n\t\treturn\n\t}\n\tlog.Info(\"Подготовлен payload для обновления сущности в ServiceDesk\", zap.Any(\"payload\", payloadForSD))\n\n\t// 3. Выполняем обновление, используя внешний ID.\n\terr = s.sdClient.UpdateEntity(ctx, link.ExternalID, payload.EntityType, payloadForSD)\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при обновлении сущности в ServiceDesk\", zap.Error(err), zap.Any(\"sent_payload\", payloadForSD))\n\t\ts.updateTaskStatus(ctx, payload.TaskID, \"sd_error\", fmt.Sprintf(\"Ошибка API ServiceDesk: %v\", err))\n\t\treturn\n\t}\n\n\t// 4. В случае успеха, обновляем статус задачи.\n\tlog.Info(\"Сущность в ServiceDesk успешно обновлена (или выполнен dry run)\")\n\ts.updateTaskStatus(ctx, payload.TaskID, \"resolved\", \"Сущность успешно обновлена в ServiceDesk.\")\n}\n\n// handleCreateRequest обрабатывает запрос на создание сущности в ServiceDesk.\nfunc (s *sdEditorServiceImpl) handleCreateRequest(ctx context.Context, event eventbus.Event) {\n\tpayload, ok := event.Payload.(events.ServiceDeskModificationPayload)\n\tif !ok {\n\t\treturn\n\t}\n\tlog := s.logger.With(zap.Uint(\"taskID\", payload.TaskID))\n\tlog.Info(\"Получен запрос на создание сущности в ServiceDesk\")\n\n\tvar newExternalUUID string\n\tvar err error\n\n\tswitch payload.EntityType {\n\tcase \"FiscalRegister\":\n\t\tnewExternalUUID, err = s.createFiscalRegisterFromTask(ctx, payload.TaskID)\n\tdefault:\n\t\terr = fmt.Errorf(\"создание сущности типа '%s' не поддерживается\", payload.EntityType)\n\t}\n\n\tif err != nil {\n\t\tlog.Error(\"Ошибка при создании сущности в ServiceDesk\", zap.Error(err))\n\t\ts.updateTaskStatus(ctx, payload.TaskID, \"sd_error\", fmt.Sprintf(\"Ошибка API ServiceDesk: %v\", err))\n\t\treturn\n\t}\n\n\t// После успешного создания в SD, нам нужно связать наш внутренний объект с новым внешним.\n\ttask, _ := s.taskRepo.GetByID(ctx, payload.TaskID)\n\tif task != nil {\n\t\t// EntityUUID в задаче типа add_equipment - это уникальный идентификатор оборудования (например, серийный номер).\n\t\t// Нам нужно найти внутренний объект по этому идентификатору.\n\t\tvar internalID string\n\t\tswitch task.EntityType {\n\t\tcase \"FiscalRegister\":\n\t\t\tfr, _ := s.frRepo.FindBySerialNumber(ctx, task.EntityUUID)\n\t\t\tif fr != nil {\n\t\t\t\tinternalID = fr.ID\n\t\t\t}\n\t\t}\n\n\t\tif internalID != \"\" {\n\t\t\tnewLink := models.ExternalSystemLink{\n\t\t\t\tInternalID: internalID, SystemName: \"naumen\", ExternalID: newExternalUUID,\n\t\t\t\tEntityType: task.EntityType, LastSyncedAt: time.Now(),\n\t\t\t}\n\t\t\tif err := s.linkRepo.Create(ctx, nil, &newLink); err != nil {\n\t\t\t\tlog.Error(\"Критическая ошибка: сущность в SD создана, но не удалось создать для нее связь в локальной БД\", zap.Error(err))\n\t\t\t\t// Статус задачи не меняем на resolved, чтобы оператор увидел проблему\n\t\t\t\ts.updateTaskStatus(ctx, payload.TaskID, \"sd_error\", fmt.Sprintf(\"Создано в SD (extUUID: %s), но не удалось создать связь в БД!\", newExternalUUID))\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}\n\n\tlog.Info(\"Сущность в ServiceDesk успешно создана и связана\", zap.String(\"newExternalUUID\", newExternalUUID))\n\ts.updateTaskStatus(ctx, payload.TaskID, \"resolved\", fmt.Sprintf(\"Сущность успешно создана в ServiceDesk с UUID: %s\", newExternalUUID))\n}\n\n// buildUpdatePayload формирует map[string]interface{} для обновления сущности в SD.\nfunc (s *sdEditorServiceImpl) buildUpdatePayload(ctx context.Context, entityType, internalID string) (map[string]interface{}, error) {\n\tpayload := make(map[string]interface{})\n\n\tswitch entityType {\n\tcase \"FiscalRegister\":\n\t\tfr, err := s.frRepo.GetByID(ctx, internalID)\n\t\tif err != nil || fr == nil {\n\t\t\treturn nil, fmt.Errorf(\"не удалось найти ФР с ID %s в локальной БД: %w\", internalID, err)\n\t\t}\n\t\tpayload[\"RNKKT\"] = utils.FormatRNKKT(utils.SafeStringDereference(fr.RNKKT))\n\t\tpayload[\"FNNumber\"] = utils.SafeStringDereference(fr.FNNumber)\n\t\tpayload[\"FRDownloader\"] = utils.SafeStringDereference(fr.FRDownloader)\n\n\t\tvar legalName string\n\t\tif fr.LegalName != nil && *fr.LegalName != \"\" {\n\t\t\tlegalName = *fr.LegalName\n\t\t\tif fr.INN != nil && *fr.INN != \"\" {\n\t\t\t\tlegalName = fmt.Sprintf(\"%s ИНН:%s\", *fr.LegalName, *fr.INN)\n\t\t\t}\n\t\t}\n\t\tpayload[\"LegalName\"] = legalName\n\n\t\tif fr.FNExpireDate != nil {\n\t\t\tpayload[\"FNExpireDate\"] = fr.FNExpireDate.Format(utils.TimeLayoutServiceDesk)\n\t\t}\n\t\tif fr.KKTRegDate != nil {\n\t\t\tpayload[\"KKTRegDate\"] = fr.KKTRegDate.Format(utils.TimeLayoutServiceDesk)\n\t\t}\n\n\t\tfor k, v := range payload {\n\t\t\tif strVal, ok := v.(string); ok && strVal == \"\" {\n\t\t\t\tdelete(payload, k)\n\t\t\t}\n\t\t}\n\n\tdefault:\n\t\treturn nil, fmt.Errorf(\"обновление для типа сущности '%s' не поддерживается\", entityType)\n\t}\n\n\treturn payload, nil\n}\n\n// createFiscalRegisterFromTask извлекает данные из задачи и создает ФР в ServiceDesk.\nfunc (s *sdEditorServiceImpl) createFiscalRegisterFromTask(ctx context.Context, taskID uint) (string, error) {\n\ttask, err := s.taskRepo.GetByID(ctx, taskID)\n\tif err != nil || task == nil {\n\t\treturn \"\", fmt.Errorf(\"ошибка получения задачи %d: %w\", taskID, err)\n\t}\n\n\tvar details struct {\n\t\tAgentData       api.AgentDataDTO `json:\"agent_data\"`\n\t\tEtalonOwnerUUID string           `json:\"etalon_owner_uuid\"` // Здесь все еще внешний ID владельца\n\t}\n\tif err := json.Unmarshal(task.Details, &details); err != nil {\n\t\treturn \"\", err\n\t}\n\n\tagentData := details.AgentData\n\tlog := s.logger.With(zap.Uint(\"taskID\", taskID))\n\tlog.Debug(\"Начало сборки payload для создания ФР\")\n\tpayload := make(map[string]interface{})\n\n\taddStringFieldToPayload(log, payload, \"owner\", details.EtalonOwnerUUID)\n\n\t// 1. Простые текстовые и временные поля\n\taddStringFieldToPayload(log, payload, \"RNKKT\", utils.FormatRNKKT(agentData.RNM))\n\taddStringFieldToPayload(log, payload, \"FRSerialNumber\", strings.TrimSpace(agentData.SerialNumber))\n\taddStringFieldToPayload(log, payload, \"FNNumber\", strings.TrimSpace(agentData.FNSerial))\n\n\tvar legalName string\n\tif agentData.OrganizationName != \"\" && agentData.INN != \"\" {\n\t\tlegalName = fmt.Sprintf(\"%s ИНН:%s\", strings.TrimSpace(agentData.OrganizationName), strings.TrimSpace(agentData.INN))\n\t} else {\n\t\tlegalName = strings.TrimSpace(agentData.OrganizationName)\n\t}\n\taddStringFieldToPayload(log, payload, \"LegalName\", legalName)\n\n\tif regDate := utils.ParseAgentTime(agentData.DateTimeReg); regDate != nil {\n\t\taddStringFieldToPayload(log, payload, \"KKTRegDate\", regDate.Format(utils.TimeLayoutServiceDesk))\n\t}\n\tif expDate := utils.ParseAgentTime(agentData.DateTimeEnd); expDate != nil {\n\t\taddStringFieldToPayload(log, payload, \"FNExpireDate\", expDate.Format(utils.TimeLayoutServiceDesk))\n\t}\n\n\t// 2. Новые поля для прошивки и загрузчика\n\taddStringFieldToPayload(log, payload, \"FRDownloader\", strings.TrimSpace(agentData.BootVersion))\n\tfrFirmwareValue := utils.CalculateFRFirmware(agentData.Licenses)\n\taddStringFieldToPayload(log, payload, \"FRFirmware\", frFirmwareValue)\n\n\t// 3. Поля, требующие поиска в справочниках ServiceDesk\n\tmodelName := strings.TrimSpace(agentData.ModelName)\n\tmodelUUID, err := s.sdClient.FindReferenceID(ctx, \"ModeliFR\", modelName, false)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось найти модель ККТ '%s': %w\", modelName, err)\n\t}\n\taddStringFieldToPayload(log, payload, \"ModelKKT\", modelUUID)\n\n\tffdVersion := utils.FormatFFDVersion(agentData.FFDVersion)\n\tffdUUID, err := s.sdClient.FindReferenceID(ctx, \"FFD\", ffdVersion, false)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось найти версию ФФД '%s': %w\", ffdVersion, err)\n\t}\n\taddStringFieldToPayload(log, payload, \"FFD\", ffdUUID)\n\n\tsrokMatches := srokFnRegex.FindStringSubmatch(agentData.FNExecution)\n\tif len(srokMatches) < 2 {\n\t\treturn \"\", fmt.Errorf(\"не удалось извлечь срок ФН из '%s'\", agentData.FNExecution)\n\t}\n\tsrokUUID, err := s.sdClient.FindReferenceID(ctx, \"SrokiFN\", srokMatches[1], true)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось найти срок ФН '%s': %w\", srokMatches[1], err)\n\t}\n\taddStringFieldToPayload(log, payload, \"SrokFN\", srokUUID)\n\n\t// 4. Владелец сущности\n\taddStringFieldToPayload(log, payload, \"owner\", details.EtalonOwnerUUID)\n\n\tlog.Info(\"Подготовлен итоговый payload для создания ФР в ServiceDesk\", zap.Any(\"payload\", payload))\n\n\t// 5. Вызов клиента для создания сущности\n\tresponse, err := s.sdClient.CreateEntity(ctx, \"FiscalRegister\", payload)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"ошибка создания ФР в ServiceDesk: %w\", err)\n\t}\n\n\tnewUUID, _ := response[\"UUID\"].(string)\n\treturn newUUID, nil\n}\n\n// updateTaskStatus обновляет статус и комментарий задачи. Выполняется в отдельной транзакции\n// для обеспечения атомарности и независимости от основного контекста операции.\nfunc (s *sdEditorServiceImpl) updateTaskStatus(ctx context.Context, taskID uint, newStatus, commentText string) {\n\terr := s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {\n\t\t// Используем .WithContext(ctx) внутри транзакции для передачи таймаутов, если они есть\n\t\ttask, err := s.taskRepo.GetByID(ctx, taskID)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif task == nil {\n\t\t\treturn fmt.Errorf(\"задача с ID %d не найдена для обновления статуса\", taskID)\n\t\t}\n\t\ttask.Status = newStatus\n\t\ttask.Comment = fmt.Sprintf(\"%s\\n[SD_WORKER] %s\", task.Comment, commentText)\n\t\treturn tx.Save(task).Error\n\t})\n\tif err != nil {\n\t\ts.logger.Error(\"Критическая ошибка: не удалось обновить статус задачи после операции с SD\",\n\t\t\tzap.Uint(\"taskID\", taskID),\n\t\t\tzap.String(\"newStatus\", newStatus),\n\t\t\tzap.Error(err),\n\t\t)\n\t}\n}\n\n// srokFnRegex - регулярное выражение для извлечения срока действия ФН (13, 15 или 36 месяцев).\nvar srokFnRegex = regexp.MustCompile(`(13|15|36)`)\n\n// addStringFieldToPayload - хелпер для логирования и добавления непустых строковых полей в payload.\nfunc addStringFieldToPayload(log *zap.Logger, payload map[string]interface{}, key, value string) {\n\tif value != \"\" {\n\t\tlog.Debug(\"Добавление поля в payload\", zap.String(\"поле\", key), zap.String(\"значение\", value))\n\t\tpayload[key] = value\n\t} else {\n\t\tlog.Debug(\"Пропуск пустого поля\", zap.String(\"поле\", key))\n\t}\n}\n",
    "internal/services/server_actions_service.go": "// internal/services/server_actions_service.go\npackage services\n\nimport (\n\t\"context\"\n\t\"errors\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\t\"sync\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\nvar (\n\t// ErrRateLimitExceeded возвращается, когда превышен лимит запросов на опрос для одного сервера.\n\tErrRateLimitExceeded = errors.New(\"слишком много запросов на опрос сервера\")\n)\n\nconst (\n\trateLimitCount  = 3\n\trateLimitWindow = 2 * time.Minute\n)\n\n// ServerActionsService определяет интерфейс для ручных действий над серверами.\ntype ServerActionsService interface {\n\tPollSingleServer(ctx context.Context, serverID string) error\n\tInstallLicense(ctx context.Context, serverID, uniqueID string) error\n\tAddAdditionalOwner(ctx context.Context, serverID, companyID string) error\n\tRemoveAdditionalOwner(ctx context.Context, serverID, companyID string) error\n}\n\ntype serverActionsServiceImpl struct {\n\tlogger        *zap.Logger\n\tbus           eventbus.EventBus\n\tserverRepo    repositories.ServerRepo\n\tcompanyRepo   repositories.CompanyRepo\n\tdb            *gorm.DB\n\trateLimiter   *sync.Mutex\n\trequestStamps map[string][]time.Time\n}\n\n// NewServerActionsService создает новый экземпляр сервиса.\nfunc NewServerActionsService(logger *zap.Logger, bus eventbus.EventBus, serverRepo repositories.ServerRepo, companyRepo repositories.CompanyRepo, db *gorm.DB) ServerActionsService {\n\treturn &serverActionsServiceImpl{\n\t\tlogger:        logger,\n\t\tbus:           bus,\n\t\tserverRepo:    serverRepo,\n\t\tcompanyRepo:   companyRepo,\n\t\tdb:            db,\n\t\trateLimiter:   &sync.Mutex{},\n\t\trequestStamps: make(map[string][]time.Time),\n\t}\n}\n\n// PollSingleServer запускает асинхронную задачу опроса через событие, с проверкой rate limit.\n// Принимает внутренний ID сервера.\nfunc (s *serverActionsServiceImpl) PollSingleServer(ctx context.Context, serverID string) error {\n\tif !s.checkRateLimit(serverID) {\n\t\treturn ErrRateLimitExceeded\n\t}\n\n\tserver, err := s.serverRepo.GetByID(ctx, serverID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения сервера из БД: %w\", err)\n\t}\n\tif server == nil {\n\t\treturn gorm.ErrRecordNotFound\n\t}\n\n\ts.logger.Info(\"Получен ручной запрос на опрос сервера. Публикация события...\", zap.String(\"serverID\", serverID))\n\n\ts.bus.Publish(eventbus.Event{\n\t\tType: events.ServerPollingRequested,\n\t\tPayload: events.ServerPollingRequestedPayload{\n\t\t\tServerUUID: serverID, // Поле в событии называется UUID, но мы передаем внутренний ID\n\t\t},\n\t})\n\n\treturn nil\n}\n\n// checkRateLimit проверяет, можно ли выполнить запрос для данного serverID.\nfunc (s *serverActionsServiceImpl) checkRateLimit(serverID string) bool {\n\ts.rateLimiter.Lock()\n\tdefer s.rateLimiter.Unlock()\n\tnow := time.Now()\n\tlimitWindowStart := now.Add(-rateLimitWindow)\n\tstamps := s.requestStamps[serverID]\n\trecentStamps := make([]time.Time, 0, len(stamps))\n\tfor _, stamp := range stamps {\n\t\tif stamp.After(limitWindowStart) {\n\t\t\trecentStamps = append(recentStamps, stamp)\n\t\t}\n\t}\n\tif len(recentStamps) >= rateLimitCount {\n\t\ts.logger.Warn(\"Превышен лимит запросов на опрос для сервера\", zap.String(\"serverID\", serverID))\n\t\ts.requestStamps[serverID] = recentStamps\n\t\treturn false\n\t}\n\trecentStamps = append(recentStamps, now)\n\ts.requestStamps[serverID] = recentStamps\n\treturn true\n}\n\n// InstallLicense - метод-заглушка для ручного запуска установки лицензии.\n// Принимает внутренний ID сервера.\nfunc (s *serverActionsServiceImpl) InstallLicense(ctx context.Context, serverID, uniqueID string) error {\n\tserver, err := s.serverRepo.GetByID(ctx, serverID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения сервера: %w\", err)\n\t}\n\tif server == nil {\n\t\treturn gorm.ErrRecordNotFound\n\t}\n\ts.logger.Info(\"ЗАГЛУШКА: Запущена установка лицензии\",\n\t\tzap.String(\"server_id\", serverID),\n\t\tzap.String(\"unique_id\", uniqueID),\n\t)\n\treturn nil\n}\n\n// AddAdditionalOwner добавляет компанию в список дополнительных владельцев сервера.\n// Принимает внутренние ID сервера и компании.\nfunc (s *serverActionsServiceImpl) AddAdditionalOwner(ctx context.Context, serverID, companyID string) error {\n\tserver, err := s.serverRepo.GetByID(ctx, serverID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения сервера: %w\", err)\n\t}\n\tif server == nil {\n\t\treturn gorm.ErrRecordNotFound\n\t}\n\n\tcompany, err := s.companyRepo.GetByID(ctx, companyID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения компании: %w\", err)\n\t}\n\tif company == nil {\n\t\treturn fmt.Errorf(\"компания с ID %s не найдена: %w\", companyID, gorm.ErrRecordNotFound)\n\t}\n\n\terr = s.db.Model(server).Association(\"AdditionalOwners\").Append(company)\n\tif err != nil {\n\t\ts.logger.Error(\"Не удалось добавить дополнительного владельца\", zap.Error(err))\n\t\treturn fmt.Errorf(\"ошибка добавления связи в БД: %w\", err)\n\t}\n\n\ts.logger.Info(\"Дополнительный владелец успешно добавлен к серверу\", zap.String(\"server_id\", serverID), zap.String(\"company_id\", companyID))\n\treturn nil\n}\n\n// RemoveAdditionalOwner удаляет компанию из списка дополнительных владельцев сервера.\n// Принимает внутренние ID сервера и компании.\nfunc (s *serverActionsServiceImpl) RemoveAdditionalOwner(ctx context.Context, serverID, companyID string) error {\n\tserver, err := s.serverRepo.GetByID(ctx, serverID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения сервера: %w\", err)\n\t}\n\tif server == nil {\n\t\treturn gorm.ErrRecordNotFound\n\t}\n\n\tcompany, err := s.companyRepo.GetByID(ctx, companyID)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"ошибка получения компании: %w\", err)\n\t}\n\tif company == nil {\n\t\treturn fmt.Errorf(\"компания с ID %s не найдена: %w\", companyID, gorm.ErrRecordNotFound)\n\t}\n\n\terr = s.db.Model(server).Association(\"AdditionalOwners\").Delete(company)\n\tif err != nil {\n\t\ts.logger.Error(\"Не удалось удалить дополнительного владельца\", zap.Error(err))\n\t\treturn fmt.Errorf(\"ошибка удаления связи из БД: %w\", err)\n\t}\n\n\ts.logger.Info(\"Дополнительный владелец успешно удален с сервера\", zap.String(\"server_id\", serverID), zap.String(\"company_id\", companyID))\n\treturn nil\n}\n",
    "internal/services/task_resolution_service.go": "// internal/services/task_resolution_service.go\npackage services\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"errors\"\n\t\"etalon-server/internal/api\"\n\t\"etalon-server/internal/contextkeys\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/internal/utils\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"fmt\"\n\n\t\"go.uber.org/zap\"\n\t\"gorm.io/gorm\"\n)\n\nvar (\n\tErrTaskNotFound      = errors.New(\"задача не найдена\")\n\tErrTaskAlreadyDone   = errors.New(\"задача уже была решена или отклонена\")\n\tErrInvalidPayload    = errors.New(\"некорректные данные в resolution_payload для этого типа задачи\")\n\tErrUnsupportedTask   = errors.New(\"этот тип задачи не поддерживает автоматическое выполнение\")\n\tErrInternalExecution = errors.New(\"внутренняя ошибка при выполнении действия по задаче\")\n)\n\ntype contextKey string\n\nconst transactionKey contextKey = \"tx\"\n\n// TaskResolutionService определяет интерфейс для сервиса выполнения задач.\ntype TaskResolutionService interface {\n\tResolve(ctx context.Context, taskID uint, dto *api.ResolveTaskRequestDTO) (*models.ReconciliationTask, error)\n\tRequestSDEntityCreation(ctx context.Context, taskID uint, entityType string) (*models.ReconciliationTask, error)\n}\n\ntype taskResolutionServiceImpl struct {\n\tlogger          *zap.Logger\n\tdb              *gorm.DB\n\tbus             eventbus.EventBus\n\ttaskRepo        repositories.TaskRepo\n\tserverRepo      repositories.ServerRepo\n\tworkstationRepo repositories.WorkstationRepo\n\tfrRepo          repositories.FiscalRegisterRepo\n}\n\n// NewTaskResolutionService создает новый экземпляр сервиса.\nfunc NewTaskResolutionService(logger *zap.Logger, db *gorm.DB, bus eventbus.EventBus, taskRepo repositories.TaskRepo, serverRepo repositories.ServerRepo, workstationRepo repositories.WorkstationRepo, frRepo repositories.FiscalRegisterRepo) TaskResolutionService {\n\treturn &taskResolutionServiceImpl{\n\t\tlogger:          logger,\n\t\tdb:              db,\n\t\tbus:             bus,\n\t\ttaskRepo:        taskRepo,\n\t\tserverRepo:      serverRepo,\n\t\tworkstationRepo: workstationRepo,\n\t\tfrRepo:          frRepo,\n\t}\n}\n\n// Resolve выполняет задачу на основе resolution_payload.\nfunc (s *taskResolutionServiceImpl) Resolve(ctx context.Context, taskID uint, dto *api.ResolveTaskRequestDTO) (*models.ReconciliationTask, error) {\n\tvar updatedTask *models.ReconciliationTask\n\terr := s.db.Transaction(func(tx *gorm.DB) error {\n\t\ttxCtx := context.WithValue(ctx, transactionKey, tx)\n\n\t\ttask, err := s.taskRepo.GetByID(txCtx, taskID)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif task == nil {\n\t\t\treturn ErrTaskNotFound\n\t\t}\n\t\tif task.Status != \"new\" && task.Status != \"sd_error\" {\n\t\t\treturn ErrTaskAlreadyDone\n\t\t}\n\n\t\tif dto.ResolutionPayload != nil {\n\t\t\taction, _ := dto.ResolutionPayload[\"action\"].(string)\n\t\t\tswitch action {\n\t\t\tcase \"update_in_sd\":\n\t\t\t\terr = s.handleUpdateInSD(ctx, task)\n\t\t\tcase \"create\":\n\t\t\t\terr = s.handleAddEquipment(txCtx, task, dto.ResolutionPayload)\n\t\t\tcase \"update_owner\":\n\t\t\t\terr = s.handleOwnerMismatch(txCtx, task, dto.ResolutionPayload)\n\t\t\tcase \"delete_duplicates\":\n\t\t\t\terr = s.handleResolveDuplicate(txCtx, task, dto.ResolutionPayload)\n\t\t\t}\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t}\n\n\t\ttask.Status = dto.Status\n\t\tif dto.Comment != \"\" {\n\t\t\ttask.Comment = fmt.Sprintf(\"%s\\n[РЕШЕНИЕ] %s\", task.Comment, dto.Comment)\n\t\t}\n\t\tif err := tx.Save(task).Error; err != nil {\n\t\t\treturn err\n\t\t}\n\n\t\tupdatedTask = task\n\t\treturn nil\n\t})\n\n\treturn updatedTask, err\n}\n\n// RequestSDEntityCreation инициирует асинхронное создание сущности в ServiceDesk.\nfunc (s *taskResolutionServiceImpl) RequestSDEntityCreation(ctx context.Context, taskID uint, entityType string) (*models.ReconciliationTask, error) {\n\tvar updatedTask *models.ReconciliationTask\n\terr := s.db.Transaction(func(tx *gorm.DB) error {\n\t\ttask, err := s.taskRepo.GetByID(ctx, taskID)\n\t\tif err != nil {\n\t\t\treturn err\n\t\t}\n\t\tif task == nil {\n\t\t\treturn ErrTaskNotFound\n\t\t}\n\t\tif task.Status != \"new\" && task.Status != \"sd_error\" {\n\t\t\treturn ErrTaskAlreadyDone\n\t\t}\n\t\tif task.TaskType != \"add_equipment\" {\n\t\t\treturn fmt.Errorf(\"создание сущности возможно только для задач типа 'add_equipment'\")\n\t\t}\n\t\tif task.EntityType != entityType {\n\t\t\treturn fmt.Errorf(\"несоответствие типа сущности: в задаче %s, в запросе %s\", task.EntityType, entityType)\n\t\t}\n\n\t\ttask.Status = \"pending_sd_action\"\n\t\ttask.Comment = fmt.Sprintf(\"%s\\n[ДЕЙСТВИЕ] Отправлен запрос на создание сущности в ServiceDesk.\", task.Comment)\n\t\tif err := tx.Save(task).Error; err != nil {\n\t\t\treturn err\n\t\t}\n\n\t\tuserID, _ := ctx.Value(contextkeys.UserIDContextKey).(string)\n\t\tif userID == \"\" {\n\t\t\tuserID = \"unknown\"\n\t\t}\n\n\t\tpayload := events.ServiceDeskModificationPayload{\n\t\t\tTaskID:            task.ID,\n\t\t\tEntityType:        task.EntityType,\n\t\t\tTriggeredByUserID: userID,\n\t\t}\n\t\ts.bus.Publish(eventbus.Event{\n\t\t\tType:    events.ServiceDeskCreateRequested,\n\t\t\tPayload: payload,\n\t\t})\n\t\ts.logger.Info(\"Опубликовано событие на создание сущности в ServiceDesk\", zap.Uint(\"taskID\", task.ID))\n\n\t\tupdatedTask = task\n\t\treturn nil\n\t})\n\treturn updatedTask, err\n}\n\n// handleUpdateInSD публикует событие для асинхронного обновления.\nfunc (s *taskResolutionServiceImpl) handleUpdateInSD(ctx context.Context, task *models.ReconciliationTask) error {\n\tuserID, _ := ctx.Value(contextkeys.UserIDContextKey).(string)\n\tif userID == \"\" {\n\t\tuserID = \"unknown\"\n\t}\n\n\tpayload := events.ServiceDeskModificationPayload{\n\t\tTaskID:            task.ID,\n\t\tEntityType:        task.EntityType,\n\t\tEntityUUID:        task.EntityUUID, // Здесь EntityUUID это внутренний ID\n\t\tTriggeredByUserID: userID,\n\t}\n\ts.bus.Publish(eventbus.Event{\n\t\tType:    events.ServiceDeskUpdateRequested,\n\t\tPayload: payload,\n\t})\n\ts.logger.Info(\"Опубликовано событие на обновление сущности в ServiceDesk\", zap.Uint(\"taskID\", task.ID), zap.String(\"entityUUID\", task.EntityUUID))\n\treturn nil\n}\n\n// handleResolveDuplicate обрабатывает задачу об удалении дубликатов.\nfunc (s *taskResolutionServiceImpl) handleResolveDuplicate(ctx context.Context, task *models.ReconciliationTask, payload map[string]interface{}) error {\n\trawUUIDs, ok := payload[\"delete_record_uuids\"].([]interface{})\n\tif !ok {\n\t\treturn ErrInvalidPayload\n\t}\n\n\ttx := ctx.Value(transactionKey).(*gorm.DB)\n\tfor _, uuidInterface := range rawUUIDs {\n\t\tuuid, ok := uuidInterface.(string)\n\t\tif !ok {\n\t\t\tcontinue\n\t\t}\n\t\tvar err error\n\t\tswitch task.EntityType {\n\t\tcase \"Server\":\n\t\t\t_, err = s.serverRepo.Delete(ctx, tx, uuid)\n\t\tcase \"Workstation\":\n\t\t\t_, err = s.workstationRepo.Delete(ctx, tx, uuid)\n\t\t}\n\t\tif err != nil {\n\t\t\ts.logger.Error(\"Ошибка 'мягкого удаления' дубликата\", zap.String(\"uuid\", uuid), zap.Error(err))\n\t\t}\n\t}\n\treturn nil\n}\n\n// handleOwnerMismatch обрабатывает задачу о смене владельца.\nfunc (s *taskResolutionServiceImpl) handleOwnerMismatch(ctx context.Context, task *models.ReconciliationTask, payload map[string]interface{}) error {\n\tnewOwnerID, ok := payload[\"new_owner_id\"].(string) // Ожидаем внутренний ID\n\tif !ok {\n\t\treturn ErrInvalidPayload\n\t}\n\n\ttx := ctx.Value(transactionKey).(*gorm.DB)\n\tupdates := map[string]interface{}{\"owner_id\": newOwnerID}\n\tvar err error\n\tswitch task.EntityType {\n\tcase \"Server\":\n\t\t_, err = s.serverRepo.Update(ctx, tx, task.EntityUUID, updates)\n\tcase \"Workstation\":\n\t\t_, err = s.workstationRepo.Update(ctx, tx, task.EntityUUID, updates)\n\tcase \"FiscalRegister\":\n\t\t_, err = s.frRepo.Update(ctx, tx, task.EntityUUID, updates)\n\t}\n\tif err != nil {\n\t\treturn ErrInternalExecution\n\t}\n\treturn nil\n}\n\n// handleAddEquipment обрабатывает задачу о добавлении нового оборудования.\nfunc (s *taskResolutionServiceImpl) handleAddEquipment(ctx context.Context, task *models.ReconciliationTask, payload map[string]interface{}) error {\n\tvar details struct {\n\t\tAgentData       api.AgentDataDTO `json:\"agent_data\"`\n\t\tEtalonOwnerUUID string           `json:\"etalon_owner_id\"` // Это должен быть внутренний ID\n\t}\n\tif err := json.Unmarshal(task.Details, &details); err != nil || details.EtalonOwnerUUID == \"\" {\n\t\ts.logger.Error(\"Не удалось извлечь agent_data или etalon_owner_id из деталей задачи\", zap.Uint(\"task_id\", task.ID))\n\t\treturn ErrInternalExecution\n\t}\n\n\ttx := ctx.Value(transactionKey).(*gorm.DB)\n\tvar err error\n\tswitch task.EntityType {\n\tcase \"Workstation\":\n\t\tws := &models.Workstation{\n\t\t\tOwnerID:     &details.EtalonOwnerUUID,\n\t\t\tDeviceName:  &details.AgentData.Hostname,\n\t\t\tTeamviewer:  &details.AgentData.TeamviewerID,\n\t\t\tLitemanager: &details.AgentData.LitemanagerID,\n\t\t\tAnydesk:     &details.AgentData.AnydeskID,\n\t\t\tStatus:      utils.StringPtr(\"offline\"),\n\t\t}\n\t\terr = s.workstationRepo.Create(ctx, tx, ws)\n\tcase \"FiscalRegister\":\n\t\tfr := &models.FiscalRegister{\n\t\t\tOwnerID:        &details.EtalonOwnerUUID,\n\t\t\tFRSerialNumber: &details.AgentData.SerialNumber,\n\t\t\tModelKKT:       &details.AgentData.ModelName,\n\t\t\tINN:            &details.AgentData.INN,\n\t\t\tRNKKT:          &details.AgentData.RNM,\n\t\t}\n\t\terr = s.frRepo.Create(ctx, tx, fr)\n\t}\n\tif err != nil {\n\t\treturn ErrInternalExecution\n\t}\n\n\treturn nil\n}\n",
    "internal/utils/helpers.go": "package utils\n\nimport (\n\t\"etalon-server/internal/api\"\n\t\"fmt\"\n\t\"net\"\n\t\"regexp\"\n\t\"sort\"\n\t\"strings\"\n\t\"time\"\n\t// Импорт остается нужным для CalculateFRFirmware\n)\n\n// TimeLayoutServiceDesk определяет формат времени, используемый в ServiceDesk.\nconst TimeLayoutServiceDesk = \"2006.01.02 15:04:05\"\n\n// TimeLayoutAgent определяет формат времени, используемый в JSON от агентов.\nconst TimeLayoutAgent = \"2006-01-02 15:04:05\"\n\n// Regex для поиска любых символов, кроме цифр.\nvar nonDigitRegex = regexp.MustCompile(`\\D`)\n\n// Regex для извлечения квартала и года из legacy-строки лицензии.\nvar legacyLicenseRegex = regexp.MustCompile(`(\\d)\\s*квартала\\s*(\\d{4})`)\n\n// ParseServiceDeskTime парсит строку времени из ServiceDesk.\n// Возвращает nil, если строка пустая или не может быть распарсена.\nfunc ParseServiceDeskTime(dateStr string) *time.Time {\n\tif dateStr == \"\" {\n\t\treturn nil\n\t}\n\tt, err := time.Parse(TimeLayoutServiceDesk, dateStr)\n\tif err != nil {\n\t\treturn nil\n\t}\n\treturn &t\n}\n\n// ParseAgentTime парсит строку времени из файла агента.\nfunc ParseAgentTime(dateStr string) *time.Time {\n\tif dateStr == \"\" {\n\t\treturn nil\n\t}\n\t// Убираем возможные пробелы на концах строки\n\tdateStr = strings.TrimSpace(dateStr)\n\tt, err := time.Parse(TimeLayoutAgent, dateStr)\n\tif err != nil {\n\t\tt, err2 := time.Parse(TimeLayoutServiceDesk, dateStr)\n\t\tif err2 != nil {\n\t\t\treturn nil\n\t\t}\n\t\treturn &t\n\t}\n\treturn &t\n}\n\n// FormatFFDVersion преобразует версию ФФД из формата агента в эталонный.\nfunc FormatFFDVersion(rawVersion string) string {\n\tswitch rawVersion {\n\tcase \"120\":\n\t\treturn \"1.2\"\n\tcase \"105\":\n\t\treturn \"1.05\"\n\tdefault:\n\t\treturn rawVersion\n\t}\n}\n\n// SafeStringDereference безопасно разыменовывает указатель на строку.\nfunc SafeStringDereference(s *string) string {\n\tif s != nil {\n\t\treturn *s\n\t}\n\treturn \"\"\n}\n\n// NormalizeRNKKT очищает регистрационный номер ККТ, оставляя только цифры.\nfunc NormalizeRNKKT(rnm string) string {\n\treturn nonDigitRegex.ReplaceAllString(rnm, \"\")\n}\n\n// FormatRNKKT форматирует чистый РН ККТ для вывода в ServiceDesk, добавляя пробелы.\nfunc FormatRNKKT(rnm string) string {\n\tcleanRnm := NormalizeRNKKT(rnm)\n\tif len(cleanRnm) != 16 {\n\t\treturn cleanRnm // Возвращаем как есть, если длина некорректна\n\t}\n\treturn fmt.Sprintf(\"%s %s %s %s\", cleanRnm[0:4], cleanRnm[4:8], cleanRnm[8:12], cleanRnm[12:16])\n}\n\n// IsPrivateIP проверяет, является ли IP-адрес приватным (локальным).\nfunc IsPrivateIP(ipStr string) (bool, error) {\n\tip := net.ParseIP(ipStr)\n\tif ip == nil {\n\t\treturn false, fmt.Errorf(\"некорректный IP-адрес: %s\", ipStr)\n\t}\n\n\t_, private24, _ := net.ParseCIDR(\"10.0.0.0/8\")\n\t_, private20, _ := net.ParseCIDR(\"172.16.0.0/12\")\n\t_, private16, _ := net.ParseCIDR(\"192.168.0.0/16\")\n\n\treturn private24.Contains(ip) || private20.Contains(ip) || private16.Contains(ip), nil\n}\n\n// CalculateFRFirmware вычисляет строку для поля FRFirmware на основе лицензий.\n// Обрабатывает как новый (структурированный), так и старый (строковый) формат.\nfunc CalculateFRFirmware(licenses api.LicensesField) string {\n\t// 1. Обработка нового, структурированного формата\n\tif len(licenses.Structured) > 0 {\n\t\tvar parts []string\n\t\tnow := time.Now()\n\t\t// Устанавливаем временное окно +- 3 года от текущей даты\n\t\tthreeYearsAgo := now.AddDate(-3, 0, 0)\n\t\tthreeYearsFromNow := now.AddDate(3, 0, 0)\n\n\t\tfor id, licenseInfo := range licenses.Structured {\n\t\t\tdateUntil := ParseAgentTime(licenseInfo.DateUntil)\n\t\t\tif dateUntil == nil {\n\t\t\t\tcontinue // Пропускаем лицензии с некорректной датой\n\t\t\t}\n\n\t\t\t// Проверяем, что лицензия попадает в окно +- 3 года.\n\t\t\tif dateUntil.After(threeYearsAgo) && dateUntil.Before(threeYearsFromNow) {\n\t\t\t\t// Форматируем в \"ID:ДД.ММ.ГГГГ\"\n\t\t\t\tpart := fmt.Sprintf(\"%s:%s\", id, dateUntil.Format(\"02.01.2006\"))\n\t\t\t\tparts = append(parts, part)\n\t\t\t}\n\t\t}\n\t\tsort.Strings(parts)\n\t\treturn strings.Join(parts, \"; \")\n\t}\n\n\t// 2. Обработка старого, строкового формата\n\tif licenses.Legacy != \"\" {\n\t\tmatches := legacyLicenseRegex.FindStringSubmatch(licenses.Legacy)\n\t\t// matches[0] - вся строка, matches[1] - квартал, matches[2] - год\n\t\tif len(matches) == 3 {\n\t\t\treturn fmt.Sprintf(\"%s.%s\", matches[1], matches[2])\n\t\t}\n\t}\n\n\treturn \"\"\n}\n\n// StringPtr создает указатель на строку.\n// Возвращает nil, если строка пустая.\nfunc StringPtr(s string) *string {\n\tif s == \"\" {\n\t\treturn nil\n\t}\n\treturn &s\n}\n",
    "internal/utils/rms_client.go": "// internal/utils/rms_client.go\n// internal/utils/rms_client.go\npackage utils\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"encoding/xml\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n)\n\n// ServerInfoXML структура для парсинга XML-ответа от сервера iikoRMS\ntype ServerInfoXML struct {\n\tXMLName     xml.Name `xml:\"r\"`\n\tServerName  string   `xml:\"serverName\"`\n\tVersion     string   `xml:\"version\"`\n\tEdition     string   `xml:\"edition\"`\n\tServerState string   `xml:\"serverState\"`\n}\n\n// RMSClient определяет интерфейс для взаимодействия с RMS API.\ntype RMSClient interface {\n\tGetServerMonitoringInfo(ctx context.Context, serverURL string) (*ServerInfoXML, error)\n}\n\ntype rmsClientImpl struct {\n\thttpClient *http.Client\n\tlogger     *zap.Logger\n}\n\n// NewRMSClient создает новый экземпляр клиента для RMS.\nfunc NewRMSClient(timeout time.Duration, logger *zap.Logger) RMSClient {\n\treturn &rmsClientImpl{\n\t\thttpClient: &http.Client{\n\t\t\tTimeout: timeout,\n\t\t},\n\t\tlogger: logger,\n\t}\n}\n\n// GetServerMonitoringInfo получает статус и информацию о сервере.\n// ИСПРАВЛЕНО: Теперь в первую очередь парсит XML.\nfunc (c *rmsClientImpl) GetServerMonitoringInfo(ctx context.Context, serverURL string) (*ServerInfoXML, error) {\n\treq, err := http.NewRequestWithContext(ctx, \"GET\", fmt.Sprintf(\"%s/resto/get_server_info.jsp?encoding=UTF-8\", serverURL), nil)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось создать GET-запрос: %w\", err)\n\t}\n\n\tresp, err := c.httpClient.Do(req)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось выполнить GET-запрос для получения информации о сервере: %w\", err)\n\t}\n\tdefer resp.Body.Close()\n\n\tif resp.StatusCode != http.StatusOK {\n\t\treturn nil, NewHttpError(resp.StatusCode, fmt.Sprintf(\"сервер вернул ошибку при получении информации: %s\", resp.Status))\n\t}\n\n\tbody, err := io.ReadAll(resp.Body)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось прочитать ответ от сервера: %w\", err)\n\t}\n\n\tvar info ServerInfoXML\n\tif err := xml.Unmarshal(body, &info); err != nil {\n\t\t// Попытка fallback на JSON, если XML не удался\n\t\tc.logger.Warn(\"Не удалось распарсить XML, попытка распарсить как JSON\", zap.String(\"server_url\", serverURL), zap.Error(err))\n\t\tvar jsonInfo struct {\n\t\t\tServerName  string `json:\"serverName\"`\n\t\t\tEdition     string `json:\"edition\"`\n\t\t\tVersion     string `json:\"version\"`\n\t\t\tServerState string `json:\"serverState\"`\n\t\t}\n\t\tif jsonErr := json.Unmarshal(body, &jsonInfo); jsonErr == nil {\n\t\t\tinfo.ServerName = jsonInfo.ServerName\n\t\t\tinfo.Edition = jsonInfo.Edition\n\t\t\tinfo.Version = jsonInfo.Version\n\t\t\tinfo.ServerState = jsonInfo.ServerState\n\t\t} else {\n\t\t\treturn nil, fmt.Errorf(\"не удалось разобрать ответ ни как XML, ни как JSON: %w\", err)\n\t\t}\n\t}\n\n\treturn &info, nil\n}\n\n/*\n =================================================================================\n  ОТНОСИТСЯ К СТАРОЙ ЛОГИКЕ\n  ПОЛУЧЕНИЯ CRMID.\n  ОН МОЖЕТ ПОНАДОБИТЬСЯ В БУДУЩЕМ ДЛЯ ДРУГИХ ЗАДАЧ.\n =================================================================================\n\n// Структуры для парсинга XML-ответов от сервера iikoRMS\ntype ServerInfo struct {\n\tXMLName xml.Name `xml:\"r\"`\n\tVersion string   `xml:\"version\"`\n\tEdition string   `xml:\"edition\"`\n}\n\ntype LicenseInfoResponse struct {\n\tXMLName           xml.Name `xml:\"result\"`\n\tCrmOrganizationId string   `xml:\"licenseInfo>licenseData>r>crmOrganizationId\"`\n\tSerialNumber      string   `xml:\"licenseInfo>licenseData>r>serialNumber\"`\n}\n\n// GetCRMid подключается к серверу iikoRMS и возвращает его CRMid.\n// Поддерживает попытку с fallbackPassword в случае ошибки аутентификации.\nfunc (c *rmsClientImpl) GetCRMid(ctx context.Context, serverURL, login, password, fallbackPassword string) (string, error) {\n\tlog := c.logger.With(zap.String(\"server_url\", serverURL))\n\n\t// Первая попытка с основным паролем\n\tcrmid, err := c.fetchCRMid(ctx, serverURL, login, password, log)\n\tif err == nil {\n\t\treturn crmid, nil\n\t}\n\n\t// Проверяем, является ли ошибка ошибкой аутентификации (401/403)\n\tvar httpErr *HttpError\n\tif asHttpErr, ok := err.(*HttpError); ok {\n\t\thttpErr = asHttpErr\n\t}\n\n\tif (httpErr != nil && (httpErr.StatusCode == http.StatusUnauthorized || httpErr.StatusCode == http.StatusForbidden)) && fallbackPassword != \"\" {\n\t\tlog.Warn(\"Первая попытка аутентификации не удалась, пробую с запасным паролем.\")\n\t\t// Вторая попытка с запасным паролем\n\t\treturn c.fetchCRMid(ctx, serverURL, login, fallbackPassword, log)\n\t}\n\n\treturn \"\", err\n}\n\nfunc (c *rmsClientImpl) fetchCRMid(ctx context.Context, serverURL, login, password string, log *zap.Logger) (string, error) {\n\t// 1. Получаем информацию о сервере (версия, редакция)\n\tinfo, err := c.getServerInfoXML(ctx, serverURL)\n\tif err != nil {\n\t\treturn \"\", err\n\t}\n\n\t// 2. Хэшируем пароль по алгоритму SHA1\n\thasher := sha1.New()\n\thasher.Write([]byte(password))\n\tpasswordHash := hex.EncodeToString(hasher.Sum(nil))\n\n\t// 3. Формируем тело и заголовки для запроса\n\tendpoint := fmt.Sprintf(\"%s/resto/services/licensing?methodName=getForceDeveloperSandboxModeInfo&\", serverURL)\n\txmlBody := `<?xml version=\"1.0\" encoding=\"utf-8\"?><args><entities-version>1</entities-version><client-type>BACK</client-type><enable-warnings>false</enable-warnings><client-call-id>30264dfd-570d-46c0-81b8-6bef9da5a2c9</client-call-id><license-hash>-1938788177</license-hash><restrictions-state-hash>5761</restrictions-state-hash><obtained-license-connections-ids /><request-watchdog-check-results>true</request-watchdog-check-results><use-raw-entities>true</use-raw-entities></args>`\n\n\treq, err := http.NewRequestWithContext(ctx, \"POST\", endpoint, bytes.NewBufferString(xmlBody))\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось создать POST-запрос: %w\", err)\n\t}\n\n\treq.Header.Set(\"Content-Type\", \"text/xml\")\n\treq.Header.Set(\"X-Resto-LoginName\", login)\n\treq.Header.Set(\"X-Resto-PasswordHash\", passwordHash)\n\treq.Header.Set(\"X-Resto-BackVersion\", info.Version)\n\treq.Header.Set(\"X-Resto-AuthType\", \"BACK\")\n\treq.Header.Set(\"X-Resto-ServerEdition\", info.Edition)\n\n\t// 4. Отправляем запрос\n\tresp, err := c.httpClient.Do(req)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"ошибка при отправке запроса на получение CRMid: %w\", err)\n\t}\n\tdefer resp.Body.Close()\n\n\tresponseBody, err := io.ReadAll(resp.Body)\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось прочитать ответ сервера: %w\", err)\n\t}\n\n\tif resp.StatusCode != http.StatusOK {\n\t\treturn \"\", NewHttpError(resp.StatusCode, fmt.Sprintf(\"сервер вернул ошибку при получении CRMid: %s. Ответ: %s\", resp.Status, string(responseBody)))\n\t}\n\n\t// 5. Парсим ответ\n\tvar licenseInfo LicenseInfoResponse\n\tcleanXML := strings.ReplaceAll(string(responseBody), \"&lt;\", \"<\")\n\tcleanXML = strings.ReplaceAll(cleanXML, \"&gt;\", \">\")\n\n\tif err := xml.Unmarshal([]byte(cleanXML), &licenseInfo); err != nil {\n\t\treturn \"\", fmt.Errorf(\"не удалось разобрать XML-ответ с лицензией: %w. Ответ: %s\", err, string(responseBody))\n\t}\n\n\tif licenseInfo.CrmOrganizationId == \"\" {\n\t\treturn \"\", fmt.Errorf(\"не удалось найти CRMid в ответе сервера. Ответ: %s\", string(responseBody))\n\t}\n\n\treturn licenseInfo.CrmOrganizationId, nil\n}\n\nfunc (c *rmsClientImpl) getServerInfoXML(ctx context.Context, serverURL string) (*ServerInfo, error) {\n\treq, err := http.NewRequestWithContext(ctx, \"GET\", fmt.Sprintf(\"%s/resto/get_server_info.jsp?encoding=UTF-8\", serverURL), nil)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось создать GET-запрос: %w\", err)\n\t}\n\n\tresp, err := c.httpClient.Do(req)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось выполнить GET-запрос для получения информации о сервере: %w\", err)\n\t}\n\tdefer resp.Body.Close()\n\n\tif resp.StatusCode != http.StatusOK {\n\t\treturn nil, NewHttpError(resp.StatusCode, fmt.Sprintf(\"сервер вернул ошибку при получении информации: %s\", resp.Status))\n\t}\n\n\tbody, err := io.ReadAll(resp.Body)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось прочитать ответ от сервера: %w\", err)\n\t}\n\n\tvar info ServerInfo\n\tif err := xml.Unmarshal(body, &info); err != nil {\n\t\treturn nil, fmt.Errorf(\"не удалось разобрать XML с информацией о сервере: %w\", err)\n\t}\n\n\tinfo.Edition = strings.Replace(info.Edition, \"default\", \"IIKO_RMS\", -1)\n\tinfo.Edition = strings.Replace(info.Edition, \"chain\", \"IIKO_CHAIN\", -1)\n\n\treturn &info, nil\n}\n*/\n\n// HttpError специальный тип ошибки для HTTP-ответов\ntype HttpError struct {\n\tStatusCode int\n\tMessage    string\n}\n\nfunc (e *HttpError) Error() string {\n\treturn fmt.Sprintf(\"HTTP %d: %s\", e.StatusCode, e.Message)\n}\n\nfunc NewHttpError(code int, message string) *HttpError {\n\treturn &HttpError{StatusCode: code, Message: message}\n}\n",
    "internal/validators/validators.go": "package validators\n\nimport (\n\t\"fmt\"\n\t\"net/url\"\n\t\"regexp\"\n\t\"strconv\"\n\t\"strings\"\n)\n\nvar (\n\tuniqueIDRegex         = regexp.MustCompile(`^\\d{3}-\\d{3}-\\d{3}$`)\n\tremoteAccessIDRegex   = regexp.MustCompile(`(\\d\\s*){9,10}`)\n\tLiteManagerIDRegex    = regexp.MustCompile(`MH_\\d{5}`)\n\tiikoCloudDomainRegex  = regexp.MustCompile(`(?i)(?:https?://)?(?:[a-z0-9-]+\\.)?([a-z0-9-]+\\.iiko\\.it)`)\n\tsyrveCloudDomainRegex = regexp.MustCompile(`(?i)(?:https?://)?(?:[a-z0-9-]+\\.)?([a-z0-9-]+\\.syrve\\.online)`)\n)\n\n// ValidateUniqueID проверяет формат UniqueID.\nfunc ValidateUniqueID(uniqueID string) *string {\n\tif uniqueIDRegex.MatchString(uniqueID) {\n\t\treturn &uniqueID\n\t}\n\treturn nil\n}\n\n// ValidateRemoteAccessID находит и нормализует ID удаленного доступа (TeamViewer, Anydesk).\nfunc ValidateRemoteAccessID(raw string) *string {\n\tfound := remoteAccessIDRegex.FindString(raw)\n\tif found == \"\" {\n\t\treturn nil\n\t}\n\tnormalized := strings.ReplaceAll(found, \" \", \"\")\n\treturn &normalized\n}\n\n// ExtractLiteManagerID извлекает LiteManager ID из данных.\nfunc ExtractLiteManagerID(data map[string]interface{}, fallback string) *string {\n\tif id, ok := data[\"litemanagerID\"].(string); ok && LiteManagerIDRegex.MatchString(id) {\n\t\treturn &id\n\t}\n\tfound := LiteManagerIDRegex.FindString(fallback)\n\tif found != \"\" {\n\t\treturn &found\n\t}\n\treturn nil\n}\n\n// DetermineCompanyTypeFromIP определяет тип компании (\"syrve\" или \"iiko\") по IP/домену.\nfunc DetermineCompanyTypeFromIP(ip string) string {\n\tif strings.Contains(strings.ToLower(ip), \"syrve\") {\n\t\treturn \"syrve\"\n\t}\n\treturn \"iiko\"\n}\n\n// ValidateCabinetLink извлекает clientId из ссылки на личный кабинет.\nfunc ValidateCabinetLink(raw string, companyType string) string {\n\tlastIndex := strings.LastIndex(raw, \"=\")\n\n\t// Если \"=\" не найден или это последний символ в строке\n\tif lastIndex == -1 || lastIndex == len(raw)-1 {\n\t\treturn \"N/A\"\n\t}\n\n\t// Берем подстроку после последнего \"=\"\n\tidStr := raw[lastIndex+1:]\n\n\t// Дополнительно очищаем от возможных якорей (#) или других параметров (&)\n\tif anchorIndex := strings.Index(idStr, \"#\"); anchorIndex != -1 {\n\t\tidStr = idStr[:anchorIndex]\n\t}\n\tif paramIndex := strings.Index(idStr, \"&\"); paramIndex != -1 {\n\t\tidStr = idStr[:paramIndex]\n\t}\n\n\t// Проверяем, является ли полученная строка числом\n\tif _, err := strconv.Atoi(idStr); err == nil {\n\t\treturn idStr\n\t}\n\n\treturn \"N/A\"\n}\n\n// ValidateIPAddress валидирует и нормализует IP-адрес или домен.\n// НОВАЯ РЕАЛИЗАЦИЯ: Использует пакет net/url для надежного парсинга.\nfunc ValidateIPAddress(raw string) *string {\n\tif raw == \"\" {\n\t\treturn nil\n\t}\n\traw = strings.TrimSpace(raw)\n\n\t// 1. Приоритетная проверка на специальные облачные домены.\n\tif matches := iikoCloudDomainRegex.FindStringSubmatch(raw); len(matches) > 1 {\n\t\tres := fmt.Sprintf(\"%s:443\", matches[1])\n\t\treturn &res\n\t}\n\tif matches := syrveCloudDomainRegex.FindStringSubmatch(raw); len(matches) > 1 {\n\t\tres := fmt.Sprintf(\"%s:443\", matches[1])\n\t\treturn &res\n\t}\n\n\t// 2. Используем url.Parse для надежного разбора.\n\t// Добавляем схему \"http://\", если она отсутствует, чтобы парсер корректно работал\n\t// с адресами вида \"domain.com:8080\".\n\tparseableURL := raw\n\tif !strings.Contains(parseableURL, \"://\") {\n\t\tparseableURL = \"http://\" + parseableURL\n\t}\n\n\tparsedURL, err := url.Parse(parseableURL)\n\tif err != nil {\n\t\t// Если даже с добавленной схемой парсинг не удался, считаем адрес невалидным.\n\t\treturn nil\n\t}\n\n\thostname := parsedURL.Hostname()\n\tport := parsedURL.Port()\n\n\t// Если не удалось извлечь хост, адрес невалидный.\n\tif hostname == \"\" {\n\t\treturn nil\n\t}\n\n\t// 3. Формируем итоговую строку.\n\tvar result string\n\tif port != \"\" {\n\t\t// Если порт был указан в исходной строке, используем его.\n\t\tresult = fmt.Sprintf(\"%s:%s\", hostname, port)\n\t} else {\n\t\t// Если порт не указан, используем порт по умолчанию 8080.\n\t\t// Это стандарт для локальных серверов iikoRMS.\n\t\tresult = fmt.Sprintf(\"%s:8080\", hostname)\n\t}\n\n\treturn &result\n}\n",
    "internal/validators/validators_test.go": "package validators\n\nimport (\n\t\"testing\"\n\n\t\"github.com/stretchr/testify/assert\"\n)\n\nfunc TestValidateRemoteAccessID(t *testing.T) {\n\ttestCases := []struct {\n\t\tname     string\n\t\tinput    string\n\t\texpected *string\n\t}{\n\t\t{\"Valid ID with spaces\", \"123 456 789\", stringPtr(\"123456789\")},\n\t\t{\"Valid 10-digit ID\", \"1234567890\", stringPtr(\"1234567890\")},\n\t\t{\"Invalid short ID\", \"123 456\", nil},\n\t\t{\"ID with text\", \"AnyDesk: 987 654 321\", stringPtr(\"987654321\")},\n\t\t{\"Empty string\", \"\", nil},\n\t}\n\n\tfor _, tc := range testCases {\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\tresult := ValidateRemoteAccessID(tc.input)\n\t\t\tassert.Equal(t, tc.expected, result)\n\t\t})\n\t}\n}\n\nfunc TestValidateIPAddress(t *testing.T) {\n\ttestCases := []struct {\n\t\tname     string\n\t\tinput    string\n\t\texpected *string\n\t}{\n\t\t{\"Valid IP without port\", \"192.168.1.1\", stringPtr(\"192.168.1.1:8080\")},\n\t\t{\"Valid IP with port\", \"8.8.8.8:53\", stringPtr(\"8.8.8.8:53\")},\n\t\t{\"Iiko cloud domain\", \"https://my-res.iiko.it\", stringPtr(\"my-res.iiko.it:443\")},\n\t\t{\"Syrve cloud domain\", \"https://my-res.syrve.online/api\", stringPtr(\"my-res.syrve.online:443\")},\n\t\t{\"Local domain without port\", \"localhost\", stringPtr(\"localhost:8080\")},\n\t\t{\"Local domain with port\", \"db.local:5432\", stringPtr(\"db.local:5432\")},\n\t\t{\"Invalid IP\", \"999.999.999.999\", nil},\n\t\t{\"Just text\", \"not an ip\", nil},\n\t}\n\n\tfor _, tc := range testCases {\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\tresult := ValidateIPAddress(tc.input)\n\t\t\tassert.Equal(t, tc.expected, result)\n\t\t})\n\t}\n}\n\nfunc TestValidateUniqueID(t *testing.T) {\n\ttestCases := []struct {\n\t\tname     string\n\t\tinput    string\n\t\texpected *string\n\t}{\n\t\t{\"Корректный ID\", \"123-456-789\", stringPtr(\"123-456-789\")},\n\t\t{\"Некорректный ID с буквами\", \"123-abc-789\", nil},\n\t\t{\"Некорректный формат\", \"123456789\", nil},\n\t\t{\"Пустая строка\", \"\", nil},\n\t}\n\n\tfor _, tc := range testCases {\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\tresult := ValidateUniqueID(tc.input)\n\t\t\tassert.Equal(t, tc.expected, result)\n\t\t})\n\t}\n}\n\nfunc TestExtractLiteManagerID(t *testing.T) {\n\ttestCases := []struct {\n\t\tname     string\n\t\tdata     map[string]interface{}\n\t\tfallback string\n\t\texpected *string\n\t}{\n\t\t{\"ID в поле data\", map[string]interface{}{\"litemanagerID\": \"MH_12345\"}, \"\", stringPtr(\"MH_12345\")},\n\t\t{\"ID в fallback строке\", map[string]interface{}{}, \"Какой-то текст с MH_54321 внутри\", stringPtr(\"MH_54321\")},\n\t\t{\"ID отсутствует\", map[string]interface{}{}, \"Просто текст\", nil},\n\t\t{\"Некорректный ID в поле data\", map[string]interface{}{\"litemanagerID\": \"MH_123\"}, \"\", nil},\n\t}\n\n\tfor _, tc := range testCases {\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\tresult := ExtractLiteManagerID(tc.data, tc.fallback)\n\t\t\tassert.Equal(t, tc.expected, result)\n\t\t})\n\t}\n}\n\nfunc TestDetermineCompanyTypeFromIP(t *testing.T) {\n\tassert.Equal(t, \"syrve\", DetermineCompanyTypeFromIP(\"my.syrve.online\"))\n\tassert.Equal(t, \"iiko\", DetermineCompanyTypeFromIP(\"my.iiko.it\"))\n\tassert.Equal(t, \"iiko\", DetermineCompanyTypeFromIP(\"192.168.1.1\"))\n}\n\nfunc TestValidateCabinetLink(t *testing.T) {\n\ttestCases := []struct {\n\t\tname     string\n\t\tinput    string\n\t\texpected string\n\t}{\n\t\t{\"Стандартный случай с clientId\", \"https://cabinet?clientId=12345\", \"12345\"},\n\t\t{\"Случай с параметром id в конце\", \"https://partners.iiko.ru/ru/cabinet/clients.html?mode=showOne&id=720846\", \"720846\"},\n\t\t{\"Случай с некорректным ключом (должен вернуть N/A)\", \"https://cabinet?client=12345\", \"12345\"}, // Оставим это поведение, оно соответствует логике \"берем последнее\"\n\t\t{\"URL без знака равно\", \"https://cabinet/clients\", \"N/A\"},\n\t\t{\"Параметр не является числом\", \"https://cabinet?id=abc\", \"N/A\"},\n\t\t{\"Параметр с якорем\", \"https://cabinet?id=54321#details\", \"54321\"},\n\t\t{\"Пустая строка\", \"\", \"N/A\"},\n\t}\n\n\tfor _, tc := range testCases {\n\t\tt.Run(tc.name, func(t *testing.T) {\n\t\t\t// В этой функции второй параметр companyType не используется, так что можно передать пустую строку\n\t\t\tassert.Equal(t, tc.expected, ValidateCabinetLink(tc.input, \"\"))\n\t\t})\n\t}\n}\n\n// Вспомогательная функция для тестов, чтобы создавать указатели на строки.\nfunc stringPtr(s string) *string {\n\treturn &s\n}\n",
    "internal/workers/fr_update_founder.go": "// internal/workers/fr_update_founder.go\npackage workers\n\nimport (\n\t\"context\"\n\t\"etalon-server/internal/config\"\n\t\"etalon-server/internal/core/events\"\n\t\"etalon-server/internal/external\"\n\t\"etalon-server/internal/models\"\n\t\"etalon-server/internal/repositories\"\n\t\"etalon-server/pkg/eventbus\"\n\t\"time\"\n\n\t\"go.uber.org/zap\"\n)\n\n// FRUpdateFounder (Fiscal Register Update Founder) - это фоновый воркер,\n// который периодически сверяет данные о фискальных регистраторах в локальной\n// базе данных с данными в ServiceDesk.\ntype FRUpdateFounder interface {\n\tStart(ctx context.Context)\n}\n\ntype frUpdateFounderImpl struct {\n\tcfg      *config.Config\n\tlogger   *zap.Logger\n\tbus      eventbus.EventBus\n\tfrRepo   repositories.FiscalRegisterRepo\n\tlinkRepo repositories.LinkRepo // Новая зависимость\n\tsdClient external.ExternalSystemClient\n}\n\n// NewFRUpdateFounder создает новый экземпляр воркера.\nfunc NewFRUpdateFounder(\n\tcfg *config.Config,\n\tlogger *zap.Logger,\n\tbus eventbus.EventBus,\n\tfrRepo repositories.FiscalRegisterRepo,\n\tlinkRepo repositories.LinkRepo, // Новая зависимость\n\tsdClient external.ExternalSystemClient,\n) FRUpdateFounder {\n\treturn &frUpdateFounderImpl{\n\t\tcfg:      cfg,\n\t\tlogger:   logger,\n\t\tbus:      bus,\n\t\tfrRepo:   frRepo,\n\t\tlinkRepo: linkRepo,\n\t\tsdClient: sdClient,\n\t}\n}\n\n// Start запускает воркер в фоновом режиме.\nfunc (w *frUpdateFounderImpl) Start(ctx context.Context) {\n\tw.logger.Info(\"Запуск воркера поиска обновлений для ФР (FRUpdateFounder)\", zap.Duration(\"interval\", w.cfg.FRDiscrepancyCheckInterval))\n\tticker := time.NewTicker(w.cfg.FRDiscrepancyCheckInterval)\n\tdefer ticker.Stop()\n\n\tw.runCheckCycle(ctx)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ticker.C:\n\t\t\tw.runCheckCycle(ctx)\n\t\tcase <-ctx.Done():\n\t\t\tw.logger.Info(\"Остановка воркера FRUpdateFounder.\")\n\t\t\treturn\n\t\t}\n\t}\n}\n\n// runCheckCycle выполняет один полный цикл сверки данных.\nfunc (w *frUpdateFounderImpl) runCheckCycle(ctx context.Context) {\n\tw.logger.Info(\"Начало нового цикла сверки данных ФР с ServiceDesk.\")\n\n\t// 1. Получаем все ФР из ServiceDesk.\n\tremoteFRsData, err := w.sdClient.FetchEntityList(ctx, \"FiscalRegister\")\n\tif err != nil {\n\t\tw.logger.Error(\"Не удалось получить список ФР из ServiceDesk, цикл прерван\", zap.Error(err))\n\t\treturn\n\t}\n\n\t// 2. Преобразуем данные из SD в мапу [externalUUID] -> *models.FiscalRegister\n\tremoteFRsMap := make(map[string]*models.FiscalRegister, len(remoteFRsData))\n\t// MapperContext здесь не нужен, так как DataToFiscalRegister не ищет связей\n\tmapperCtx := &external.MapperContext{Logger: w.logger}\n\tfor _, data := range remoteFRsData {\n\t\tfr, err := w.sdClient.Mapper().DataToFiscalRegister(ctx, mapperCtx, data)\n\t\tif err != nil {\n\t\t\tuuid, _ := data[\"UUID\"].(string)\n\t\t\tw.logger.Warn(\"Пропуск ФР из ServiceDesk из-за ошибки маппинга\", zap.String(\"uuid\", uuid), zap.Error(err))\n\t\t\tcontinue\n\t\t}\n\t\texternalUUID, _ := data[\"UUID\"].(string)\n\t\tremoteFRsMap[externalUUID] = fr\n\t}\n\tw.logger.Info(\"Из ServiceDesk загружено и обработано ФР\", zap.Int(\"count\", len(remoteFRsMap)))\n\n\t// 3. Получаем все ФР из нашей локальной (\"эталонной\") базы.\n\tlocalFRs, err := w.frRepo.Search(ctx, \"\", 10000, 0)\n\tif err != nil {\n\t\tw.logger.Error(\"Не удалось получить список ФР из локальной БД, цикл прерван\", zap.Error(err))\n\t\treturn\n\t}\n\tw.logger.Info(\"Из локальной БД загружено ФР для сверки\", zap.Int(\"count\", len(localFRs)))\n\n\tpublishedEvents := 0\n\t// 4. Итерируем по локальным ФР и сравниваем их с данными из SD.\n\tfor _, localFR := range localFRs {\n\t\t// Находим внешний ID для нашего локального ФР\n\t\tlink, err := w.linkRepo.GetByInternalID(ctx, nil, \"naumen\", localFR.ID)\n\t\tif err != nil {\n\t\t\tw.logger.Error(\"Ошибка получения связи для ФР\", zap.String(\"internal_id\", localFR.ID), zap.Error(err))\n\t\t\tcontinue\n\t\t}\n\t\tif link == nil {\n\t\t\tw.logger.Debug(\"Пропуск ФР, для которого нет связи с внешней системой\", zap.String(\"internal_id\", localFR.ID))\n\t\t\tcontinue\n\t\t}\n\n\t\tremoteFR, ok := remoteFRsMap[link.ExternalID]\n\t\tif !ok {\n\t\t\tw.logger.Debug(\"Пропуск локального ФР, так как он отсутствует во внешней системе\", zap.String(\"internal_id\", localFR.ID))\n\t\t\tcontinue\n\t\t}\n\n\t\tdiscrepancies := w.compareFiscalRegisters(&localFR, remoteFR)\n\n\t\tif len(discrepancies) > 0 {\n\t\t\tpayload := events.FiscalRegisterDiscrepancyPayload{\n\t\t\t\tFRServiceDeskUUID: link.ExternalID,\n\t\t\t\tDiscrepancies:     discrepancies,\n\t\t\t}\n\t\t\tw.bus.Publish(eventbus.Event{\n\t\t\t\tType:    events.FiscalRegisterDiscrepancyFound,\n\t\t\t\tPayload: payload,\n\t\t\t})\n\t\t\tpublishedEvents++\n\t\t}\n\t}\n\n\tw.logger.Info(\"Цикл сверки данных ФР завершен.\", zap.Int(\"published_events\", publishedEvents))\n}\n\n// compareFiscalRegisters сравнивает два фискальных регистратора и возвращает карту расхождений.\nfunc (w *frUpdateFounderImpl) compareFiscalRegisters(local, remote *models.FiscalRegister) map[string]events.DiscrepancyDetail {\n\tdiscrepancies := make(map[string]events.DiscrepancyDetail)\n\n\tif local.FNExpireDate != nil && (remote.FNExpireDate == nil || !local.FNExpireDate.Truncate(24*time.Hour).Equal(remote.FNExpireDate.Truncate(24*time.Hour))) {\n\t\tvar remoteDateStr string\n\t\tif remote.FNExpireDate != nil {\n\t\t\tremoteDateStr = remote.FNExpireDate.Format(\"2006-01-02\")\n\t\t} else {\n\t\t\tremoteDateStr = \"<nil>\"\n\t\t}\n\n\t\tdiscrepancies[\"FNExpireDate\"] = events.DiscrepancyDetail{\n\t\t\tEtalonValue:      local.FNExpireDate.Format(\"2006-01-02\"),\n\t\t\tServiceDeskValue: remoteDateStr,\n\t\t}\n\t}\n\n\treturn discrepancies\n}\n",
    "pkg/eventbus/eventbus.go": "package eventbus\n\nimport (\n\t\"context\"\n\t\"sync\"\n\n\t\"go.uber.org/zap\"\n)\n\n// Event представляет собой событие, передаваемое по шине.\ntype Event struct {\n\tType    string      // Тип события, например, \"servicedesk.entity.updated\"\n\tPayload interface{} // Полезная нагрузка события\n}\n\n// EventHandler - это функция-обработчик для определенного типа события.\ntype EventHandler func(ctx context.Context, event Event)\n\n// DebugInfo содержит отладочную информацию о состоянии шины.\ntype DebugInfo struct {\n\tQueueLength    int                 `json:\"queue_length\"`\n\tQueueCapacity  int                 `json:\"queue_capacity\"`\n\tSubscribers    map[string]int      `json:\"subscribers\"` // Карта: eventType -> count of handlers\n}\n\n// EventBus определяет интерфейс для асинхронной шины событий.\ntype EventBus interface {\n\tPublish(event Event)\n\tSubscribe(eventType string, handler EventHandler)\n\tStart(ctx context.Context, logger *zap.Logger)\n\tGetDebugInfo() DebugInfo\n}\n\n// InMemoryEventBus - это реализация EventBus в памяти с использованием каналов Go.\ntype InMemoryEventBus struct {\n\tmu          sync.RWMutex\n\tsubscribers map[string][]EventHandler\n\tevents      chan Event\n\tlogger      *zap.Logger\n}\n\n// NewInMemoryEventBus создает новый экземпляр InMemoryEventBus.\nfunc NewInMemoryEventBus(bufferSize int) *InMemoryEventBus {\n\treturn &InMemoryEventBus{\n\t\tsubscribers: make(map[string][]EventHandler),\n\t\tevents:      make(chan Event, bufferSize),\n\t}\n}\n\n// Publish отправляет событие в шину. Метод неблокирующий.\nfunc (b *InMemoryEventBus) Publish(event Event) {\n\t// Логируем событие ПЕРЕД отправкой в канал\n\tif b.logger != nil {\n\t\tb.logger.Debug(\"Публикация события в шину\",\n\t\t\tzap.String(\"type\", event.Type),\n\t\t\tzap.Int(\"queue_len\", len(b.events)),      // Текущая длина очереди\n\t\t\tzap.Int(\"queue_cap\", cap(b.events)),      // Вместимость очереди\n\t\t)\n\t}\n\tb.events <- event\n}\n\n// Subscribe подписывает обработчик на определенный тип события.\nfunc (b *InMemoryEventBus) Subscribe(eventType string, handler EventHandler) {\n\tb.mu.Lock()\n\tdefer b.mu.Unlock()\n\tb.subscribers[eventType] = append(b.subscribers[eventType], handler)\n}\n\n// GetDebugInfo возвращает отладочную информацию о текущем состоянии шины.\nfunc (b *InMemoryEventBus) GetDebugInfo() DebugInfo {\n\tb.mu.RLock()\n\tdefer b.mu.RUnlock()\n\n\tsubs := make(map[string]int)\n\tfor eventType, handlers := range b.subscribers {\n\t\tsubs[eventType] = len(handlers)\n\t}\n\n\treturn DebugInfo{\n\t\tQueueLength:    len(b.events),\n\t\tQueueCapacity:  cap(b.events),\n\t\tSubscribers:    subs,\n\t}\n}\n\n// Start запускает основной цикл обработки событий.\nfunc (b *InMemoryEventBus) Start(ctx context.Context, logger *zap.Logger) {\n\tb.logger = logger // Сохраняем логгер\n\tlogger.Info(\"Шина событий запущена и готова к обработке.\")\n\tfor {\n\t\tselect {\n\t\tcase event := <-b.events:\n\t\t\tb.logger.Debug(\"Шина извлекла событие из очереди для обработки\", zap.String(\"type\", event.Type))\n\t\t\t\n\t\t\tb.mu.RLock()\n\t\t\thandlers, ok := b.subscribers[event.Type]\n\t\t\tb.mu.RUnlock()\n\n\t\t\tif ok {\n\t\t\t\tfor _, handler := range handlers {\n\t\t\t\t\tgo handler(ctx, event)\n\t\t\t\t}\n\t\t\t}\n\t\tcase <-ctx.Done():\n\t\t\tlogger.Info(\"Шина событий останавливается.\")\n\t\t\tclose(b.events)\n\t\t\treturn\n\t\t}\n\t}\n}",
}

